VALUES ('biology', '13-15', 'beginner', '初三', '人体呼吸系统中，气体交换的主要场所是？', [{"label": "A", "text": "鼻腔"}, {"label": "B", "text": "气管"}, {"label": "C", "text": "支气管"}, {"label": "D", "text": "肺泡"}], 'D', '肺泡是肺内气体交换的主要场所，其壁薄且周围有丰富的毛细血管，有利于气体交换。', 'single_choice', ARRAY['人体生理','呼吸系统','气体交换'], 'ai_generated', 'batch_biology_13-15_supplement_20260715184405');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '13-15', 'beginner', '初三', '下列哪些器官属于消化系统？（多选）', [{"label": "A", "text": "口腔"}, {"label": "B", "text": "食道"}, {"label": "C", "text": "心脏"}, {"label": "D", "text": "肝脏"}], 'ABD', '消化系统包括口腔、食道、胃、小肠、大肠、肝、胰等器官。心脏属于循环系统。', 'multiple_choice', ARRAY['人体生理','消化系统','器官识别'], 'ai_generated', 'batch_biology_13-15_supplement_20260715184405');
