INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '13-15', 'beginner', '初三', '简述食物在口腔中的消化过程。', NULL, '食物在口腔中被牙齿咀嚼磨碎，舌搅拌，唾液中的唾液淀粉酶将淀粉初步分解为麦芽糖，形成食团，经咽、食管进入胃。', '口腔消化包括物理性消化（咀嚼、搅拌）和化学性消化（唾液淀粉酶作用）。', 'short_answer', ARRAY['人体生理','消化系统','口腔消化'], 'ai_generated', 'batch_biology_13-15_supplement_20260715184405');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
