INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '13-15', 'beginner', '初三', '请简述基因、DNA和染色体之间的关系。', NULL, '染色体由DNA和蛋白质组成，DNA是主要的遗传物质，基因是有遗传效应的DNA片段，一条染色体上有多个基因。', '染色体是遗传物质的载体，DNA是遗传物质，基因是DNA上的功能片段。', 'short_answer', ARRAY['遗传变异','基因','DNA'], 'ai_generated', 'batch_biology_13-15_supplement_20260715184405');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '13-15', 'beginner', '初三', '生物体所有性状都是由基因决定的。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '错误', '性状由基因和环境共同决定，例如人的身高受基因影响，但也受营养等环境因素影响。', 'true_false', ARRAY['遗传变异','基因与环境'], 'ai_generated', 'batch_biology_13-15_supplement_20260715184405');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '13-15', 'beginner', '初三', '亲代的性状是通过________传递给子代的。', NULL, '生殖细胞（或基因）', '亲代通过生殖细胞将基因传递给子代，从而控制子代的性状。', 'fill_blank', ARRAY['遗传变异','遗传的传递'], 'ai_generated', 'batch_biology_13-15_supplement_20260715184405');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
