INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高三', '温度过高会导致酶的空间结构破坏，使酶永久失活。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], 'A', '高温会破坏酶的空间结构（变性），且这种破坏是不可逆的；低温只抑制酶活性，不破坏结构。', 'true_false', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高三', '伴性遗传的基因不遵循孟德尔的分离定律。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], 'B', '伴性遗传的基因仍遵循孟德尔的分离定律，只是这些基因位于性染色体上，其遗传与性别相关联。', 'true_false', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高三', '位于非同源染色体上的非等位基因在形成配子时自由组合。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], 'A', '自由组合定律的实质是减数第一次分裂后期，非同源染色体上的非等位基因随非同源染色体的自由组合而组合。', 'true_false', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高三', '生态系统中能量金字塔一定是正金字塔，数量金字塔和生物量金字塔可能出现倒金字塔。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], 'A', '能量金字塔一定是正金字塔（能量逐级递减）；数量金字塔可能出现倒金字塔（如一棵大树上生活着大量昆虫）；生物量金字塔也可能出现倒金字塔（如海洋浮游生物）。', 'true_false', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高三', '检测目的基因是否表达出蛋白质，可采用DNA分子杂交技术。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], 'B', '检测蛋白质应采用抗原-抗体杂交技术；DNA分子杂交用于检测目的基因是否导入或转录。', 'true_false', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高三', '比较有氧呼吸和无氧呼吸的异同点。', NULL, '相同点：第一阶段相同，都在细胞质基质中进行，将葡萄糖分解为丙酮酸，都释放少量能量。不同点：有氧呼吸需要氧气，将有机物彻底氧化分解为CO₂和H₂O，释放大量能量，主要在线粒体中进行；无氧呼吸不需要氧气，分解不彻底，产物为乳酸或酒精和CO₂，释放少量能量，全程在细胞质基质中进行。', '有氧呼吸和无氧呼吸的第一阶段相同，但后续阶段在场所、条件和产物上有显著差异。', 'short_answer', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高三', '简述孟德尔第一定律（分离定律）的内容及其实质。', NULL, '内容：在生物的体细胞中，控制同一性状的遗传因子成对存在，不相融合；在形成配子时，成对的遗传因子发生分离，分离后的遗传因子分别进入不同的配子中，随配子遗传给后代。实质：减数分裂时，等位基因随同源染色体的分开而分离，分别进入不同配子。', '分离定律描述了一对相对性状的遗传规律，其核心是等位基因的分离。', 'short_answer', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高三', '比较生态系统的抵抗力稳定性和恢复力稳定性，并举例说明。', NULL, '抵抗力稳定性是生态系统抵抗外界干扰并保持原状的能力；恢复力稳定性是生态系统受干扰后恢复原状的能力。两者通常呈负相关。例如，森林生态系统生物种类多、营养结构复杂，抵抗力稳定性高但恢复力稳定性低；农田生态系统抵抗力稳定性低但恢复力稳定性高。', '抵抗力稳定性和恢复力稳定性通常相反，与生态系统的复杂程度有关。', 'short_answer', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下图表示某植物在不同光照强度下的光合速率曲线，b点表示？', [{"label": "A", "text": "光补偿点"}, {"label": "B", "text": "光饱和点"}, {"label": "C", "text": "CO₂补偿点"}, {"label": "D", "text": "呼吸速率"}], 'A', 'b点为光补偿点，此时光合速率等于呼吸速率，净光合速率为零。', 'single_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '某同学在进行绿叶中色素的提取和分离实验时，滤纸条上最宽的色素带呈？', [{"label": "A", "text": "橙黄色"}, {"label": "B", "text": "黄色"}, {"label": "C", "text": "蓝绿色"}, {"label": "D", "text": "黄绿色"}], 'C', '滤纸条上最宽的色素带是叶绿素a，呈蓝绿色，因为叶绿素a在绿叶中含量最高。', 'single_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '将一植物叶片在黑暗中放置一段时间后，用真空渗入法将其放入含¹⁴C标记的NaHCO₃溶液中，光照一段时间后，放射性首先出现在？', [{"label": "A", "text": "C₅"}, {"label": "B", "text": "C₃"}, {"label": "C", "text": "葡萄糖"}, {"label": "D", "text": "淀粉"}], 'B', '¹⁴C标记的CO₂首先与C₅结合生成C₃，因此放射性首先出现在C₃中，随后出现在葡萄糖和淀粉中。', 'single_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '关于细胞呼吸原理在生产中的应用，错误的是？', [{"label": "A", "text": "中耕松土可促进根部有氧呼吸"}, {"label": "B", "text": "低温储存水果可降低呼吸速率"}, {"label": "C", "text": "水稻田定期排水可防止烂根"}, {"label": "D", "text": "透气性差的创可贴可促进细胞呼吸"}], 'D', '透气性好的创可贴才能为伤口愈合提供充足氧气，促进细胞呼吸；透气性差会导致厌氧菌繁殖。', 'single_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于ATP-ADP循环的叙述，错误的是？', [{"label": "A", "text": "ATP水解与合成分别释放和储存能量"}, {"label": "B", "text": "ATP水解酶的活性受温度影响"}, {"label": "C", "text": "ATP合成只发生在线粒体中"}, {"label": "D", "text": "ATP与ADP的转化速率很快"}], 'C', 'ATP合成不仅在线粒体中进行，还在叶绿体（光合作用）和细胞质基质（细胞呼吸第一阶段）中进行。', 'single_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于基因突变和染色体变异的叙述，正确的是？', [{"label": "A", "text": "基因突变一定会改变生物的表现型"}, {"label": "B", "text": "染色体结构变异中的缺失和重复可在显微镜下观察到"}, {"label": "C", "text": "单倍体只含有一个染色体组"}, {"label": "D", "text": "多倍体植株都是不育的"}], 'B', '染色体结构变异可在显微镜下观察；基因突变不一定改变表现型（如隐性突变、密码子简并性）；单倍体可含多个染色体组（如四倍体的单倍体含2个组）；多倍体如四倍体是可育的。', 'single_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '某植物果实形状由两对等位基因控制，只有双显性时才表现为圆形，其余为长形。让双杂合子自交，F₂中圆形与长形的比例为？', [{"label": "A", "text": "9:7"}, {"label": "B", "text": "9:3:3:1"}, {"label": "C", "text": "15:1"}, {"label": "D", "text": "3:1"}], 'A', 'A_B_为圆形（9/16），A_bb、aaB_、aabb为长形（7/16），比例为9:7，属于互补作用。', 'single_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于遗传系谱图的分析，正确的是？', [{"label": "A", "text": "双亲正常子代患病必为隐性遗传"}, {"label": "B", "text": "女患者的父亲和儿子都患病必为伴X显性遗传"}, {"label": "C", "text": "男患者的母亲和女儿都患病必为伴X隐性遗传"}, {"label": "D", "text": "代代相传的遗传病必为显性遗传"}], 'A', '双亲正常子代患病，说明致病基因为隐性（无中生有为隐性）；B应为伴X隐性；C应为伴X显性；D代代相传不一定是显性，也可能是显性。', 'single_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '鸡的性别决定方式为ZW型，芦花（B）对非芦花（b）为显性，基因位于Z染色体上。让非芦花雄鸡（ZbZb）与芦花雌鸡（ZBW）交配，F₁中芦花鸡所占比例为？', [{"label": "A", "text": "1/4"}, {"label": "B", "text": "1/2"}, {"label": "C", "text": "3/4"}, {"label": "D", "text": "1"}], 'B', 'ZbZb×ZBW后代为ZBZb（芦花雄）和ZbW（非芦花雌），芦花鸡占1/2。', 'single_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '某植物的花色和花型由两对独立遗传的基因控制。让双杂合子（AaBb）自交，F₂中表现型与亲本不同的个体占？', [{"label": "A", "text": "1/16"}, {"label": "B", "text": "3/8"}, {"label": "C", "text": "7/16"}, {"label": "D", "text": "9/16"}], 'C', '若亲本为AABB和aabb，F₂中与亲本相同的表现型为A_B_（9/16）和aabb（1/16），共10/16，不同的占6/16=3/8；但若亲本为AAbb和aaBB，则不同为7/16。题目未说明亲本，默认双显和双隐为亲本，不同占7/16。', 'single_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于种群、群落和生态系统的叙述，正确的是？', [{"label": "A", "text": "种群是同一区域所有生物的集合"}, {"label": "B", "text": "群落是同一区域同种生物的集合"}, {"label": "C", "text": "生态系统包括生物群落和无机环境"}, {"label": "D", "text": "种群密度能反映种群数量的变化趋势"}], 'C', '种群是同一区域同种生物的集合；群落是同一区域所有生物的集合；种群密度不能反映数量变化趋势，年龄组成才能。', 'single_choice', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于生态系统能量传递效率的叙述，正确的是？', [{"label": "A", "text": "能量传递效率是10%-20%"}, {"label": "B", "text": "能量传递效率是固定的10%"}, {"label": "C", "text": "能量传递效率是指相邻营养级间的同化量比"}, {"label": "D", "text": "能量传递效率可以人为提高到50%"}], 'C', '能量传递效率是指相邻两个营养级同化量的比值，大约为10%-20%，不是固定值，也不能人为大幅提高。', 'single_choice', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于生物地球化学循环的叙述，错误的是？', [{"label": "A", "text": "碳循环、氮循环、硫循环都属于生物地球化学循环"}, {"label": "B", "text": "物质循环具有全球性"}, {"label": "C", "text": "物质在生物群落和无机环境之间循环"}, {"label": "D", "text": "物质循环只在陆地生态系统中进行"}], 'D', '物质循环具有全球性，不仅在陆地，也在海洋等生态系统中进行，是全球范围内的循环。', 'single_choice', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于群落演替的叙述，正确的是？', [{"label": "A", "text": "群落演替最终都会形成森林"}, {"label": "B", "text": "初生演替和次生演替的起始条件相同"}, {"label": "C", "text": "人类活动会影响群落演替的速度和方向"}, {"label": "D", "text": "演替过程中群落结构越来越简单"}], 'C', '人类活动会影响演替的速度和方向；演替不一定形成森林（受气候限制）；初生演替从无植被开始，次生演替从有土壤和繁殖体开始；演替过程中群落结构一般越来越复杂。', 'single_choice', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '某种群数量增长的J型曲线出现的条件是？', [{"label": "A", "text": "食物和空间充裕、气候适宜、没有天敌"}, {"label": "B", "text": "食物和空间有限、存在天敌"}, {"label": "C", "text": "种群密度增大时种内斗争加剧"}, {"label": "D", "text": "资源和空间有限"}], 'A', 'J型增长出现在理想条件下：食物和空间充裕、气候适宜、没有天敌等；S型增长出现在资源和空间有限的自然条件下。', 'single_choice', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
