INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于cDNA文库和基因组文库的叙述，正确的是？', [{"label": "A", "text": "cDNA文库含有该生物的全部基因"}, {"label": "B", "text": "基因组文库只含有编码蛋白质的基因"}, {"label": "C", "text": "cDNA文库不含启动子和内含子"}, {"label": "D", "text": "基因组文库中的基因不能在原核生物中表达"}], 'C', 'cDNA由mRNA反转录而来，不含启动子、内含子等非编码序列；基因组文库含有该生物的全部基因（包括非编码区）。', 'single_choice', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于基因治疗的说法，正确的是？', [{"label": "A", "text": "基因治疗可以治愈所有遗传病"}, {"label": "B", "text": "基因治疗是将正常基因导入患者体内有缺陷的细胞中"}, {"label": "C", "text": "基因治疗只能治疗体细胞遗传病"}, {"label": "D", "text": "基因治疗已经被广泛应用于临床"}], 'B', '基因治疗是将正常基因导入患者体内有缺陷的细胞中，以纠正或补偿缺陷基因；目前仍处于研究阶段，应用有限；可针对体细胞和生殖细胞（伦理争议大）。', 'single_choice', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
