INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '利用农杆菌转化法将目的基因导入植物细胞时，Ti质粒上的T-DNA的特点是？', [{"label": "A", "text": "可自主复制"}, {"label": "B", "text": "可转移至受体细胞并整合到染色体DNA上"}, {"label": "C", "text": "含有抗生素抗性基因"}, {"label": "D", "text": "可在农杆菌中表达目的基因"}], 'B', 'Ti质粒上的T-DNA（可转移DNA）可以从农杆菌转移至植物细胞，并整合到植物染色体DNA中，是农杆菌转化法的核心。', 'single_choice', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于呼吸作用在生产实践中应用的叙述，正确的是？（多选）', [{"label": "A", "text": "蔬菜和水果应储存在低温、低氧环境中"}, {"label": "B", "text": "中耕松土有利于根系有氧呼吸和吸收矿质元素"}, {"label": "C", "text": "剧烈运动时人体肌肉细胞同时进行有氧和无氧呼吸"}, {"label": "D", "text": "酿制葡萄酒时利用酵母菌的有氧呼吸"}, {"label": "E", "text": "包扎伤口应选用透气的敷料"}], 'ABCE', '低温低氧可降低呼吸速率，延长保鲜期；中耕松土增加土壤含氧量；剧烈运动时肌肉缺氧会进行无氧呼吸产生乳酸；酿酒利用酵母菌无氧呼吸；透气敷料可抑制厌氧菌繁殖。', 'multiple_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于叶绿体色素的叙述，正确的是？（多选）', [{"label": "A", "text": "叶绿素主要吸收红光和蓝紫光"}, {"label": "B", "text": "类胡萝卜素主要吸收蓝紫光"}, {"label": "C", "text": "色素分布在类囊体薄膜上"}, {"label": "D", "text": "叶绿素b呈黄绿色"}, {"label": "E", "text": "所有色素都参与光反应中ATP的合成"}], 'ABCD', '叶绿素a和b主要吸收红光和蓝紫光；类胡萝卜素主要吸收蓝紫光；四种色素都分布在类囊体薄膜上；叶绿素b呈黄绿色；并非所有色素都直接参与ATP合成，但都能吸收和传递光能。', 'multiple_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列杂交组合中，后代能出现1:1:1:1表现型比例的有？（多选）', [{"label": "A", "text": "AaBb×aabb"}, {"label": "B", "text": "AaBb×Aabb"}, {"label": "C", "text": "Aabb×aaBb"}, {"label": "D", "text": "AaBb×aaBB"}, {"label": "E", "text": "Aabb×aabb"}], 'AC', '1:1:1:1比例需双亲各产生两种比例相等的配子且组合后表现型不同。AaBb×aabb（测交）和Aabb×aaBb均可产生1:1:1:1的表现型比例。', 'multiple_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '关于遗传病预防措施的叙述，正确的是？（多选）', [{"label": "A", "text": "禁止近亲结婚可降低隐性遗传病的发病率"}, {"label": "B", "text": "遗传咨询可估算后代患病风险"}, {"label": "C", "text": "产前诊断可检测胎儿是否患染色体异常遗传病"}, {"label": "D", "text": "基因治疗可治愈所有遗传病"}, {"label": "E", "text": "适龄生育可降低染色体异常遗传病的发生率"}], 'ABCE', '禁止近亲结婚降低隐性遗传病风险；遗传咨询可评估风险；产前诊断可检测染色体异常；基因治疗目前只能治疗部分遗传病；适龄生育可降低染色体异常风险。', 'multiple_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于群落结构的叙述，正确的是？（多选）', [{"label": "A", "text": "群落具有垂直结构和水平结构"}, {"label": "B", "text": "植物的垂直分层为动物创造了多样的栖息空间"}, {"label": "C", "text": "水平结构受地形、土壤湿度、光照等因素影响"}, {"label": "D", "text": "群落的季节性变化也属于群落结构"}, {"label": "E", "text": "垂直分层越复杂，光能利用率越高"}], 'ABCDE', '群落有垂直和水平结构；植物垂直分层为动物提供栖息空间和食物；水平结构受多种环境因素影响；季节性变化是时间结构；垂直分层复杂有利于提高光能利用率。', 'multiple_choice', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
