INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高三', '关于光合作用和细胞呼吸中[H]的叙述，正确的是？（多选）', [{"label": "A", "text": "光合作用中的[H]是NADPH"}, {"label": "B", "text": "细胞呼吸中的[H]是NADH和FADH₂"}, {"label": "C", "text": "光合作用中的[H]用于还原C₃"}, {"label": "D", "text": "细胞呼吸中的[H]与O₂结合生成水"}, {"label": "E", "text": "两者中的[H]是同一种物质"}], 'ABCD', '光合作用中的[H]指NADPH，用于暗反应还原C₃；细胞呼吸中的[H]包括NADH和FADH₂，在线粒体内膜与O₂结合生成水；两者不是同一种物质。', 'multiple_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高三', '下列实验方法或技术的叙述，正确的是？（多选）', [{"label": "A", "text": "纸层析法分离色素的原理是不同色素在层析液中溶解度不同"}, {"label": "B", "text": "同位素示踪法可用于追踪物质的转移途径"}, {"label": "C", "text": "对照实验是科学探究中常用的方法"}, {"label": "D", "text": "显微观察法可直接观察细胞内的代谢过程"}, {"label": "E", "text": "比色法可用于测定酶活性"}], 'ABCE', '纸层析法利用色素在层析液中溶解度不同而分离；同位素示踪可追踪物质转移；对照实验是基本方法；显微观察不能直接观察代谢过程；比色法可通过检测产物或底物浓度变化测定酶活性。', 'multiple_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高三', '下列育种方法中，能打破物种界限获得新性状的有？（多选）', [{"label": "A", "text": "杂交育种"}, {"label": "B", "text": "诱变育种"}, {"label": "C", "text": "单倍体育种"}, {"label": "D", "text": "多倍体育种"}, {"label": "E", "text": "基因工程育种"}], 'BE', '杂交育种只能在同种或近缘种间进行；诱变育种产生新基因但不跨物种；单倍体育种和多倍体育种不跨物种；只有基因工程育种可将外源基因导入，打破物种界限。', 'multiple_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高三', '下列关于基因连锁和交换的叙述，正确的是？（多选）', [{"label": "A", "text": "连锁基因位于同一对同源染色体上"}, {"label": "B", "text": "交换发生在减数第一次分裂前期"}, {"label": "C", "text": "交换率越大，基因间距离越远"}, {"label": "D", "text": "完全连锁时测交后代只有两种表现型"}, {"label": "E", "text": "交换率等于50%时基因独立遗传"}], 'ABCDE', '连锁基因在同源染色体上；交换发生在减Ⅰ前期（四分体时期）；交换率反映基因间距离；完全连锁时无交换，测交后代只有两种；交换率为50%时相当于独立遗传。', 'multiple_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
