INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高三', '请设计实验探究温度对淀粉酶活性的影响，写出实验原理、材料用具、方法步骤和结果分析。', NULL, '原理：淀粉酶催化淀粉水解，碘液遇淀粉变蓝，可根据蓝色深浅判断淀粉剩余量，进而反映酶活性。步骤：①取若干支试管，分别加入等量淀粉溶液；②将试管分组置于0℃、20℃、40℃、60℃、80℃水浴中保温5分钟；③向各试管加入等量淀粉酶溶液，在相应温度下反应10分钟；④加入碘液观察颜色变化。结果分析：40℃左右蓝色最浅（淀粉水解最彻底），说明该温度下酶活性最高；0℃和80℃蓝色较深，说明低温抑制酶活性、高温使酶失活。', '通过碘液检测淀粉剩余量来反映不同温度下淀粉酶的活性，注意控制变量和预保温。', 'short_answer', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高三', '某实验室要培育能稳定遗传的矮秆抗病（aaBB）水稻品种。现有高秆抗病（AABB）和矮秆感病（aabb）两个纯合品种，请设计育种方案并说明各步骤的目的。', NULL, '方案（杂交育种）：①杂交：AABB×aabb→F₁（AaBb），将两个亲本的优良性状组合在一起；②自交：F₁自交得F₂，出现性状重组；③筛选：从F₂中选出矮秆抗病（aaB_）个体；④连续自交并筛选：淘汰杂合子，直至不发生性状分离，获得稳定遗传的aaBB品种。若需缩短年限，可在F₁花药离体培养获得单倍体后，用秋水仙素加倍，再筛选。', '杂交育种通过杂交、自交和筛选获得稳定遗传的优良品种，单倍体育种可缩短育种年限。', 'short_answer', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高三', '请结合生态学原理，论述如何实现农业生态系统的可持续发展。', NULL, '实现农业生态系统可持续发展的措施：①物种多样性原理：增加农田物种多样性，如间作、套种、轮作，提高生态系统稳定性；②物质循环再生原理：建立无废弃物农业，如秸秆还田、沼气发酵，实现物质循环利用；③协调与平衡原理：合理施肥灌溉，避免水体富营养化；④整体性原理：兼顾生态效益、经济效益和社会效益；⑤系统学和工程学原理：优化农业生态系统的结构，改善功能。', '农业可持续发展需要综合运用生态学原理，实现经济、生态和社会效益的统一。', 'short_answer', ARRAY['生态系统稳态'], 'ai_generated', '');
