INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '13-15', 'beginner', '初三', '关于分子和原子的说法，正确的是？', [{"label": "A", "text": "分子大原子小"}, {"label": "B", "text": "分子可分原子不可分"}, {"label": "C", "text": "分子是保持物质化学性质的最小粒子"}, {"label": "D", "text": "原子不能构成物质"}], 'C', '分子是保持物质化学性质的最小粒子；不同分子和原子大小不能简单比较；在化学变化中分子可分原子不可分；原子可以直接构成物质。', 'single_choice', ARRAY['物质构成','分子','原子'], 'ai_generated', 'batch_chemistry_13-15_20260715173201');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
