INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '13-15', 'beginner', '初三', '请简述分子与原子的主要区别。', NULL, '分子是保持物质化学性质的最小粒子，在化学变化中可以再分；原子是化学变化中的最小粒子，在化学变化中不能再分。', '分子与原子的本质区别：在化学变化中，分子可以再分，而原子不能再分。', 'short_answer', ARRAY['物质构成','分子','原子'], 'ai_generated', 'batch_chemistry_13-15_20260715173201');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '13-15', 'beginner', '初三', '为什么氯化钠固体不导电，而氯化钠溶液能导电？', NULL, '氯化钠固体中钠离子和氯离子不能自由移动，因此不导电；氯化钠溶于水后，钠离子和氯离子脱离晶体表面，可以自由移动，因此溶液能导电。', '物质导电需要有能自由移动的带电粒子。固体氯化钠中离子不能自由移动，溶液中离子可以自由移动。', 'short_answer', ARRAY['物质构成','离子','导电性'], 'ai_generated', 'batch_chemistry_13-15_20260715173201');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '13-15', 'intermediate', '初三', '化学方程式2H2+O2═2H2O中，参加反应的氢气、氧气和生成水的质量比为？', [{"label": "A", "text": "2:1:2"}, {"label": "B", "text": "1:8:9"}, {"label": "C", "text": "4:32:36"}, {"label": "D", "text": "1:1:1"}], 'B', '质量比 = (2×2) : (16×2) : (18×2) = 4:32:36 = 1:8:9。', 'single_choice', ARRAY['化学方程式','质量比'], 'ai_generated', 'batch_chemistry_13-15_20260715173201');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '13-15', 'intermediate', '初三', '下列化学方程式书写正确的是？', [{"label": "A", "text": "2Fe+6HCl═2FeCl3+3H2↑"}, {"label": "B", "text": "Fe+2HCl═FeCl2+H2↑"}, {"label": "C", "text": "Cu+H2SO4═CuSO4+H2↑"}, {"label": "D", "text": "2Ag+2HCl═2AgCl+H2↑"}], 'B', '铁与盐酸反应生成氯化亚铁和氢气；铜和银在金属活动性顺序中位于氢后，不能与稀盐酸反应。', 'single_choice', ARRAY['化学方程式','金属活动性'], 'ai_generated', 'batch_chemistry_13-15_20260715173201');
