INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '13-15', 'intermediate', '初三', '加热分解12.25g氯酸钾(KClO3)，理论上可制得氧气多少克？', [{"label": "A", "text": "3.2g"}, {"label": "B", "text": "4.8g"}, {"label": "C", "text": "9.6g"}, {"label": "D", "text": "12.25g"}], 'B', '2KClO3═2KCl+3O2↑，245份质量KClO3生成96份质量O2，12.25g KClO3生成(96/245)×12.25=4.8g O2。', 'single_choice', ARRAY['化学方程式','计算'], 'ai_generated', 'batch_chemistry_13-15_20260715173201');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '13-15', 'intermediate', '初三', '在化学反应A+B═C+D中，若12g A与16g B恰好完全反应，生成8g C，则生成D的质量为？', [{"label": "A", "text": "20g"}, {"label": "B", "text": "28g"}, {"label": "C", "text": "36g"}, {"label": "D", "text": "4g"}], 'A', '根据质量守恒定律，参加反应的各物质质量总和等于生成的各物质质量总和，m(D)=12+16-8=20g。', 'single_choice', ARRAY['化学方程式','质量守恒定律'], 'ai_generated', 'batch_chemistry_13-15_20260715173201');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
