INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '13-15', 'advanced', '初三', '紫色石蕊试液遇酸变______色，遇碱变______色；无色酚酞试液遇酸______色，遇碱变______色。', NULL, '红；蓝；不变（或无）；红', '石蕊遇酸变红、遇碱变蓝；酚酞遇酸不变色、遇碱变红。', 'fill_blank', ARRAY['酸碱盐','指示剂'], 'ai_generated', 'batch_chemistry_13-15_20260715173201');
