INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '13-15', 'advanced', '初三', '如何鉴别稀盐酸和稀硫酸？请写出实验步骤、现象和结论。', NULL, '分别取少量待测液于两支试管中，各滴加少量氯化钡溶液。产生白色沉淀的是稀硫酸（BaCl2+H2SO4═BaSO4↓+2HCl），无明显现象的是稀盐酸。', '利用硫酸根离子与钡离子生成白色硫酸钡沉淀的特征反应来鉴别稀硫酸和稀盐酸。', 'short_answer', ARRAY['酸碱盐','鉴别'], 'ai_generated', 'batch_chemistry_13-15_20260715173201');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '13-15', 'advanced', '初三', '请设计实验方案，证明氢氧化钠溶液与稀盐酸发生了中和反应。', NULL, '方案：向氢氧化钠溶液中滴加几滴酚酞试液，溶液变红；再逐滴加入稀盐酸，边加边搅拌，至溶液刚好变为无色，说明NaOH已被HCl完全中和。原理：酚酞在碱性溶液中呈红色，在中性或酸性溶液中无色，颜色变化证明反应发生。', '利用酸碱指示剂的颜色变化来证明中和反应的发生，酚酞是常用的指示剂。', 'short_answer', ARRAY['酸碱盐','中和反应','实验设计'], 'ai_generated', 'batch_chemistry_13-15_20260715173201');
