INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '16-18', 'beginner', '高三', '请简述勒夏特列原理，并举例说明其在化学平衡移动中的应用。', NULL, '勒夏特列原理：如果改变影响平衡的一个条件（如浓度、压强或温度），平衡将向着能够减弱这种改变的方向移动。例如，对于N₂+3H₂⇌2NH₃，增大压强，平衡向正反应方向移动（气体分子数减少的方向），以减弱压强的增大。', '准确表述原理并举例说明。', 'short_answer', ARRAY['反应速率与平衡'], 'ai_generated', 'chemistry_16-18_supplement');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '16-18', 'beginner', '高三', '请分析为什么强酸弱碱盐溶液呈酸性，强碱弱酸盐溶液呈碱性。', NULL, '强酸弱碱盐中，弱碱阳离子水解结合水电离出的OH⁻，使溶液中c(H⁺)>c(OH⁻)，溶液呈酸性；强碱弱酸盐中，弱酸根阴离子水解结合水电离出的H⁺，使溶液中c(OH⁻)>c(H⁺)，溶液呈碱性。', '从离子水解的角度分析溶液酸碱性的成因。', 'short_answer', ARRAY['弱电解质/盐类水解'], 'ai_generated', 'chemistry_16-18_supplement');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chemistry', '16-18', 'beginner', '高三', '请说明原电池和电解池在原理、能量转化和电极反应方面的区别。', NULL, '原电池：自发进行氧化还原反应，化学能转化为电能，负极氧化、正极还原；电解池：在外加电源作用下进行氧化还原反应，电能转化为化学能，阳极氧化、阴极还原。', '从原理、能量转化、电极反应三方面比较。', 'short_answer', ARRAY['氧化还原/电化学'], 'ai_generated', 'chemistry_16-18_supplement');
