INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'beginner', '高三', '下列句子中，加点词的意义和用法相同的一组是（ ）', [{"label": "A", "text": "①项王即日因留沛公与饮 ②因击沛公于坐"}, {"label": "B", "text": "①若属皆且为所虏 ②且为之奈何"}, {"label": "C", "text": "①臣死且不避 ②不者，若属皆且为所虏"}, {"label": "D", "text": "①项伯乃夜驰之沛公军 ②今者有小人之言"}], 'A', 'A项两个“因”均为“趁机”；B项①“为”表被动，②“为”动词，对待；C项①“且”尚且，②“且”将要；D项①“之”动词，到，②“之”助词，的。', 'single_choice', ARRAY['古文翻译','史传'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'beginner', '高三', '下列对文中词语的相关内容的解说，不正确的一项是（ ）', [{"label": "A", "text": "“左司马”是官名，掌管军政，秦汉时期在右司马之上。"}, {"label": "B", "text": "“关中”指函谷关以西地区，今陕西一带。"}, {"label": "C", "text": "“季父”指叔父，古代兄弟排行以伯、仲、叔、季为序。"}, {"label": "D", "text": "“婚姻”指儿女亲家，女方的父亲为婚，男方的父亲为姻。"}], 'A', '秦汉时期，右司马地位高于左司马。', 'single_choice', ARRAY['文学常识','史传'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'beginner', '高三', '下列句子中，加点词的解释正确的一项是（ ）', [{"label": "A", "text": "纵一苇之所如（如：像）"}, {"label": "B", "text": "凌万顷之茫然（凌：越过）"}, {"label": "C", "text": "浩浩乎如冯虚御风（冯：同“凭”，乘）"}, {"label": "D", "text": "正襟危坐而问客曰（危：危险）"}], 'C', 'A项“如”意为“往”；B项“凌”意为“乘”；D项“危”意为“端正”。', 'single_choice', ARRAY['古文翻译','游记'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
