INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'beginner', '高三', '下列对《赤壁赋》中语句的理解，不正确的一项是（ ）', [{"label": "A", "text": "“寄蜉蝣于天地”比喻人生短暂如蜉蝣寄身天地之间。"}, {"label": "B", "text": "“挟飞仙以遨游”表达与仙人同游的浪漫幻想。"}, {"label": "C", "text": "“知不可乎骤得”意为知道不可能轻易得到。"}, {"label": "D", "text": "“托遗响于悲风”指将悲苦寄托给秋风，表达豁达之情。"}], 'D', '“托遗响于悲风”表达的是悲凉无奈之情，非豁达。', 'single_choice', ARRAY['现代文深度阅读','散文'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'beginner', '高三', '下列对鲁迅《祝福》中人物形象的分析，不正确的一项是（ ）', [{"label": "A", "text": "祥林嫂是旧中国劳动妇女的典型，勤劳善良却命运悲惨。"}, {"label": "B", "text": "鲁四老爷是封建礼教的维护者，虚伪冷酷。"}, {"label": "C", "text": "柳妈是封建迷信的受害者，也是祥林嫂悲剧的间接推手。"}, {"label": "D", "text": "“我”是一个具有进步思想的知识分子，最终成功拯救了祥林嫂。"}], 'D', '“我”虽同情祥林嫂，但无力改变现实，并未拯救她。', 'single_choice', ARRAY['现代文深度阅读','小说'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'beginner', '高三', '下列诗句中，运用了比喻修辞手法的一项是（ ）', [{"label": "A", "text": "大漠沙如雪，燕山月似钩。"}, {"label": "B", "text": "感时花溅泪，恨别鸟惊心。"}, {"label": "C", "text": "白发三千丈，缘愁似个长。"}, {"label": "D", "text": "问君能有几多愁？恰似一江春水向东流。"}], 'A', 'A项将沙比作雪，月比作钩；B项拟人；C项夸张；D项设问兼比喻，但题干要求“比喻”，A更直接。', 'single_choice', ARRAY['现代文深度阅读','诗歌鉴赏'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'beginner', '高三', '下列文学常识表述正确的一项是（ ）', [{"label": "A", "text": "《诗经》是我国第一部诗歌总集，收录了从西周到春秋时期的诗歌305篇。"}, {"label": "B", "text": "“四书”指《大学》《中庸》《论语》《孟子》，“五经”指《诗》《书》《礼》《易》《春秋》。"}, {"label": "C", "text": "鲁迅的《狂人日记》是中国现代文学史上第一篇白话小说，收录在小说集《彷徨》中。"}, {"label": "D", "text": "莎士比亚的四大悲剧是《哈姆雷特》《奥赛罗》《李尔王》《麦克白》。"}], 'B', 'A项《诗经》共305篇，说法正确但B项更全面；C项《狂人日记》收录于《呐喊》；D项四大悲剧正确，但题干要求选正确的一项，B项无误。', 'single_choice', ARRAY['文学常识','作家作品'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'beginner', '高三', '下列对《红楼梦》的表述，正确的有（ ）', [{"label": "A", "text": "《红楼梦》原名《石头记》，以贾、史、王、薛四大家族的兴衰为背景。"}, {"label": "B", "text": "林黛玉是贾母的外孙女，性格多愁善感，才华横溢。"}, {"label": "C", "text": "贾宝玉佩戴的通灵宝玉上刻有“莫失莫忘，仙寿恒昌”。"}, {"label": "D", "text": "王熙凤是贾琏之妻，精明能干，但心狠手辣，最终结局圆满。"}], 'ABC', 'D项王熙凤结局悲惨，并非圆满。', 'multiple_choice', ARRAY['文学常识','作家作品'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
