INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'intermediate', '高三', '判断下列说法的正误。
《红楼梦》中“世事洞明皆学问，人情练达即文章”是王熙凤的座右铭。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], 'B', '这句话出自《红楼梦》第五回，是宁国府上房内的一副对联，并非王熙凤的座右铭。', 'true_false', ARRAY['文学常识','小说'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
