INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'intermediate', '高三', '简答题：请简要分析《祝福》中“我”这一形象的作用。', NULL, '①“我”是故事的叙述者，通过“我”的所见所闻展现祥林嫂的悲剧；②“我”是一个具有进步思想的知识分子，对祥林嫂的遭遇充满同情，但又无力改变现实，反映了当时知识分子的软弱性；③“我”与鲁镇环境的对比，深化了反封建主题。', '从叙述视角、人物形象、主题表现三方面作答。', 'short_answer', ARRAY['现代文阅读','小说'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'intermediate', '高三', '简答题：请简要分析《阿房宫赋》中“秦人不暇自哀，而后人哀之；后人哀之而不鉴之，亦使后人而复哀后人也”这句话的含义及作用。', NULL, '①含义：秦人来不及为自己哀叹，而后人哀叹他们；后人哀叹他们却不以之为鉴，也会让更后来的人哀叹他们。②作用：总结全文，点明主旨，警示当朝统治者要以秦亡为鉴，避免重蹈覆辙。', '从句子翻译和主旨作用两方面作答。', 'short_answer', ARRAY['古文翻译','史传'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'advanced', '高三', '下列句子中，加点词的解释不正确的一项是（  ）
A. 沛公旦日从百余骑来见项王（从：使……跟从）
B. 范增数目项王（数：多次）
C. 若入前为寿（若：你）
D. 常以身翼蔽沛公（翼：翅膀）', [{"label": "A", "text": "沛公旦日从百余骑来见项王（从：使……跟从）"}, {"label": "B", "text": "范增数目项王（数：多次）"}, {"label": "C", "text": "若入前为寿（若：你）"}, {"label": "D", "text": "常以身翼蔽沛公（翼：翅膀）"}], 'D', '“翼”在此处为名词作状语，意为“像翅膀一样”，而非名词“翅膀”。', 'single_choice', ARRAY['古文翻译','史传'], 'ai_generated', 'chinese_16-18_complete');

-- Batch 9
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'advanced', '高三', '下列对《祝福》中“我”这一人物的分析，不正确的一项是（  ）
A. “我”是一个具有进步思想的知识分子
B. “我”对祥林嫂的遭遇充满同情，但无力改变
C. “我”是故事的叙述者，也是情节发展的推动者
D. “我”最终接受了鲁四老爷的观点，成为封建礼教的维护者', [{"label": "A", "text": "“我”是一个具有进步思想的知识分子"}, {"label": "B", "text": "“我”对祥林嫂的遭遇充满同情，但无力改变"}, {"label": "C", "text": "“我”是故事的叙述者，也是情节发展的推动者"}, {"label": "D", "text": "“我”最终接受了鲁四老爷的观点，成为封建礼教的维护者"}], 'D', '“我”并未接受鲁四老爷的观点，而是表现出对封建礼教的批判和无奈。', 'single_choice', ARRAY['现代文深度阅读','小说鉴赏'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'advanced', '高三', '下列文学常识表述正确的一项是（  ）
A. 屈原的《离骚》是我国古代最早的长篇叙事诗
B. 苏轼是宋代豪放派词人，代表作有《念奴娇·赤壁怀古》
C. 鲁迅的《狂人日记》是中国现代文学史上第一篇白话短篇小说
D. 莫泊桑是法国批判现实主义作家，被誉为“短篇小说之王”', [{"label": "A", "text": "屈原的《离骚》是我国古代最早的长篇叙事诗"}, {"label": "B", "text": "苏轼是宋代豪放派词人，代表作有《念奴娇·赤壁怀古》"}, {"label": "C", "text": "鲁迅的《狂人日记》是中国现代文学史上第一篇白话短篇小说"}, {"label": "D", "text": "莫泊桑是法国批判现实主义作家，被誉为“短篇小说之王”"}], 'C', 'A项《离骚》是抒情诗；B项苏轼是豪放派，但《念奴娇·赤壁怀古》是词，表述正确，但C项更准确，且D项莫泊桑是批判现实主义作家，但“短篇小说之王”通常指欧·亨利，莫泊桑是“世界短篇小说巨匠”。综合判断，C项无误。', 'single_choice', ARRAY['文学常识','作家作品'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'advanced', '高三', '下列句子中，没有语病的一项是（  ）
A. 通过这次社会实践活动，使我们开阔了眼界，增长了知识。
B. 为了防止不再发生类似的伤害事故，学校加强了安全教育。
C. 他的写作水平明显提高，这得益于他坚持阅读和练笔。
D. 能否刻苦学习，是取得优异成绩的关键。', [{"label": "A", "text": "通过这次社会实践活动，使我们开阔了眼界，增长了知识。"}, {"label": "B", "text": "为了防止不再发生类似的伤害事故，学校加强了安全教育。"}, {"label": "C", "text": "他的写作水平明显提高，这得益于他坚持阅读和练笔。"}, {"label": "D", "text": "能否刻苦学习，是取得优异成绩的关键。"}], 'C', 'A项缺少主语，删去“通过”或“使”；B项否定不当，删去“不”；D项两面对一面，删去“能否”。', 'single_choice', ARRAY['现代文深度阅读','病句辨析'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'advanced', '高三', '下列诗句中，运用了比拟修辞手法的一项是（  ）
A. 感时花溅泪，恨别鸟惊心。
B. 大漠沙如雪，燕山月似钩。
C. 不知细叶谁裁出，二月春风似剪刀。
D. 飞流直下三千尺，疑是银河落九天。', [{"label": "A", "text": "感时花溅泪，恨别鸟惊心。"}, {"label": "B", "text": "大漠沙如雪，燕山月似钩。"}, {"label": "C", "text": "不知细叶谁裁出，二月春风似剪刀。"}, {"label": "D", "text": "飞流直下三千尺，疑是银河落九天。"}], 'A', 'A项“花溅泪”“鸟惊心”赋予花、鸟以人的情感，是比拟（拟人）；B、C、D均为比喻。', 'single_choice', ARRAY['诗歌鉴赏','修辞手法'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'advanced', '高三', '下列对《滕王阁序》中“落霞与孤鹜齐飞，秋水共长天一色”的赏析，不正确的一项是（  ）
A. 运用对偶，句式工整
B. 动静结合，画面生动
C. 以“落霞”与“孤鹜”对比，突出孤寂
D. 意境开阔，色彩明丽', [{"label": "A", "text": "运用对偶，句式工整"}, {"label": "B", "text": "动静结合，画面生动"}, {"label": "C", "text": "以“落霞”与“孤鹜”对比，突出孤寂"}, {"label": "D", "text": "意境开阔，色彩明丽"}], 'C', '“落霞”与“孤鹜”并非对比，而是相互映衬，共同构成和谐画面。', 'single_choice', ARRAY['古文翻译','游记'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'advanced', '高三', '下列句子中，加点词的意义和用法相同的一组是（  ）
A. ①以其乃华山之阳名之也 ②今其智乃反不能及
B. ①其孰能讥之乎 ②吾其还也
C. ①既其出，则或咎其欲出者 ②而余亦悔其随之而不得极夫游之乐也
D. ①以故其后名之曰“褒禅” ②余与四人拥火以入', [{"label": "A", "text": "①以其乃华山之阳名之也 ②今其智乃反不能及"}, {"label": "B", "text": "①其孰能讥之乎 ②吾其还也"}, {"label": "C", "text": "①既其出，则或咎其欲出者 ②而余亦悔其随之而不得极夫游之乐也"}, {"label": "D", "text": "①以故其后名之曰“褒禅” ②余与四人拥火以入"}], 'C', 'C项两个“其”均为代词，指代自己；A项①“乃”表判断，②“乃”表转折；B项①“其”表反问，②“其”表商量；D项①“以”表原因，②“以”表目的。', 'single_choice', ARRAY['古文翻译','游记'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'advanced', '高三', '下列对《红楼梦》中人物判词的理解，不正确的一项是（  ）
A. “可叹停机德，堪怜咏絮才”对应林黛玉和薛宝钗
B. “富贵又何为，襁褓之间父母违”对应史湘云
C. “欲洁何曾洁，云空未必空”对应妙玉
D. “凡鸟偏从末世来，都知爱慕此生才”对应王熙凤', [{"label": "A", "text": "“可叹停机德，堪怜咏絮才”对应林黛玉和薛宝钗"}, {"label": "B", "text": "“富贵又何为，襁褓之间父母违”对应史湘云"}, {"label": "C", "text": "“欲洁何曾洁，云空未必空”对应妙玉"}, {"label": "D", "text": "“凡鸟偏从末世来，都知爱慕此生才”对应王熙凤"}], 'A', '“可叹停机德”指薛宝钗，“堪怜咏絮才”指林黛玉，但判词是合写二人，并非对应一人。', 'single_choice', ARRAY['文学常识','作家作品'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'advanced', '高三', '下列各句中，表达得体的一句是（  ）
A. 奉上拙作一部，敬请雅正。
B. 您的文章写得真好，本刊将予以刊登，稿费从优。
C. 既然你这么客气，那我就笑纳了。
D. 欢迎您莅临寒舍，我感到十分荣幸。', [{"label": "A", "text": "奉上拙作一部，敬请雅正。"}, {"label": "B", "text": "您的文章写得真好，本刊将予以刊登，稿费从优。"}, {"label": "C", "text": "既然你这么客气，那我就笑纳了。"}, {"label": "D", "text": "欢迎您莅临寒舍，我感到十分荣幸。"}], 'A', 'A项“拙作”谦称自己的作品，“雅正”敬辞，得体；B项“稿费从优”口语化，不正式；C项“笑纳”用于请人收下礼物，此处误用；D项“莅临”用于对方，此处“您莅临寒舍”搭配不当，应说“您光临寒舍”。', 'single_choice', ARRAY['应用文写作','书信'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'advanced', '高三', '下列对《阿Q正传》中“精神胜利法”的理解，不正确的一项是（  ）
A. 阿Q在失败时，通过想象自己胜利来获得心理安慰
B. 精神胜利法是阿Q性格的核心，体现其自欺欺人
C. 精神胜利法是当时中国国民性的普遍弱点
D. 精神胜利法使阿Q最终走向革命，获得解放', [{"label": "A", "text": "阿Q在失败时，通过想象自己胜利来获得心理安慰"}, {"label": "B", "text": "精神胜利法是阿Q性格的核心，体现其自欺欺人"}, {"label": "C", "text": "精神胜利法是当时中国国民性的普遍弱点"}, {"label": "D", "text": "精神胜利法使阿Q最终走向革命，获得解放"}], 'D', '精神胜利法并未使阿Q获得解放，反而导致其悲剧结局。', 'single_choice', ARRAY['现代文深度阅读','小说鉴赏'], 'ai_generated', 'chinese_16-18_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'advanced', '高三', '下列对《故都的秋》中“北国的秋，却特别地来得清，来得静，来得悲凉”一句的理解，正确的有（  ）
