INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('chinese', '16-18', 'beginner', '高三', '请简要分析《边城》中翠翠的人物形象。', NULL, '①翠翠天真善良、温柔清纯，是湘西淳朴人性的化身；②她对爱情忠贞执着，默默等待傩送的归来；③她的命运带有悲剧色彩，体现了人性美与现实之间的矛盾。', '从性格、爱情观、悲剧意义三方面作答。', 'short_answer', ARRAY['现代文深度阅读','小说'], 'ai_generated', 'chinese_16-18_supplement');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
