VALUES ('english', '13-15', 'advanced', '', 'The old house, ______ (abandon) for years, finally collapsed in the storm.', [{"label": "A", "text": "A. abandoned"}, {"label": "B", "text": "B. abandoning"}, {"label": "C", "text": "C. to abandon"}, {"label": "D", "text": "D. having abandoned"}], 'A', 'The past participle ''abandoned'' indicates a passive and completed action.', 'single_choice', ARRAY['完形填空'], 'ai_generated', 'english_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('english', '13-15', 'advanced', '', '(Passage about exercise benefits) Q: What is an additional benefit of exercise besides physical health?', [{"label": "A", "text": "A. Weight loss only"}, {"label": "B", "text": "B. Better sleep"}, {"label": "C", "text": "C. Improved memory and concentration"}, {"label": "D", "text": "D. Lower cost"}], 'C', 'The passage states exercise boosts memory and concentration.', 'single_choice', ARRAY['阅读理解'], 'ai_generated', 'english_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('english', '13-15', 'advanced', '', 'Which sentences contain non-restrictive relative clauses? (Select all that apply)', [{"label": "A", "text": "A. Tom, who is my friend, is kind."}, {"label": "B", "text": "B. The book which is red is mine."}, {"label": "C", "text": "C. The man, whom I met, is kind."}, {"label": "D", "text": "D. All books that I have are good."}], '[''A'', ''C'']', 'Non-restrictive clauses are set off by commas and provide extra information.', 'multiple_choice', ARRAY['定语从句'], 'ai_generated', 'english_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('english', '13-15', 'advanced', '', 'Which of the following are correct subject clauses? (Select all that apply)', [{"label": "A", "text": "A. What he said is true."}, {"label": "B", "text": "B. That he will come is certain."}, {"label": "C", "text": "C. Whether he comes doesn't matter."}, {"label": "D", "text": "D. If he comes is not known."}], '[''A'', ''B'', ''C'']', 'Subject clauses cannot be introduced by ''if''; use ''whether'' instead.', 'multiple_choice', ARRAY['宾语从句'], 'ai_generated', 'english_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('english', '13-15', 'advanced', '', 'Which sentences use inversion correctly? (Select all that apply)', [{"label": "A", "text": "A. Hardly had I left when it rained."}, {"label": "B", "text": "B. No sooner had he left than it rained."}, {"label": "C", "text": "C. Not only does he swim but also runs."}, {"label": "D", "text": "D. Although he is young, he works hard."}], '[''A'', ''B'', ''C'']', '''Although'' does not trigger inversion; the others are correct inverted structures.', 'multiple_choice', ARRAY['状语从句'], 'ai_generated', 'english_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('english', '13-15', 'advanced', '', 'Which structures use the perfect participle? (Select all that apply)', [{"label": "A", "text": "A. Having finished work, he went home."}, {"label": "B", "text": "B. The work finished, he went home."}, {"label": "C", "text": "C. Having been told the news, she cried."}, {"label": "D", "text": "D. Being tired, he stopped working."}], '[''A'', ''C'']', 'The perfect participle indicates an action completed before the main verb.', 'multiple_choice', ARRAY['非谓语动词'], 'ai_generated', 'english_13-15_001');
