INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('english', '16-18', 'beginner', '高三', 'Explain the difference between ''If I was'' and ''If I were'' in conditional sentences.', NULL, '''If I were'' is used in the subjunctive mood for unreal or hypothetical situations. ''If I was'' is sometimes used in informal speech for real conditions about the past, but ''were'' is grammatically preferred for hypotheticals.', 'The subjunctive mood requires ''were'' for all persons in formal English when expressing unreal conditions.', 'short_answer', ARRAY['虚拟语气'], 'ai_generated', '');
