VALUES ('english', '16-18', 'intermediate', '高三', 'Inference questions in reading comprehension require readers to draw conclusions based on textual evidence rather than direct statements.', NULL, 'True', 'Inference questions test the ability to read between the lines using evidence from the text.', 'true_false', ARRAY['阅读理解'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('english', '16-18', 'intermediate', '高三', 'Analyze the sentence structure: ''What surprises me is that he refused the offer.'' Identify the main clause and the subordinate clause.', NULL, 'Main clause: ''What surprises me is...'' (where ''What surprises me'' is a subject clause). Subordinate clause: ''that he refused the offer'' (a predicative clause acting as the complement of ''is'').', 'This sentence contains a subject clause (''What surprises me'') and a predicative clause (''that he refused the offer'').', 'short_answer', ARRAY['长难句分析'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('english', '16-18', 'intermediate', '高三', 'Describe two ways to create suspense in a narrative continuation.', NULL, 'Introducing an unexpected obstacle or conflict, and using pacing techniques like short sentences or cliffhangers at paragraph endings.', 'Suspense is built through uncertainty about outcomes and controlled pacing that delays resolution.', 'short_answer', ARRAY['读后续写/应用文写作'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('english', '16-18', 'advanced', '高三', 'But for your timely warning, we _____ into serious trouble.', [{"label": "A", "text": "would get"}, {"label": "B", "text": "would have got"}, {"label": "C", "text": "had got"}, {"label": "D", "text": "got"}], 'B', '''But for'' introduces an implied negative condition; for a past unreal situation, use ''would have + past participle''.', 'single_choice', ARRAY['虚拟语气'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('english', '16-18', 'advanced', '高三', 'The manager ordered that the work _____ finished before Friday.', [{"label": "A", "text": "is"}, {"label": "B", "text": "be"}, {"label": "C", "text": "was"}, {"label": "D", "text": "would be"}], 'B', 'After verbs like ''order,'' ''demand,'' and ''suggest,'' the subjunctive uses the base form ''be'' without ''should''.', 'single_choice', ARRAY['虚拟语气'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('english', '16-18', 'advanced', '高三', 'So fast _____ that it is difficult to imagine the pace at which it is moving.', [{"label": "A", "text": "does technology advance"}, {"label": "B", "text": "technology advances"}, {"label": "C", "text": "advanced technology"}, {"label": "D", "text": "has technology advanced"}], 'A', 'When ''so + adjective/adverb'' begins a sentence, partial inversion with the auxiliary verb is required.', 'single_choice', ARRAY['长难句分析'], 'ai_generated', '');
