INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('english', '16-18', 'advanced', '高三', 'Which literary device is most prominent? (Passage: The city breathed at night. Neon lights pulsed like veins. Buildings stood as silent giants, watching the streets below.)', [{"label": "A", "text": "Literal description"}, {"label": "B", "text": "Personification and metaphor"}, {"label": "C", "text": "Chronological narration"}, {"label": "D", "text": "Statistical analysis"}], 'B', 'The city ''breathed,'' lights ''pulsed like veins,'' and buildings ''stood as silent giants''—all personification and metaphor.', 'single_choice', ARRAY['阅读理解'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
