VALUES ('physics', '13-15', 'intermediate', '初三', 'A hollow metal ball weighs 8 N in air and 5 N in water. Its volume is 0.0004 m³. What is the average density of the ball?', [{"label": "A", "text": "2000 kg/m³"}, {"label": "B", "text": "1000 kg/m³"}, {"label": "C", "text": "1500 kg/m³"}, {"label": "D", "text": "2500 kg/m³"}], 'A', 'Mass = 8/10 = 0.8 kg; density = 0.8/0.0004 = 2000 kg/m³.', 'multiple_choice', ARRAY['浮力'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
