INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高二', 'In a single-slit diffraction pattern, the angular width of the central maximum is _____.', [{"label": "A", "text": "a/λ"}, {"label": "B", "text": "λ/a"}, {"label": "C", "text": "2λ/a"}, {"label": "D", "text": "aλ"}], 'C', 'The first minima occur at sin θ = ±λ/a, so the angular width of the central maximum is 2λ/a.', 'fill_blank', ARRAY['波动光学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高一', 'A fixed amount of ideal gas undergoes an isochoric process. If the pressure doubles, the temperature _____.', [{"label": "A", "text": "doubles"}, {"label": "B", "text": "remains constant"}, {"label": "C", "text": "quadruples"}, {"label": "D", "text": "halves"}], 'A', 'At constant volume, p ∝ T (Charles''s Law). Doubling pressure doubles absolute temperature.', 'fill_blank', ARRAY['热学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高一', 'On a rough horizontal surface, a force F pulls a block at angle θ above horizontal. The normal force is _____ compared to the block''s weight.', [{"label": "A", "text": "equal to"}, {"label": "B", "text": "independent of"}, {"label": "C", "text": "greater than"}, {"label": "D", "text": "less than"}], 'D', 'The vertical component F sin θ lifts the block slightly, reducing the normal force: N = mg - F sin θ.', 'true_false', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
