INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高一', 'A coil with 100 turns experiences a change in magnetic flux of 0.05 Wb in 0.1 s. The magnitude of induced EMF is _____.', [{"label": "A", "text": "0.5 V"}, {"label": "B", "text": "50 V"}, {"label": "C", "text": "5 V"}, {"label": "D", "text": "500 V"}], 'B', 'ε = N|ΔΦ/Δt| = 100 × 0.05/0.1 = 50 V.', 'true_false', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高二', 'When unpolarized light passes through a polarizer, the intensity of transmitted light becomes _____ of the original intensity.', [{"label": "A", "text": "unchanged"}, {"label": "B", "text": "half"}, {"label": "C", "text": "zero"}, {"label": "D", "text": "one quarter"}], 'B', 'A polarizer transmits the component parallel to its axis; for unpolarized light, transmitted intensity is I₀/2.', 'true_false', ARRAY['波动光学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高一', 'Which statements correctly describe the relationship between force and motion?', [{"label": "A", "text": "An object can move without any net force acting on it"}, {"label": "B", "text": "Acceleration direction matches net force direction"}, {"label": "C", "text": "Greater force always means greater speed"}, {"label": "D", "text": "Force causes acceleration, not velocity"}], '[''D'', ''A'', ''B'']', 'Force causes acceleration (A). Inertia allows motion without force (B). Acceleration aligns with net force (D). Greater force does not guarantee greater speed (C).', 'short_answer', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高二', 'In which scenarios is momentum conserved for the described system?', [{"label": "A", "text": "A rocket expelling exhaust gases in space"}, {"label": "B", "text": "A bullet fired from a rifle (bullet + rifle system)"}, {"label": "C", "text": "A ball bouncing elastically off a wall"}, {"label": "D", "text": "Two colliding objects on a frictionless surface"}], '[''B'', ''D'', ''A'']', 'Momentum is conserved in isolated systems (A, C, D). In B, the wall is connected to Earth, so external forces act.', 'single_choice', ARRAY['动量守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高一', 'Which factors increase the self-inductance of a solenoid?', [{"label": "A", "text": "Inserting an iron core"}, {"label": "B", "text": "Increasing the number of turns per unit length"}, {"label": "C", "text": "Decreasing the cross-sectional area"}, {"label": "D", "text": "Increasing the length of the solenoid"}], '[''B'', ''A'']', 'L = μn²V. Increasing turns per unit length (A) and inserting iron (B, increasing μ) raise inductance. Decreasing area or increasing length reduces L.', 'single_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高一', 'During an isothermal expansion of an ideal gas, which quantities remain constant?', [{"label": "A", "text": "Pressure"}, {"label": "B", "text": "The product pV"}, {"label": "C", "text": "Internal energy"}, {"label": "D", "text": "Temperature"}], '[''C'', ''D'', ''B'']', 'For an ideal gas, internal energy depends only on temperature, so both are constant in an isothermal process. Boyle''s Law gives pV = constant.', 'single_choice', ARRAY['热学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高二', 'A car rounds a banked curve at angle θ with radius r at speed v. For no friction needed, v² = _____ (in terms of r, g, and θ).', NULL, 'gr tan θ', 'Balancing forces: N sin θ = mv²/r and N cos θ = mg. Dividing gives tan θ = v²/(gr), so v² = gr tan θ.', 'single_choice', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'The work-energy theorem states that the net work done on an object equals its change in _____.', NULL, 'kinetic energy', 'W_net = ΔEk = ½mv₂² - ½mv₁².', 'single_choice', ARRAY['动能定理/机械能守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'In a two-body collision, the total momentum before collision equals the total momentum after collision, provided no external _____ act on the system.', NULL, 'forces', 'Momentum conservation holds when the net external force on the system is zero.', 'single_choice', ARRAY['动量守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高一', 'The direction of induced current determined by Lenz''s Law is consistent with the principle of conservation of _____.', NULL, 'energy', 'Lenz''s Law ensures that induced current opposes the change, preventing perpetual motion and conserving energy.', 'single_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高二', 'In thin-film interference, constructive interference occurs when the optical path difference equals an integer multiple of the _____.', NULL, 'wavelength (in the film)', 'Constructive interference in thin films requires the optical path difference to equal mλ_film, considering phase changes.', 'single_choice', ARRAY['波动光学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'If non-conservative forces do positive work on a system, the total mechanical energy of the system increases.', NULL, 'True', 'Positive work by non-conservative forces (like an applied force) adds energy to the system, increasing mechanical energy.', 'single_choice', ARRAY['动能定理/机械能守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'In an elastic collision between two objects, both momentum and kinetic energy are conserved.', NULL, 'True', 'Elastic collisions conserve both total momentum and total kinetic energy.', 'single_choice', ARRAY['动量守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'The internal energy of an ideal gas depends only on its temperature and the number of moles.', NULL, 'True', 'For an ideal gas, U = (f/2)nRT, depending only on temperature and amount of substance.', 'single_choice', ARRAY['热学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'Explain why a changing magnetic flux through a coil induces an electromotive force according to Faraday''s Law.', NULL, 'A changing magnetic flux produces a vortex electric field (non-electrostatic field) that does work on charges in the coil, driving induced current. The magnitude of EMF equals the rate of change of magnetic flux through the coil.', 'Faraday''s Law quantifies how changing magnetic fields create electric fields that drive current.', 'single_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高一', 'Describe the difference between interference and diffraction patterns in terms of their origins and appearance.', NULL, 'Interference arises from superposition of waves from coherent sources (like double slits), producing equally spaced fringes. Diffraction results from waves bending around obstacles or through apertures, with an intensity-modulated pattern featuring a broad central maximum.', 'Interference involves multiple coherent sources; diffraction involves wave bending at edges.', 'single_choice', ARRAY['波动光学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'A block of mass m on a horizontal surface is connected to a spring (constant k). The coefficient of kinetic friction is μ. The block is displaced by A from equilibrium and released. The total distance traveled before coming to rest is _____.', [{"label": "A", "text": "A/(2μmg/k)"}, {"label": "B", "text": "kA²/(2μmg)"}, {"label": "C", "text": "μmgA/k"}, {"label": "D", "text": "A"}], 'B', 'Initial elastic energy ½kA² is dissipated by friction: μmg × d = ½kA² → d = kA²/(2μmg).', 'single_choice', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高二', 'A particle moves under a conservative force where potential energy U(r) = -a/r + b/r². The equilibrium position occurs at r = _____.', [{"label": "A", "text": "b/a"}, {"label": "B", "text": "2b/a"}, {"label": "C", "text": "a/(2b)"}, {"label": "D", "text": "a/b"}], 'B', 'Equilibrium requires F = -dU/dr = 0. Solving -a/r² + 2b/r³ = 0 gives r = 2b/a.', 'single_choice', ARRAY['动能定理/机械能守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高一', 'A rocket of initial mass M₀ ejects exhaust at speed u relative to the rocket. Its mass decreases at rate α. The thrust force is _____.', [{"label": "A", "text": "u/α"}, {"label": "B", "text": "M₀u"}, {"label": "C", "text": "αu"}, {"label": "D", "text": "αM₀"}], 'C', 'Thrust F = u|dm/dt| = αu, from the rocket equation.', 'multiple_choice', ARRAY['动量守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高一', 'A square loop of side L and resistance R moves with velocity v into a region of uniform magnetic field B (perpendicular to the loop). The magnitude of the magnetic force opposing the motion is _____.', [{"label": "A", "text": "BLv/R"}, {"label": "B", "text": "B²L²v/R"}, {"label": "C", "text": "BL²v/R"}, {"label": "D", "text": "B²Lv/R"}], 'B', 'EMF = BLv, I = BLv/R, F = BIL = B²L²v/R.', 'multiple_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'In a diffraction grating with spacing d, light of wavelength λ is incident normally. The maximum possible order of diffraction is approximately _____.', [{"label": "A", "text": "d/λ"}, {"label": "B", "text": "dλ"}, {"label": "C", "text": "2d/λ"}, {"label": "D", "text": "λ/d"}], 'A', 'From d sin θ = mλ, with sin θ ≤ 1, the maximum order m_max ≤ d/λ.', 'multiple_choice', ARRAY['波动光学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高二', 'An ideal gas undergoes a cyclic process on a p-V diagram. If the cycle is traversed clockwise, the net work done by the gas is _____.', [{"label": "A", "text": "negative"}, {"label": "B", "text": "equal to the heat rejected"}, {"label": "C", "text": "positive"}, {"label": "D", "text": "zero"}], 'C', 'A clockwise cycle on a p-V diagram encloses positive area, representing net work done by the gas.', 'multiple_choice', ARRAY['热学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高一', 'Two blocks of masses m₁ and m₂ are stacked on a frictionless surface. A force F is applied to m₁. The coefficient of static friction between the blocks is μ. The maximum F before slipping occurs is _____.', [{"label": "A", "text": "μ(m₁+m₂)g"}, {"label": "B", "text": "μm₂g"}, {"label": "C", "text": "μm₁g(m₁+m₂)/m₂"}, {"label": "D", "text": "μ(m₁+m₂)g(m₁/m₂)"}], 'C', 'Maximum acceleration before slip: a = μm₁g/m₂ for m₂. For the system: F = (m₁+m₂)a = μm₁g(m₁+m₂)/m₂.', 'multiple_choice', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高二', 'A conducting rod rotates with angular velocity ω about one end in a uniform magnetic field B perpendicular to the plane of rotation. The rod has length L. The EMF between the ends is _____.', [{"label": "A", "text": "BωL²"}, {"label": "B", "text": "½BωL²"}, {"label": "C", "text": "BωL"}, {"label": "D", "text": "½BωL"}], 'B', 'Integrating v = ωr: ε = ∫₀ᴸ Bωr dr = ½BωL².', 'multiple_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'In a Michelson interferometer, when the movable mirror is displaced by distance d, the number of fringes N that cross the field of view is related by _____.', [{"label": "A", "text": "d = 2Nλ"}, {"label": "B", "text": "d = Nλ"}, {"label": "C", "text": "d = Nλ/4"}, {"label": "D", "text": "d = Nλ/2"}], 'D', 'Each fringe shift corresponds to λ/2 mirror displacement because the light path changes by 2d.', 'fill_blank', ARRAY['波动光学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高一', 'For an adiabatic process of an ideal monatomic gas, the relation between pressure and volume is pV^γ = constant, where γ equals _____.', [{"label": "A", "text": "5/3"}, {"label": "B", "text": "7/5"}, {"label": "C", "text": "3/2"}, {"label": "D", "text": "4/3"}], 'A', 'For a monatomic ideal gas, γ = Cp/Cv = (5/2)R / (3/2)R = 5/3.', 'fill_blank', ARRAY['热学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高二', 'Which statements about inertial and non-inertial reference frames are correct?', [{"label": "A", "text": "Fictitious forces appear in non-inertial frames"}, {"label": "B", "text": "The Earth is a perfect inertial frame"}, {"label": "C", "text": "Centrifugal force is a fictitious force"}, {"label": "D", "text": "Newton's laws hold in inertial frames"}], '[''D'', ''A'', ''C'']', 'A, B, and D are correct. Earth is approximately inertial but not perfect due to rotation (C is false).', 'fill_blank', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高一', 'For a conservative force field, which statements are true?', [{"label": "A", "text": "Work done around any closed path is zero"}, {"label": "B", "text": "The work done depends only on endpoints, not path"}, {"label": "C", "text": "Force is the negative gradient of potential energy"}, {"label": "D", "text": "Mechanical energy is conserved"}], '[''B'', ''C'', ''D'', ''A'']', 'All four are defining properties of conservative forces.', 'fill_blank', ARRAY['动能定理/机械能守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高一', 'Which phenomena are explained by Faraday''s Law of Induction?', [{"label": "A", "text": "Magnetic force on a moving charge"}, {"label": "B", "text": "Eddy currents in a conductor near changing fields"}, {"label": "C", "text": "The operation of a transformer"}, {"label": "D", "text": "Current induced in a coil by a moving magnet"}], '[''D'', ''B'', ''C'']', 'A, B, and C involve changing magnetic flux inducing EMF. D is the Lorentz force, not induction.', 'fill_blank', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高三', 'Which factors affect the resolving power of a diffraction-limited optical instrument?', [{"label": "A", "text": "The refractive index of the medium"}, {"label": "B", "text": "Aperture diameter"}, {"label": "C", "text": "Wavelength of light"}, {"label": "D", "text": "Focal length"}], '[''C'', ''B'', ''A'']', 'Resolving power ∝ D/λ. Refractive index affects wavelength in medium (λ/n). Focal length affects image size but not angular resolution.', 'fill_blank', ARRAY['波动光学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高二', 'For a satellite in circular orbit around Earth at radius r, the orbital speed v = _____ (in terms of G, M, and r).', NULL, 'sqrt(GM/r)', 'Equating gravitational force to centripetal force: GMm/r² = mv²/r → v = √(GM/r).', 'fill_blank', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高二', 'In a two-dimensional elastic collision, _____ components of total momentum are conserved independently.', NULL, 'all / both x and y', 'Momentum is a vector; each component is conserved separately when there are no external forces in that direction.', 'true_false', ARRAY['动量守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高一', 'The energy stored in an inductor carrying current I is U = _____.', NULL, '½LI²', 'Magnetic energy in an inductor: U = ½LI², analogous to elastic potential energy in a spring.', 'true_false', ARRAY['电磁感应'], 'ai_generated', '');
