INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高一', 'In an Atwood machine with masses m₁ and m₂ (m₁ > m₂) connected over a massless pulley, the tension in the string is the same on both sides of an ideal pulley.', NULL, 'True', 'For a massless, frictionless pulley, tension is uniform throughout the string.', 'short_answer', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
