INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'Explain the physical origin of eddy currents and describe one method to reduce their undesirable effects in transformer cores.', NULL, 'Eddy currents are loops of induced current flowing in conductors exposed to changing magnetic fields, caused by Faraday''s Law. They dissipate energy as heat. To reduce them, transformer cores are laminated with thin insulated sheets oriented parallel to the magnetic field, increasing resistance to current flow perpendicular to the flux.', 'Eddy currents arise from changing flux in conductors. Lamination breaks current paths and reduces losses.', 'single_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
