INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高一', '生态系统中能量流动的特点是？', [{"label": "A", "text": "单向流动、逐级递减"}, {"label": "B", "text": "双向流动、保持不变"}, {"label": "C", "text": "循环流动、逐级递增"}, {"label": "D", "text": "单向流动、逐级递增"}], 'A', '生态系统中能量单向流动（不可循环），逐级递减（每个营养级约有10%-20%能量传递到下一级）。', 'single_choice', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高一', 'PCR技术中，引物的作用是？', [{"label": "A", "text": "打开DNA双链"}, {"label": "B", "text": "与模板DNA结合，启动子链延伸"}, {"label": "C", "text": "连接DNA片段"}, {"label": "D", "text": "提供能量"}], 'B', '引物是与模板DNA特定序列互补的短链DNA或RNA，为DNA聚合酶提供3''-OH末端，启动子链的延伸。', 'single_choice', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高三', '有氧呼吸过程中，产生ATP最多的阶段是？', [{"label": "A", "text": "第一阶段"}, {"label": "B", "text": "第三阶段"}, {"label": "C", "text": "各阶段相同"}, {"label": "D", "text": "第二阶段"}], 'B', '有氧呼吸第三阶段在线粒体内膜上进行，[H]与O₂结合生成水，释放大量能量，产生大量ATP（约34个）。', 'single_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高三', '碳在生物群落与无机环境之间循环的主要形式是？', [{"label": "A", "text": "有机物"}, {"label": "B", "text": "CO₂"}, {"label": "C", "text": "单质碳"}, {"label": "D", "text": "碳酸盐"}], 'B', '碳在生物群落与无机环境之间主要以CO₂形式循环；在生物群落内部以有机物形式传递。', 'single_choice', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高二', '基因工程中，将目的基因导入植物细胞常用的方法是？', [{"label": "A", "text": "农杆菌转化法"}, {"label": "B", "text": "Ca²⁺处理法"}, {"label": "C", "text": "显微注射法"}, {"label": "D", "text": "病毒侵染法"}], 'A', '农杆菌转化法是将目的基因导入植物细胞最常用的方法；显微注射法用于动物细胞；Ca²⁺处理法用于微生物细胞。', 'single_choice', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高二', '下列关于光合作用和呼吸作用的叙述，正确的有？', [{"label": "A", "text": "光合作用产生的O₂来自H₂O"}, {"label": "B", "text": "光合作用只在叶绿体中进行"}, {"label": "C", "text": "有氧呼吸的三个阶段都产生ATP"}, {"label": "D", "text": "无氧呼吸只在细胞质基质中进行"}], '[''C'', ''A'', ''D'']', '真核细胞光合作用在叶绿体中进行，但原核细胞（如蓝藻）无叶绿体也可光合作用；有氧呼吸三个阶段均产生ATP；光合作用O₂来自水的光解；无氧呼吸全程在细胞质基质中进行。', 'single_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高一', '下列关于孟德尔分离定律的叙述，正确的有？', [{"label": "A", "text": "F₂性状分离比为3:1"}, {"label": "B", "text": "发生在减数第一次分裂后期"}, {"label": "C", "text": "等位基因随同源染色体分开而分离"}, {"label": "D", "text": "适用于伴性遗传"}], '[''C'', ''B'', ''A'', ''D'']', '分离定律的实质是等位基因随同源染色体分开而分离，发生在减Ⅰ后期；F₂表现型比3:1；伴性遗传的基因也遵循分离定律。', 'single_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高二', '下列属于生态系统信息传递的有？', [{"label": "A", "text": "孔雀开屏"}, {"label": "B", "text": "植物分泌化学物质抑制邻近植物生长"}, {"label": "C", "text": "光照时间影响植物开花"}, {"label": "D", "text": "蜜蜂跳舞"}], '[''A'', ''D'', ''B'', ''C'']', '孔雀开屏为行为信息；蜜蜂跳舞为行为信息；植物分泌化学物质为化学信息；光照时间为物理信息。', 'single_choice', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于DNA复制的叙述，正确的有？', [{"label": "A", "text": "需要DNA聚合酶"}, {"label": "B", "text": "半保留复制"}, {"label": "C", "text": "需要模板"}, {"label": "D", "text": "需要引物"}], '[''C'', ''D'', ''B'', ''A'']', 'DNA复制以DNA两条链为模板，需要引物提供3''-OH，方式为半保留复制，需要DNA聚合酶等多种酶参与。', 'single_choice', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高一', '将一株植物置于密闭玻璃罩内，给予适宜光照，CO₂浓度变化如图所示（先降低后稳定）。CO₂浓度稳定时，植物叶肉细胞中光合作用速率______呼吸作用速率。', [{"label": "A", "text": "小于"}, {"label": "B", "text": "等于"}, {"label": "C", "text": "大于"}, {"label": "D", "text": "无法判断"}], 'C', '整株植物CO₂浓度稳定时光合速率=呼吸速率，但植物非绿色细胞只进行呼吸作用，故叶肉细胞的光合速率必须大于其自身呼吸速率，才能补偿非光合细胞的呼吸消耗。', 'fill_blank', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高二', '某植物红花(A)对白花(a)为显性，高茎(B)对矮茎(b)为显性。基因型为AaBb的植株自交，后代表现型比例为9:3:3:1的条件不包括？', [{"label": "A", "text": "存在基因互作"}, {"label": "B", "text": "两对等位基因独立遗传"}, {"label": "C", "text": "后代数量足够多"}, {"label": "D", "text": "各种配子成活率相同"}], 'A', '9:3:3:1的出现需要两对等位基因独立遗传、配子和合子成活率相同、后代数量足够多等条件；若存在基因互作，表现型比例会发生改变（如9:7、9:6:1等）。', 'fill_blank', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高二', '下列关于生态系统能量流动的计算，正确的是？', [{"label": "A", "text": "初级消费者粪便中的能量属于初级消费者同化量"}, {"label": "B", "text": "分解者获得的能量不属于该生态系统的能量"}, {"label": "C", "text": "第二营养级到第三营养级的能量传递效率为10%-20%"}, {"label": "D", "text": "生产者固定的太阳能即为流入生态系统的总能量"}], 'C', '初级消费者粪便中的能量属于生产者同化量未被利用的部分；能量传递效率约为10%-20%；生产者固定的太阳能是流入自然生态系统的总能量；分解者获得的能量属于该生态系统的能量。', 'fill_blank', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高一', '基因工程中，限制性核酸内切酶的作用是？', [{"label": "A", "text": "连接DNA片段"}, {"label": "B", "text": "合成DNA子链"}, {"label": "C", "text": "切割特定的磷酸二酯键"}, {"label": "D", "text": "解开DNA双链"}], 'C', '限制酶识别特定核苷酸序列并在特定位置切割DNA分子中的磷酸二酯键；DNA连接酶连接DNA片段，解旋酶解开双链，DNA聚合酶合成子链。', 'fill_blank', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高一', '人类红绿色盲为伴X染色体隐性遗传病。一个色盲女性与一个正常男性婚配，所生子女的患病情况是？', [{"label": "A", "text": "儿子全部色盲，女儿全部携带"}, {"label": "B", "text": "子女各有一半色盲"}, {"label": "C", "text": "儿子全部色盲，女儿全部正常"}, {"label": "D", "text": "儿子全部正常，女儿全部色盲"}], 'A', '色盲女性(XᵇXᵇ)×正常男性(XᴮY)，儿子必为XᵇY（色盲），女儿必为XᴮXᵇ（携带者，表现正常）。', 'fill_blank', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高三', '关于叶绿体色素的提取和分离实验，下列叙述正确的是？', [{"label": "A", "text": "叶绿素b呈黄绿色"}, {"label": "B", "text": "滤液细线应浸入层析液中"}, {"label": "C", "text": "用无水乙醇分离色素"}, {"label": "D", "text": "胡萝卜素在滤纸条上扩散最快"}], 'D', '无水乙醇用于提取色素，层析液用于分离色素；滤液细线不能浸入层析液；胡萝卜素在层析液中溶解度最大，扩散最快；叶绿素b呈黄绿色，叶绿素a呈蓝绿色。', 'fill_blank', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高一', '在碳循环中，大气中CO₂进入生物群落的主要途径是？', [{"label": "A", "text": "分解作用"}, {"label": "B", "text": "呼吸作用"}, {"label": "C", "text": "燃烧作用"}, {"label": "D", "text": "光合作用和化能合成作用"}], 'D', '生产者通过光合作用将大气CO₂固定为有机物，化能合成细菌通过化能合成作用也能固定CO₂，这是CO₂进入生物群落的主要途径。', 'true_false', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高二', '下列关于基因表达载体的叙述，错误的是？', [{"label": "A", "text": "含有启动子和终止子"}, {"label": "B", "text": "必须含有标记基因"}, {"label": "C", "text": "只能用质粒作为载体"}, {"label": "D", "text": "含有目的基因"}], 'C', '基因表达载体可用质粒、噬菌体衍生物、动植物病毒等；必须含有目的基因、启动子、终止子和标记基因等组件。', 'true_false', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高二', '基因型为AaBb的个体（独立遗传）测交，后代表现型比例为？', [{"label": "A", "text": "9:3:3:1"}, {"label": "B", "text": "3:1"}, {"label": "C", "text": "1:2:1"}, {"label": "D", "text": "1:1:1:1"}], 'D', 'AaBb产生四种比例相等的配子AB:Ab:aB:ab=1:1:1:1，与aabb测交，后代AaBb:Aabb:aaBb:aabb=1:1:1:1，表现型比1:1:1:1。', 'true_false', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高三', '酵母菌在有氧和无氧条件下都能进行细胞呼吸。若在有氧和无氧条件下消耗等量的葡萄糖，则产生的CO₂之比为？', [{"label": "A", "text": "1:3"}, {"label": "B", "text": "3:1"}, {"label": "C", "text": "1:1"}, {"label": "D", "text": "2:1"}], 'B', '有氧呼吸：C₆H₁₂O₆→6CO₂；无氧呼吸（酒精发酵）：C₆H₁₂O₆→2CO₂。消耗等量葡萄糖，CO₂之比为6:2=3:1。', 'true_false', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高三', '下列关于减数分裂和遗传定律关系的叙述，正确的有？', [{"label": "A", "text": "分离定律的实质是等位基因随同源染色体分开而分离"}, {"label": "B", "text": "自由组合定律的实质是非同源染色体上的非等位基因自由组合"}, {"label": "C", "text": "连锁互换定律说明基因在染色体上呈线性排列"}, {"label": "D", "text": "减数分裂过程中可发生基因重组"}], '[''A'', ''B'', ''D'', ''C'']', '分离定律实质是等位基因随同源染色体分开而分离；自由组合定律实质是非同源染色体上非等位基因自由组合；减数分裂过程中可通过交叉互换和自由组合发生基因重组；连锁互换定律证明基因在染色体上呈线性排列。', 'short_answer', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高三', '影响光合作用速率的环境因素有？', [{"label": "A", "text": "水含量"}, {"label": "B", "text": "CO₂浓度"}, {"label": "C", "text": "温度"}, {"label": "D", "text": "光照强度"}], '[''D'', ''B'', ''C'', ''A'']', '光照强度影响光反应；CO₂浓度影响暗反应；温度影响酶活性；水分既是光合作用的原料，缺水还会导致气孔关闭影响CO₂吸收。', 'single_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高二', '下列关于生态系统稳定性的叙述，正确的有？', [{"label": "A", "text": "生态系统稳定性是固定不变的"}, {"label": "B", "text": "负反馈调节是生态系统自我调节能力的基础"}, {"label": "C", "text": "热带雨林抵抗力稳定性强于北极苔原"}, {"label": "D", "text": "营养结构越复杂，抵抗力稳定性越强"}], '[''B'', ''D'', ''C'']', '负反馈调节是生态系统自我调节的基础；营养结构越复杂，抵抗力稳定性越强；热带雨林营养结构复杂，抵抗力稳定性强于北极苔原；生态系统稳定性会随环境变化而改变。', 'single_choice', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'beginner', '高一', '下列关于DNA连接酶的叙述，正确的有？', [{"label": "A", "text": "T₄ DNA连接酶可连接黏性末端和平末端"}, {"label": "B", "text": "催化磷酸二酯键形成"}, {"label": "C", "text": "可连接双链DNA片段"}, {"label": "D", "text": "E·coli DNA连接酶连接黏性末端"}], '[''C'', ''B'', ''D'', ''A'']', 'DNA连接酶连接双链DNA片段的磷酸二酯键；E·coli DNA连接酶只能连接黏性末端；T₄ DNA连接酶既能连接黏性末端也能连接平末端。', 'single_choice', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高一', '将某绿色植物置于密闭容器中，先黑暗处理1h，测得CO₂增加量为a；再给予适宜光照1h，测得CO₂减少量为b（b>a）。则该植物在光照1h内光合作用固定的CO₂量为？', [{"label": "A", "text": "a+b"}, {"label": "B", "text": "b"}, {"label": "C", "text": "2a+b"}, {"label": "D", "text": "b-a"}], 'A', '黑暗1h CO₂增加a为1h呼吸量；光照1h CO₂减少b为净光合量。总光合量=净光合量+呼吸量=b+a。', 'single_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高二', '某植物的花色由两对独立遗传的基因(A/a、B/b)控制，A_B_开红花，A_bb开粉花，aaB_和aabb开白花。基因型为AaBb的植株自交，后代中红花植株占？', [{"label": "A", "text": "3/16"}, {"label": "B", "text": "9/16"}, {"label": "C", "text": "7/16"}, {"label": "D", "text": "4/16"}], 'B', 'AaBb自交后代A_B_占9/16（红花），A_bb占3/16（粉花），aaB_占3/16（白花），aabb占1/16（白花）。', 'single_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '某生态系统中，生产者固定的太阳能为10000kJ，初级消费者同化量为1500kJ，次级消费者同化量为200kJ。则从初级消费者到次级消费者的能量传递效率为？', [{"label": "A", "text": "2%"}, {"label": "B", "text": "15%"}, {"label": "C", "text": "1.33%"}, {"label": "D", "text": "13.3%"}], 'D', '能量传递效率=次级消费者同化量/初级消费者同化量×100%=200/1500×100%≈13.3%。', 'single_choice', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高一', '利用PCR技术扩增目的基因时，若第一轮循环后得到2个DNA分子，经过n轮循环后，理论上得到的目的基因分子数为？', [{"label": "A", "text": "2ⁿ-2n"}, {"label": "B", "text": "2ⁿ⁻²n"}, {"label": "C", "text": "2ⁿ"}, {"label": "D", "text": "2ⁿ⁻¹"}], 'D', 'PCR每轮循环DNA分子数翻倍，但初始模板的两条链不含目的基因（含侧翼序列），从第二轮开始才产生含目的基因的DNA。经过n轮循环，目的基因分子数为2ⁿ⁻²×2=2ⁿ⁻¹（当n≥2时）。', 'multiple_choice', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '某动物的毛色由X染色体上的基因控制，B对b为显性。雌性杂合子与雄性显性个体交配，后代中毛色表现型及比例为？', [{"label": "A", "text": "雌性全显性，雄性全隐性"}, {"label": "B", "text": "雌性和雄性均为显性:隐性=1:1"}, {"label": "C", "text": "雌性显性:隐性=1:1，雄性全显性"}, {"label": "D", "text": "雌性全显性，雄性显性:隐性=1:1"}], 'D', 'XᴮXᵇ × XᴮY，后代雌性XᴮXᴮ和XᴮXᵇ全为显性；雄性XᴮY（显性）:XᵇY（隐性）=1:1。', 'multiple_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高二', '在适宜温度下，将一株植物从黑暗处移至弱光处，再移至强光处。叶肉细胞中C₃和C₅含量的变化是？', [{"label": "A", "text": "C₃和C₅均减少"}, {"label": "B", "text": "C₃和C₅均增加"}, {"label": "C", "text": "C₃减少，C₅增加"}, {"label": "D", "text": "C₃增加，C₅减少"}], 'C', '从弱光移至强光，光反应增强，产生的ATP和NADPH增多，C₃还原加快，C₃减少；同时CO₂固定继续消耗C₅，但C₃还原产生C₅的速率大于消耗，故C₅增加。', 'multiple_choice', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '在基因工程中，检测目的基因是否成功表达出蛋白质，常用的方法是？', [{"label": "A", "text": "PCR"}, {"label": "B", "text": "核酸分子杂交"}, {"label": "C", "text": "DNA分子杂交"}, {"label": "D", "text": "抗原-抗体杂交"}], 'D', '抗原-抗体杂交技术利用特异性抗体检测目的基因是否表达出相应蛋白质；DNA分子杂交检测目的基因是否导入，核酸分子杂交检测是否转录，PCR用于扩增DNA。', 'multiple_choice', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高二', '某种昆虫的长翅(A)对残翅(a)为显性，红眼(B)对白眼(b)为显性，两对基因位于一对同源染色体上。若A和B连锁、a和b连锁，基因型为AaBb的雌雄个体交配，后代中残翅白眼个体占？', [{"label": "A", "text": "1/16"}, {"label": "B", "text": "3/16"}, {"label": "C", "text": "1/4"}, {"label": "D", "text": "1/2"}], 'C', '完全连锁时，AaBb产生AB和ab两种配子，比例1:1。雌雄交配后代AABB:AaBb:aabb=1:2:1，残翅白眼(aabb)占1/4。', 'multiple_choice', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高一', '有氧呼吸和无氧呼吸过程中，都产生的产物是？', [{"label": "A", "text": "CO₂"}, {"label": "B", "text": "H₂O"}, {"label": "C", "text": "乳酸"}, {"label": "D", "text": "ATP"}], 'D', '有氧呼吸和无氧呼吸第一阶段完全相同，都产生丙酮酸、[H]和少量ATP；CO₂只在有氧呼吸和酒精发酵中产生，H₂O只在有氧呼吸中产生，乳酸只在乳酸发酵中产生。', 'fill_blank', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于伴性遗传和人类遗传病的叙述，正确的有？', [{"label": "A", "text": "多基因遗传病在群体中的发病率较高"}, {"label": "B", "text": "抗维生素D佝偻病为伴X显性遗传病"}, {"label": "C", "text": "伴X隐性遗传病在男性中的发病率高于女性"}, {"label": "D", "text": "红绿色盲男性的母亲至少是携带者"}], '[''B'', ''D'', ''C'', ''A'']', '抗维生素D佝偻病为伴X显性遗传；红绿色盲男性XᵇY的母亲至少携带Xᵇ；伴X隐性遗传男性只要Xᵇ即患病，女性需XᵇXᵇ才患病；多基因遗传病（如高血压、糖尿病）在群体中发病率较高。', 'fill_blank', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高一', '下列关于C₃植物和C₄植物的叙述，正确的有？', [{"label": "A", "text": "C₄植物的CO₂固定先在叶肉细胞中进行"}, {"label": "B", "text": "C₄植物光合效率通常高于C₃植物"}, {"label": "C", "text": "C₃植物的维管束鞘细胞无叶绿体"}, {"label": "D", "text": "C₄植物更能适应高温干旱环境"}], '[''B'', ''A'', ''C'', ''D'']', 'C₄植物通过PEP羧化酶固定CO₂，效率高于C₃植物；CO₂先在叶肉细胞中固定为C₄酸，再运输到维管束鞘细胞释放CO₂进行卡尔文循环；C₃植物维管束鞘细胞无叶绿体；C₄植物因CO₂浓缩机制，更能适应高温干旱环境。', 'fill_blank', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高三', '下列关于克隆技术的叙述，正确的有？', [{"label": "A", "text": "克隆羊多莉的细胞核来自乳腺细胞"}, {"label": "B", "text": "体细胞克隆属于无性繁殖"}, {"label": "C", "text": "克隆技术可应用于拯救濒危物种"}, {"label": "D", "text": "克隆动物的遗传性状主要由供核个体决定"}], '[''B'', ''A'', ''D'', ''C'']', '体细胞克隆不涉及两性生殖细胞结合，属于无性繁殖；多莉羊的核来自芬兰多塞特母羊的乳腺细胞；遗传性状主要由细胞核基因决定；克隆技术可用于繁殖濒危物种。', 'fill_blank', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高二', '下列关于生物多样性和生态系统功能的叙述，正确的有？', [{"label": "A", "text": "生态系统的抵抗力稳定性与生物多样性正相关"}, {"label": "B", "text": "建立自然保护区是保护生物多样性最有效的措施"}, {"label": "C", "text": "生物多样性的间接价值大于直接价值"}, {"label": "D", "text": "生物多样性包括基因多样性、物种多样性和生态系统多样性"}], '[''D'', ''C'', ''A'', ''B'']', '生物多样性分三个层次；间接价值（生态功能）通常大于直接价值；生物多样性越高，营养结构越复杂，抵抗力稳定性越强；就地保护（自然保护区）是最有效的保护措施。', 'fill_blank', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
