INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高一', '下列关于生态系统稳定性的叙述，正确的是？', [{"label": "A", "text": "负反馈调节是生态系统自我调节能力的基础"}, {"label": "B", "text": "生态系统成分越简单，抵抗力稳定性越高"}, {"label": "C", "text": "森林生态系统的恢复力稳定性高于农田"}, {"label": "D", "text": "抵抗力稳定性越高，恢复力稳定性也越高"}], 'A', '负反馈调节是生态系统自我调节能力的基础；抵抗力稳定性和恢复力稳定性通常呈负相关；成分越复杂，抵抗力稳定性越高；森林抵抗力稳定性高但恢复力稳定性低。', 'multiple_choice', ARRAY['生态系统稳态'], 'ai_generated', '');
