INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高一', 'PCR技术中，DNA聚合酶的作用是？', [{"label": "A", "text": "提供能量"}, {"label": "B", "text": "催化脱氧核苷酸连接到引物3'端"}, {"label": "C", "text": "与模板DNA结合"}, {"label": "D", "text": "解开DNA双链"}], 'B', 'DNA聚合酶以DNA为模板，催化脱氧核苷酸按碱基互补配对原则连接到引物的3''端，延伸子链。', 'multiple_choice', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高三', '下列关于细胞呼吸的叙述，正确的是？（多选）', [{"label": "A", "text": "有氧呼吸的产物是CO₂和H₂O"}, {"label": "B", "text": "无氧呼吸只在第一阶段释放少量能量"}, {"label": "C", "text": "有氧呼吸主要在线粒体中进行"}, {"label": "D", "text": "所有生物都能进行有氧呼吸"}, {"label": "E", "text": "有氧呼吸和无氧呼吸的第一阶段相同"}], 'EABC', '有氧呼吸和无氧呼吸第一阶段都在细胞质基质中将葡萄糖分解为丙酮酸；有氧呼吸产物是CO₂和H₂O；无氧呼吸只在第一阶段释放少量能量；有些生物如乳酸菌只能进行无氧呼吸。', 'fill_blank', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'intermediate', '高二', '下列关于光合作用和呼吸作用的叙述，正确的是？（多选）', [{"label": "A", "text": "呼吸作用产生的CO₂都来自线粒体"}, {"label": "B", "text": "光合作用产生的O₂来自水的光解"}, {"label": "C", "text": "有氧呼吸的三个阶段都产生ATP"}, {"label": "D", "text": "光合作用只在叶绿体中进行"}, {"label": "E", "text": "光合作用和呼吸作用都有[H]的产生"}], 'CEB', '光合作用在真核生物中主要在叶绿体进行，但原核生物如蓝藻无叶绿体也能进行；有氧呼吸三个阶段都产生ATP；光合作用光解水产生[H]和O₂，呼吸作用第一、二阶段也产生[H]；原核细胞呼吸产生CO₂不在线粒体。', 'fill_blank', ARRAY['细胞代谢'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高一', '下列关于基因型和表现型的叙述，正确的是？（多选）', [{"label": "A", "text": "表现型是基因型与环境共同作用的结果"}, {"label": "B", "text": "相同表现型基因型一定相同"}, {"label": "C", "text": "相同基因型在不同环境下表现型可能不同"}, {"label": "D", "text": "表现型可以反映部分基因型信息"}, {"label": "E", "text": "基因型相同表现型一定相同"}], 'ACD', '表现型=基因型+环境；相同基因型在不同环境下可能有不同表现型；相同表现型基因型不一定相同（如AA和Aa都表现显性）；表现型可以反映部分基因型信息。', 'fill_blank', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高二', '下列遗传病中，属于单基因遗传病的有？（多选）', [{"label": "A", "text": "血友病"}, {"label": "B", "text": "红绿色盲"}, {"label": "C", "text": "白化病"}, {"label": "D", "text": "21三体综合征"}, {"label": "E", "text": "抗维生素D佝偻病"}], 'CBAE', '白化病、红绿色盲、血友病、抗维生素D佝偻病都是单基因遗传病；21三体综合征是染色体异常遗传病。', 'fill_blank', ARRAY['遗传定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高二', '下列关于能量流动的叙述，正确的是？（多选）', [{"label": "A", "text": "分解者可利用各营养级的能量"}, {"label": "B", "text": "能量流动从生产者固定太阳能开始"}, {"label": "C", "text": "能量在流动过程中逐级递减"}, {"label": "D", "text": "每个营养级约有10%-20%能量流向下一营养级"}, {"label": "E", "text": "能量流动是单向的"}], 'BDECA', '能量从生产者固定开始；传递效率约10%-20%；单向流动、逐级递减；分解者分解各营养级的遗体残骸获取能量。', 'fill_blank', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高二', '下列关于生态系统的叙述，正确的是？（多选）', [{"label": "A", "text": "分解者在物质循环中起重要作用"}, {"label": "B", "text": "生态系统由生物群落和无机环境组成"}, {"label": "C", "text": "生产者都是自养生物"}, {"label": "D", "text": "生态系统中能量可以循环利用"}, {"label": "E", "text": "消费者都是异养生物"}], 'BCAE', '生态系统=生物群落+无机环境；生产者是自养生物；分解者将有机物分解为无机物，促进物质循环；消费者是异养生物；能量单向流动，不能循环利用。', 'fill_blank', ARRAY['生态系统稳态'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高一', '下列关于基因表达载体的叙述，正确的是？（多选）', [{"label": "A", "text": "启动子是RNA聚合酶识别和结合的位点"}, {"label": "B", "text": "标记基因用于筛选含目的基因的受体细胞"}, {"label": "C", "text": "终止子使转录正常停止"}, {"label": "D", "text": "目的基因是表达载体的核心部分"}, {"label": "E", "text": "复制原点是DNA复制的起点"}], 'DABCE', '基因表达载体包括目的基因、启动子、终止子、标记基因和复制原点等组件，各部分功能不同但都很重要。', 'fill_blank', ARRAY['基因工程'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('biology', '16-18', 'advanced', '高三', '基因工程中常用的工具酶有？（多选）', [{"label": "A", "text": "DNA连接酶"}, {"label": "B", "text": "限制性核酸内切酶"}, {"label": "C", "text": "解旋酶"}, {"label": "D", "text": "RNA聚合酶"}, {"label": "E", "text": "DNA聚合酶"}], 'BAE', '限制酶切割DNA；DNA连接酶连接DNA片段；DNA聚合酶用于PCR或DNA复制；RNA聚合酶和解旋酶不是基因工程的核心工具酶。', 'true_false', ARRAY['基因工程'], 'ai_generated', '');
