INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'advanced', '初一', '请列举两种青春期常见的心理矛盾，并说明如何正确化解。', NULL, '常见矛盾：独立与依赖的矛盾、开放与封闭的矛盾。化解方法：主动沟通，换位思考，寻求帮助，培养积极心态。', '青春期常见心理矛盾包括独立与依赖、开放与封闭等，化解需要沟通和积极心态。', 'true_false', ARRAY['青春期心理','心理矛盾','化解方法'], 'ai_generated', '');
