INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '下列行为中，属于犯罪的是（  ）', [{"label": "A", "text": "小王在公共场所随地吐痰"}, {"label": "B", "text": "小赵因纠纷将他人打成重伤"}, {"label": "C", "text": "小李偷窃价值100元的物品"}, {"label": "D", "text": "小张因琐事将同学打成轻微伤"}], 'B', '将他人打成重伤，具有严重社会危害性，触犯刑法，构成犯罪。轻微伤、偷窃数额不大、随地吐痰属于一般违法行为。', 'single_choice', ARRAY['违法与犯罪','犯罪的认定'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高三', '1840年，英国发动侵略中国的鸦片战争，其直接原因是什么？', [{"label": "A", "text": "英国要求通商口岸"}, {"label": "B", "text": "清政府禁止鸦片贸易"}, {"label": "C", "text": "英国想打开中国市场"}, {"label": "D", "text": "林则徐虎门销烟"}], 'D', '鸦片战争的直接原因是林则徐的虎门销烟，英国以此为借口发动战争。根本原因是英国企图打开中国市场。', 'single_choice', ARRAY['鸦片战争','中国近代史','虎门销烟'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高一', '太平天国运动的纲领性文件是？', [{"label": "A", "text": "《变法通议》"}, {"label": "B", "text": "《海国图志》"}, {"label": "C", "text": "《资政新篇》"}, {"label": "D", "text": "《天朝田亩制度》"}], 'D', '《天朝田亩制度》是太平天国前期颁布的纲领性文件，反映了农民阶级对土地的渴望。', 'single_choice', ARRAY['太平天国','天朝田亩制度','中国近代史'], 'ai_generated', '');
