INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高一', '史学研究中，一手史料和二手史料的区别在于？', [{"label": "A", "text": "一手史料是直接史料，二手史料是间接史料"}, {"label": "B", "text": "一手史料是文字，二手史料是图像"}, {"label": "C", "text": "一手史料是实物，二手史料是文献"}, {"label": "D", "text": "一手史料更可靠，二手史料不可靠"}], 'A', '一手史料是当时人留下的直接记录，二手史料是后人研究形成的间接材料。', 'single_choice', ARRAY['史料','史学方法','一手史料'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高二', '关于中国近代史上的不平等条约，下列哪些表述是正确的？', [{"label": "A", "text": "《天津条约》开放汉口、南京等十处通商口岸"}, {"label": "B", "text": "《马关条约》允许日本在通商口岸开设工厂"}, {"label": "C", "text": "《北京条约》割让香港岛给英国"}, {"label": "D", "text": "《南京条约》是中国近代史上第一个不平等条约"}, {"label": "E", "text": "《辛丑条约》规定中国赔偿白银4.5亿两"}], 'D,B,E', 'A正确，《南京条约》是1842年签订的第一个不平等条约；B正确，《马关条约》允许日本在华设厂；C正确，《辛丑条约》赔款4.5亿两；D错误，割让香港岛的是《南京条约》；E错误，《天津条约》开放汉口等十处，但南京已在《南京条约》中开放。', 'single_choice', ARRAY['中国近代史','不平等条约','识记'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高三', '工业革命时期，下列哪些发明或事件具有标志性意义？', [{"label": "A", "text": "珍妮纺纱机的发明"}, {"label": "B", "text": "瓦特改良蒸汽机"}, {"label": "C", "text": "内燃机的诞生"}, {"label": "D", "text": "铁路的兴建"}, {"label": "E", "text": "电灯的发明"}], 'A,B,D', 'A、B、C均为第一次工业革命的重要标志；D电灯是第二次工业革命的发明；E内燃机也是第二次工业革命的产物。', 'single_choice', ARRAY['世界近代史','工业革命','识记'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高二', '以下关于史学理论的说法，正确的是？', [{"label": "A", "text": "历史事实是客观存在的，不受研究者主观影响"}, {"label": "B", "text": "口述史料因其主观性，不具有任何历史价值"}, {"label": "C", "text": "历史研究必须完全摒弃现实关怀，保持绝对中立"}, {"label": "D", "text": "历史解释需要基于史料，但不同史料可能有不同视角"}], 'D', 'A错误，历史事实虽客观，但研究者的选取和解释会受其影响；B正确，史料多样性要求多角度分析；C错误，现实关怀可提供问题意识，但需避免偏见；D错误，口述史料经考证仍有价值。', 'single_choice', ARRAY['史学理论','史料与解释'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高一', '关于冷战，下列哪些说法是正确的？', [{"label": "A", "text": "北约和华约的成立标志着两极格局正式形成"}, {"label": "B", "text": "柏林墙的修建是冷战在欧洲的象征之一"}, {"label": "C", "text": "冷战开始的标志是杜鲁门主义的出台"}, {"label": "D", "text": "马歇尔计划旨在援助西欧，遏制苏联"}, {"label": "E", "text": "古巴导弹危机是冷战期间美苏直接军事冲突"}], 'C,D,A,B', 'A正确，杜鲁门主义是冷战开始的标志；B正确，马歇尔计划的经济援助旨在遏制苏联；C正确，北约（1949）和华约（1955）的成立标志着两极格局形成；D错误，古巴导弹危机是危机，并未直接军事冲突；E正确，柏林墙是冷战的象征。', 'single_choice', ARRAY['世界现代史','冷战','识记'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'intermediate', '高一', '中国近代史上第一个不平等条约是《______》，它标志着中国开始沦为半殖民地半封建社会。', NULL, '南京条约', '1842年鸦片战争后，清政府被迫与英国签订《南京条约》，这是中国近代史上第一个不平等条约，破坏了中国的领土完整和主权，标志着中国开始沦为半殖民地半封建社会。', 'single_choice', ARRAY['中国近代史','鸦片战争','不平等条约'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'intermediate', '高三', '第一次工业革命首先发生在______国，其标志性发明是______。', NULL, '英|蒸汽机', '第一次工业革命于18世纪60年代首先从英国开始，瓦特改良的蒸汽机是标志性发明，推动了机械化和工厂制度的建立。', 'single_choice', ARRAY['世界近代史','工业革命','蒸汽机'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'intermediate', '高三', '史学研究中，史料可分为第一手史料和第二手史料。其中，直接反映历史事件的原始记录属于______手史料。', NULL, '第一', '第一手史料指直接产生于历史事件发生时期的原始资料，如档案、日记、实物等；第二手史料则是后人根据第一手史料加工整理的材料。', 'single_choice', ARRAY['史学理论与方法','史料分类'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'intermediate', '高三', '1919年五四运动爆发，其导火索是巴黎和会上中国外交的失败。五四运动后期，中心由北京转移到______，主力由学生转变为______。', NULL, '上海|工人', '五四运动前期以北京学生为主，6月3日后，运动中心转移到上海，工人阶级作为独立政治力量登上历史舞台，成为运动主力。', 'single_choice', ARRAY['中国近代史','五四运动','新民主主义革命'], 'ai_generated', '');

