INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高二', '鸦片战争后，中国逐步沦为半殖民地半封建社会的主要表现有？（多选）', [{"label": "A", "text": "民族资本主义迅速发展"}, {"label": "B", "text": "自然经济开始解体"}, {"label": "C", "text": "领土主权遭到破坏"}, {"label": "D", "text": "清政府成为列强统治工具"}, {"label": "E", "text": "西方思想传入中国"}], 'CBE', '领土主权破坏和自然经济解体是鸦片战争后的直接结果；清政府成为列强统治工具是《辛丑条约》后的情况；民族资本主义在洋务运动后才逐步发展。', 'single_choice', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高二', '下列关于辛亥革命的叙述，正确的有？（多选）', [{"label": "A", "text": "建立了资产阶级共和国"}, {"label": "B", "text": "结束了两千多年的君主专制制度"}, {"label": "C", "text": "完成了反帝反封建的革命任务"}, {"label": "D", "text": "推翻了清王朝的统治"}, {"label": "E", "text": "使民主共和观念深入人心"}], 'DBAE', '辛亥革命推翻了清朝，结束了君主专制，建立了中华民国，传播了民主共和观念，但没有彻底完成反帝反封建的任务。', 'single_choice', ARRAY['中国近现代史'], 'ai_generated', '');
