INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'intermediate', '高三', '简述鸦片战争爆发的主要原因。', NULL, '根本原因：英国完成工业革命后，急需扩大海外市场和原料产地，把中国作为侵略目标。直接原因：林则徐虎门销烟（1839年），英国以此为借口发动侵略战争。', '鸦片战争爆发的根本原因是英国工业革命后的扩张需求，直接导火索是虎门销烟。', 'single_choice', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'intermediate', '高一', '同盟会成立后发动的第一次武装起义是？', [{"label": "A", "text": "黄花岗起义"}, {"label": "B", "text": "武昌起义"}, {"label": "C", "text": "萍浏醴起义"}, {"label": "D", "text": "镇南关起义"}], 'C', '1906年的萍浏醴起义是同盟会成立后发动的第一次大规模武装起义。', 'single_choice', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'intermediate', '高三', '袁世凯死后，中国陷入军阀割据局面的根本原因是？', [{"label": "A", "text": "北洋军阀内部分裂"}, {"label": "B", "text": "帝国主义分而治之的政策"}, {"label": "C", "text": "资产阶级力量弱小"}, {"label": "D", "text": "封建经济的分散性"}], 'D', '中国封建经济的分散性是军阀割据局面的根本原因，各地区可以自成体系，形成独立王国。', 'single_choice', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'intermediate', '高三', '中国共产党第一次全国代表大会最后一天的会议转移到哪里举行？', [{"label": "A", "text": "嘉兴南湖"}, {"label": "B", "text": "北京"}, {"label": "C", "text": "广州"}, {"label": "D", "text": "上海"}], 'A', '中共一大因受到法租界巡捕干扰，最后一天的会议转移到浙江嘉兴南湖的一艘游船上举行。', 'single_choice', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
