INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '赤道与两极地区的气温差异主要是由于什么因素造成的？', [{"label": "A", "text": "海陆分布"}, {"label": "B", "text": "纬度位置"}, {"label": "C", "text": "地形地势"}, {"label": "D", "text": "洋流"}], 'B', '纬度位置是影响气温的基本因素，赤道地区纬度低，太阳高度角大，获得的太阳辐射多，气温高；两极地区纬度高，太阳高度角小，获得的太阳辐射少，气温低。', 'single_choice', ARRAY['气候','气温分布','纬度位置'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');

-- Batch 39
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '我国东部地区降水主要集中在夏季，这主要受什么季风的影响？', [{"label": "A", "text": "东南季风"}, {"label": "B", "text": "西南季风"}, {"label": "C", "text": "西北季风"}, {"label": "D", "text": "东北季风"}], 'A', '我国东部地区属于季风气候区，夏季受来自太平洋的东南季风影响，降水丰沛；冬季受来自蒙古-西伯利亚的西北季风影响，降水较少。', 'single_choice', ARRAY['气候','季风气候','降水分布'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '地中海气候的特征是夏季高温干燥，冬季温和多雨。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '正确', '地中海气候分布在南北纬30°-40°的大陆西岸，夏季受副热带高气压带控制，炎热干燥；冬季受西风带控制，温和多雨。', 'true_false', ARRAY['气候','地中海气候','气候特征'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '影响气候的主要因素包括______、______和______。', NULL, '纬度位置、海陆位置、地形地势', '纬度位置影响太阳辐射量，海陆位置影响降水和气温年较差，地形地势影响气温随海拔变化及迎风坡降水。', 'fill_blank', ARRAY['气候','气候影响因素','纬度位置'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '请简述温带季风气候的分布规律和主要特征。', NULL, '温带季风气候主要分布在亚洲东部，如我国秦岭-淮河以北地区。其特征是夏季高温多雨，冬季寒冷干燥，四季分明。', '温带季风气候受海陆热力性质差异影响，夏季风从海洋吹向陆地，带来降水；冬季风从陆地吹向海洋，寒冷干燥。', 'short_answer', ARRAY['气候','温带季风气候','气候分布'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '下列哪些因素会影响一个地区的降水？', [{"label": "A", "text": "纬度位置"}, {"label": "B", "text": "海陆位置"}, {"label": "C", "text": "地形地势"}, {"label": "D", "text": "洋流"}], 'ABCD', '纬度位置影响大气环流，海陆位置影响水汽来源，地形地势影响迎风坡和背风坡降水，洋流影响沿岸地区的降水和气温。', 'multiple_choice', ARRAY['气候','降水影响因素','纬度位置'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '下列哪个地区属于热带雨林气候？', [{"label": "A", "text": "撒哈拉沙漠"}, {"label": "B", "text": "亚马孙平原"}, {"label": "C", "text": "地中海沿岸"}, {"label": "D", "text": "蒙古高原"}], 'B', '亚马孙平原位于赤道附近，常年受赤道低气压带控制，终年高温多雨，属于热带雨林气候。撒哈拉沙漠为热带沙漠气候，地中海沿岸为地中海气候，蒙古高原为温带大陆性气候。', 'single_choice', ARRAY['气候','热带雨林气候','气候分布'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '山地的______坡通常降水较多，而______坡降水较少。', NULL, '迎风、背风', '暖湿气流在迎风坡被迫抬升，水汽凝结形成降水；背风坡气流下沉，降水稀少，形成雨影区。', 'fill_blank', ARRAY['气候','地形雨','迎风坡'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '请解释为什么同纬度的大陆西岸和东岸气候类型不同？', NULL, '同纬度的大陆西岸和东岸由于海陆位置和大气环流的不同，气候类型存在差异。例如，北纬40°-60°的大陆西岸受西风带影响，形成温带海洋性气候；而大陆东岸受季风影响，形成温带季风气候。', '海陆位置不同导致受不同风带和气压带控制，加之洋流影响，使得西岸和东岸气候特征迥异。', 'short_answer', ARRAY['气候','海陆位置','大气环流'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '秦岭—淮河一线大致与我国1月0℃等温线、800毫米年等降水量线吻合，是温带季风气候与亚热带季风气候的分界线。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '正确', '秦岭—淮河一线是我国重要的地理分界线，大致与1月0℃等温线、800毫米年等降水量线重合，也是温带季风气候与亚热带季风气候的分界线。', 'true_false', ARRAY['中国地理','秦岭—淮河一线','气候分界线'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '我国地势第二级阶梯上的主要地形类型是（  ）。', [{"label": "A", "text": "山地和高原"}, {"label": "B", "text": "平原和丘陵"}, {"label": "C", "text": "高原和盆地"}, {"label": "D", "text": "平原和盆地"}], 'C', '我国地势第二级阶梯包括内蒙古高原、黄土高原、云贵高原和塔里木盆地、准噶尔盆地、四川盆地等，以高原和盆地为主。', 'single_choice', ARRAY['中国地理','地势阶梯','地形类型'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '下列河流中，属于内流河的是（  ）。', [{"label": "A", "text": "长江"}, {"label": "B", "text": "黄河"}, {"label": "C", "text": "塔里木河"}, {"label": "D", "text": "珠江"}], 'C', '内流河是指最终未流入海洋的河流，塔里木河是我国最长的内流河，而长江、黄河、珠江都是外流河。', 'single_choice', ARRAY['中国地理','内流河','河流分类'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '我国少数民族人口最多的是（  ）。', [{"label": "A", "text": "回族"}, {"label": "B", "text": "壮族"}, {"label": "C", "text": "满族"}, {"label": "D", "text": "维吾尔族"}], 'B', '根据第七次人口普查数据，壮族是我国人口最多的少数民族，主要分布在广西壮族自治区。', 'single_choice', ARRAY['中国地理','少数民族','人口分布'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '我国四大工业基地中，以轻工业为主的是（  ）。', [{"label": "A", "text": "辽中南工业基地"}, {"label": "B", "text": "京津唐工业基地"}, {"label": "C", "text": "沪宁杭工业基地"}, {"label": "D", "text": "珠江三角洲工业基地"}], 'D', '珠江三角洲工业基地以轻工业为主，如电子、家电、服装等，而其他三个工业基地为重工业或综合性工业基地。', 'single_choice', ARRAY['中国地理','工业基地','轻工业'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '我国南水北调工程将长江流域的水调往（  ）。', [{"label": "A", "text": "华北和西北"}, {"label": "B", "text": "华北和东北"}, {"label": "C", "text": "西北和西南"}, {"label": "D", "text": "东北和西北"}], 'A', '南水北调工程旨在缓解华北和西北地区水资源短缺问题，分东、中、西三条调水线路。', 'single_choice', ARRAY['中国地理','南水北调','水资源调配'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '我国冬季南北温差大，主要原因是（  ）。', [{"label": "A", "text": "纬度位置"}, {"label": "B", "text": "海陆位置"}, {"label": "C", "text": "地形因素"}, {"label": "D", "text": "洋流影响"}], 'A', '我国南北跨纬度广，冬季太阳直射南半球，北方正午太阳高度角小、白昼短，获得热量少，南方则相反，导致南北温差大。', 'single_choice', ARRAY['中国地理','冬季气温','纬度影响'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '世界上面积最大的淡水湖是哪个？', [{"label": "A", "text": "里海"}, {"label": "B", "text": "苏必利尔湖"}, {"label": "C", "text": "贝加尔湖"}, {"label": "D", "text": "维多利亚湖"}], 'B', '苏必利尔湖是北美五大湖中最大的一个，也是世界上面积最大的淡水湖，面积约8.21万平方千米。里海是咸水湖，贝加尔湖是深度最大的淡水湖，维多利亚湖是非洲最大淡水湖。', 'single_choice', ARRAY['世界地理','湖泊'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '亚马孙平原是世界上最大的平原，它位于哪个大洲？', [{"label": "A", "text": "亚洲"}, {"label": "B", "text": "非洲"}, {"label": "C", "text": "南美洲"}, {"label": "D", "text": "北美洲"}], 'C', '亚马孙平原位于南美洲北部，由亚马孙河冲积而成，面积约560万平方千米，是世界上最大的平原。', 'single_choice', ARRAY['世界地理','平原'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '马六甲海峡连接了哪两个大洋？', [{"label": "A", "text": "太平洋和印度洋"}, {"label": "B", "text": "太平洋和大西洋"}, {"label": "C", "text": "印度洋和大西洋"}, {"label": "D", "text": "北冰洋和太平洋"}], 'A', '马六甲海峡位于东南亚，是连接太平洋和印度洋的重要海上通道，也是世界上最繁忙的海峡之一。', 'single_choice', ARRAY['世界地理','海峡'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '世界上最大的半岛是哪个？', [{"label": "A", "text": "阿拉伯半岛"}, {"label": "B", "text": "印度半岛"}, {"label": "C", "text": "中南半岛"}, {"label": "D", "text": "斯堪的纳维亚半岛"}], 'A', '阿拉伯半岛位于亚洲西南部，面积约300万平方千米，是世界上最大的半岛。', 'single_choice', ARRAY['世界地理','半岛'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
