INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '请简述热带雨林气候的特点。', NULL, '全年高温多雨，气温年较差小，降水丰富且分配均匀。', '热带雨林气候主要分布在赤道附近，如亚马孙平原、刚果盆地等，特点是终年高温多雨，月均温一般在25℃以上，年降水量2000毫米以上。', 'short_answer', ARRAY['世界地理','气候'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '以下哪些是南美洲的主要河流？', [{"label": "A", "text": "亚马孙河"}, {"label": "B", "text": "密西西比河"}, {"label": "C", "text": "拉普拉塔河"}, {"label": "D", "text": "刚果河"}], 'AC', '亚马孙河和拉普拉塔河均位于南美洲。密西西比河在北美洲，刚果河在非洲。', 'multiple_choice', ARRAY['世界地理','河流'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
