INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '世界上流量最大的河流是亚马孙河。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '正确', '亚马孙河位于南美洲，流量巨大，平均流量约21.9万立方米/秒，是世界上流量最大的河流。', 'true_false', ARRAY['世界地理','河流'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
