INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '尼罗河注入哪个海？', [{"label": "A", "text": "地中海"}, {"label": "B", "text": "红海"}, {"label": "C", "text": "阿拉伯海"}, {"label": "D", "text": "黑海"}], 'A', '尼罗河自南向北流经非洲东北部，最终注入地中海，是世界上最长的河流。', 'single_choice', ARRAY['世界地理','河流'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '简述等高线地形图中，等高线密集和稀疏分别表示什么地形特征？', NULL, '等高线密集表示坡度陡，等高线稀疏表示坡度缓。', '等高线是地图上高程相等的点连线。等高线密集处单位距离内高差大，坡度陡；稀疏处坡度缓。', 'short_answer', ARRAY['地球与地图','等高线','地形图'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '在经纬网地图上，经线指示南北方向，纬线指示东西方向。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '正确', '经线连接南北两极，指示南北；纬线与赤道平行，指示东西。', 'true_false', ARRAY['地球与地图','经纬线方向'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '夏至日时，太阳直射点的纬度是____。', NULL, '23.5°N', '夏至日（6月22日前后），太阳直射北回归线，即23.5°N。', 'fill_blank', ARRAY['地球与地图','太阳直射点','夏至'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '下列哪种气候类型主要分布在大陆西岸，且具有冬季温和多雨、夏季炎热干燥的特点？', [{"label": "A", "text": "温带海洋性气候"}, {"label": "B", "text": "地中海气候"}, {"label": "C", "text": "亚热带季风气候"}, {"label": "D", "text": "温带大陆性气候"}], 'B', '地中海气候分布于南北纬30°-40°的大陆西岸，受副热带高气压带和西风带交替控制，形成冬雨夏干的气候特征。', 'single_choice', ARRAY['气候','气候类型','地中海气候'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '以下关于热带雨林气候的描述，正确的是（多选）', [{"label": "A", "text": "全年高温多雨"}, {"label": "B", "text": "主要分布在赤道附近"}, {"label": "C", "text": "有明显的干湿季"}, {"label": "D", "text": "植被为热带雨林"}], 'ABD', '热带雨林气候全年受赤道低气压带控制，高温多雨，无明显季节变化，植被为热带雨林。选项C错误，热带草原气候才有干湿季。', 'multiple_choice', ARRAY['气候','气候类型','热带雨林气候'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '我国东部季风区最主要的降水类型是________。', NULL, '锋面雨', '我国东部季风区降水主要来自夏季风带来的暖湿气流与北方冷空气交汇形成的锋面雨，尤其是梅雨季节。', 'fill_blank', ARRAY['气候','降水类型','锋面雨'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '请简述影响气候的主要因素。', NULL, '纬度位置、海陆位置、地形地势、洋流、大气环流等。', '纬度影响太阳辐射，海陆影响水汽和温差，地形影响气温和降水，洋流影响沿岸气候，大气环流影响全球气候分布。', 'short_answer', ARRAY['气候','影响气候的因素'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '影响我国降水的夏季风主要来自________洋和________洋。', NULL, '太平 印度', '我国东部和南部夏季受来自太平洋的东南季风和来自印度洋的西南季风影响，带来丰富降水。', 'fill_blank', ARRAY['气候','季风','降水'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '温带大陆性气候的显著特征是（ ）', [{"label": "A", "text": "全年温和湿润"}, {"label": "B", "text": "冬季寒冷干燥，夏季炎热多雨"}, {"label": "C", "text": "冬季寒冷，夏季炎热，全年降水稀少"}, {"label": "D", "text": "全年高温多雨"}], 'C', '温带大陆性气候远离海洋，降水稀少，气温年较差大，冬季寒冷，夏季炎热。', 'single_choice', ARRAY['气候','气候类型','温带大陆性气候'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '请解释山地迎风坡降水多的原因。', NULL, '暖湿气流在迎风坡被迫抬升，温度降低，水汽凝结形成降水。', '地形雨的形成原理：湿润气流遇山地阻挡，沿坡上升，气温下降，水汽饱和凝结成云致雨。', 'short_answer', ARRAY['气候','降水类型','地形雨'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '我国地势第二级阶梯上的主要地形类型是（ ）和盆地。', NULL, '高原', '我国地势第二级阶梯海拔多在1000-2000米，主要地形类型是高原和盆地，如内蒙古高原、黄土高原、云贵高原以及塔里木盆地、准噶尔盆地、四川盆地等。', 'fill_blank', ARRAY['中国地理','中国地形','地势阶梯'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '长江干流流经的省级行政区中，位于上游的是（ ）。', NULL, '青海省', '长江发源于青海省唐古拉山脉，干流流经青海、西藏、四川、云南、重庆、湖北、湖南、江西、安徽、江苏、上海等11个省级行政区，其中青海省位于上游。', 'fill_blank', ARRAY['中国地理','长江','河流'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '秦岭—淮河一线是我国重要的地理分界线，以下描述正确的是（ ）。', [{"label": "A", "text": "A. 相当于1月0℃等温线"}, {"label": "B", "text": "B. 相当于800毫米年等降水量线"}, {"label": "C", "text": "C. 是亚热带与暖温带的分界线"}, {"label": "D", "text": "D. 是湿润区与半湿润区的分界线"}], 'ABCD', '秦岭—淮河一线是我国重要的地理分界线，大致与1月0℃等温线、800毫米年等降水量线、亚热带与暖温带分界线、湿润区与半湿润区分界线一致。', 'multiple_choice', ARRAY['中国地理','秦岭-淮河','地理分界线'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '我国最大的内流河是（ ）。', [{"label": "A", "text": "A. 塔里木河"}, {"label": "B", "text": "B. 黄河"}, {"label": "C", "text": "C. 长江"}, {"label": "D", "text": "D. 珠江"}], 'A', '塔里木河位于新疆塔里木盆地，全长约2179千米，是我国最长的内流河。黄河、长江、珠江均为外流河。', 'single_choice', ARRAY['中国地理','河流','内流河'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '我国少数民族人口最多的民族是（ ）。', [{"label": "A", "text": "A. 壮族"}, {"label": "B", "text": "B. 回族"}, {"label": "C", "text": "C. 满族"}, {"label": "D", "text": "D. 维吾尔族"}], 'A', '壮族是我国少数民族中人口最多的民族，主要分布在广西壮族自治区。', 'single_choice', ARRAY['中国地理','民族','人口'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '我国四大工业基地中，以重工业为主的是（ ）。', [{"label": "A", "text": "A. 辽中南工业基地"}, {"label": "B", "text": "B. 京津唐工业基地"}, {"label": "C", "text": "C. 沪宁杭工业基地"}, {"label": "D", "text": "D. 珠江三角洲工业基地"}], 'A', '辽中南工业基地是我国著名的重工业基地，以沈阳、大连为中心，拥有丰富的煤、铁等资源。', 'single_choice', ARRAY['中国地理','工业基地','重工业'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '我国领土最南端在（ ）。', [{"label": "A", "text": "A. 曾母暗沙"}, {"label": "B", "text": "B. 黄岩岛"}, {"label": "C", "text": "C. 钓鱼岛"}, {"label": "D", "text": "D. 赤尾屿"}], 'A', '我国领土最南端为南沙群岛中的曾母暗沙，位于北纬4°附近。', 'single_choice', ARRAY['中国地理','领土','疆域'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '下列哪条河流是南美洲最长的河流，也是世界上水量最大的河流？', [{"label": "A", "text": "密西西比河"}, {"label": "B", "text": "亚马孙河"}, {"label": "C", "text": "刚果河"}, {"label": "D", "text": "长江"}], 'B', '亚马孙河全长约6400千米，是南美洲最长的河流，且流量居世界第一，远超其他河流。', 'single_choice', ARRAY['世界地理','河流','南美洲'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '关于亚洲地理特征，下列叙述正确的有？', [{"label": "A", "text": "亚洲是世界上面积最大的大洲"}, {"label": "B", "text": "亚洲的地势中部高、四周低"}, {"label": "C", "text": "亚洲气候类型复杂多样，季风气候显著"}, {"label": "D", "text": "亚洲河流全部注入太平洋和印度洋"}], 'ABC', '亚洲面积约4400万平方千米，居世界第一；地势中部高、四周低，青藏高原为世界屋脊；气候类型复杂，季风气候典型。但亚洲北部河流如鄂毕河注入北冰洋，并非全部注入太平洋和印度洋，故D错误。', 'multiple_choice', ARRAY['世界地理','亚洲','地势'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '北极地区比南极地区更寒冷。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '错误', '南极地区是大陆，海拔高，冰层厚，反射阳光强，且受极地高压控制，气温更低，是地球上最寒冷的地方。北极地区是海洋，受北大西洋暖流等影响，相对温暖。', 'true_false', ARRAY['世界地理','极地地区','气候比较'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '中东地区被称为“三洲五海之地”，其中“五海”指的是哪些海域？', NULL, '地中海、红海、阿拉伯海、黑海、里海', '中东地处亚、非、欧三洲交界，周围有地中海、红海、阿拉伯海、黑海和里海（内陆湖），故称五海。', 'fill_blank', ARRAY['世界地理','中东','地理位置'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '下列哪个国家不属于“金砖国家”（BRICS）？', [{"label": "A", "text": "巴西"}, {"label": "B", "text": "俄罗斯"}, {"label": "C", "text": "印度"}, {"label": "D", "text": "日本"}], 'D', '金砖国家包括巴西、俄罗斯、印度、中国和南非。日本不属于。', 'single_choice', ARRAY['世界地理','国际组织','金砖国家'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '北美洲面积最大的国家是？', [{"label": "A", "text": "美国"}, {"label": "B", "text": "加拿大"}, {"label": "C", "text": "墨西哥"}, {"label": "D", "text": "格陵兰（丹麦）"}], 'B', '加拿大面积约998万平方千米，是北美洲面积最大的国家，美国第二，墨西哥第三。格陵兰是丹麦的自治领土，不是独立国家。', 'single_choice', ARRAY['世界地理','北美洲','国家面积'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '地球的真实形状最接近以下哪种描述？', [{"label": "A", "text": "A. 正球体"}, {"label": "B", "text": "B. 两极稍扁、赤道略鼓的不规则球体"}, {"label": "C", "text": "C. 椭球体"}, {"label": "D", "text": "D. 南北不对称的梨形体"}], 'B', '地球是一个两极稍扁、赤道略鼓的不规则球体。虽然从太空看近似球体，但精确测量表明赤道半径比极半径长约21千米，因此B正确。A选项正球体是理想化模型；C选项椭球体是近似，但地球并非标准椭球；D选项梨形体不准确。', 'single_choice', ARRAY['地球与地图','地球形状'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '在地图上，判断方向的三种主要方法是什么？', NULL, '一般定向法（上北下南，左西右东）、指向标定向法（指向标箭头指向北）、经纬网定向法（经线指示南北，纬线指示东西）。', '地图上常用这三种方法确定方向。一般定向法适用于无特殊标记的地图；指向标定向法适用于有指向标的地图；经纬网定向法适用于有经纬网的地图。', 'short_answer', ARRAY['地球与地图','地图方向'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '比例尺为1:1000000的地图上，量得甲乙两地距离为5厘米，则实地距离是多少千米？请写出计算过程。', NULL, '50千米', '比例尺1:1000000表示图上1厘米代表实地1000000厘米，即10千米。所以5厘米代表5×10=50千米。计算过程：5×1000000=5000000厘米=50千米。', 'short_answer', ARRAY['地球与地图','比例尺'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '下列哪个因素不是影响气候的主要因素？', [{"label": "A", "text": "A. 纬度位置"}, {"label": "B", "text": "B. 海陆位置"}, {"label": "C", "text": "C. 地形地势"}, {"label": "D", "text": "D. 人口分布"}], 'D', '气候的主要影响因素包括纬度位置、海陆位置、地形地势和洋流等，人口分布不是影响气候的主要因素。', 'single_choice', ARRAY['气候','影响因素'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '简述季风气候的特点及其对我国农业生产的影响。', NULL, '季风气候的特点是夏季高温多雨，冬季寒冷干燥，雨热同期。这种气候有利于农作物生长，但降水季节和年际变化大，容易引发旱涝灾害，影响农业稳产。', '季风气候的雨热同期为农业生产提供了有利条件，但降水不稳定性也带来挑战。', 'short_answer', ARRAY['气候','季风气候','农业'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '说明全球变暖可能带来的主要环境问题。', NULL, '全球变暖可能导致海平面上升、极端天气事件增多、冰川融化、生态系统失衡等环境问题。', '全球变暖是当前重要的气候问题，影响深远。', 'short_answer', ARRAY['气候','全球变暖','环境问题'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '简述黄河的发源地、注入的海洋以及黄河下游形成的地上河现象的原因。', NULL, '黄河发源于青藏高原的巴颜喀拉山脉，注入渤海。黄河下游形成地上河的原因：黄河中游流经黄土高原，携带大量泥沙；下游进入华北平原，河道变宽，流速变缓，泥沙沉积，河床抬高，形成地上河。', '黄河全长约5464公里，是中国第二长河。中游黄土高原水土流失严重，大量泥沙随河水进入下游，由于下游地势平坦，泥沙淤积，使河床高出两岸地面，形成地上河。', 'short_answer', ARRAY['中国地理','黄河'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '请列举中国四大高原的名称，并说明其中面积最大的高原是哪个。', NULL, '四大高原：青藏高原、内蒙古高原、黄土高原、云贵高原。面积最大的是青藏高原。', '青藏高原位于中国西南部，平均海拔4000米以上，面积约250万平方千米，是世界上海拔最高、面积最大的高原。内蒙古高原、黄土高原、云贵高原面积依次减小。', 'short_answer', ARRAY['中国地理','地形'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '请列举两个位于非洲的世界自然奇观。', NULL, '撒哈拉沙漠、维多利亚瀑布', '撒哈拉沙漠是世界上最大的热沙漠，维多利亚瀑布是世界上最壮观的瀑布之一，均位于非洲。其他合理答案如乞力马扎罗山、东非大裂谷等也可接受。', 'short_answer', ARRAY['世界地理','非洲自然奇观'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '简述亚马孙河的特征及其对周边环境的影响。', NULL, '亚马孙河是世界上流量最大、流域面积最广的河流。它流经亚马孙雨林，对维持全球气候平衡和生物多样性至关重要。河流的泛滥为周边地区带来肥沃的土壤，但过度开发也会导致生态破坏。', '亚马孙河位于南美洲，其流域覆盖大面积热带雨林，被称为“地球之肺”。河流特征包括水量巨大、支流众多；对环境的影响包括调节气候、提供栖息地等。', 'short_answer', ARRAY['世界地理','河流','亚马孙河'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '简述纬线的主要特征。', NULL, '纬线是与地轴垂直并且环绕地球一周的圆圈；纬线指示东西方向；纬线长度不等，赤道最长，向两极逐渐缩短；纬线互相平行。', '纬线的特征包括形状、方向、长度和相互关系。', 'short_answer', ARRAY['地球与地图','纬线特征'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '如何利用经纬网确定地球表面任意一点的位置？请举例说明。', NULL, '利用经纬网，我们可以读出某点的经度和纬度，经度表示东西位置，纬度表示南北位置。例如，北京大致位于（40°N，116°E）。', '经纬网由经线和纬线交织而成，经度与纬度共同确定一个点的地理坐标。', 'short_answer', ARRAY['地球与地图','经纬网定位'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '以下哪个因素不是影响气候的主要因素？', [{"label": "A", "text": "纬度位置"}, {"label": "B", "text": "海陆分布"}, {"label": "C", "text": "地形"}, {"label": "D", "text": "人口数量"}], 'D', '影响气候的主要因素包括纬度位置、海陆分布和地形，人口数量对气候影响很小。', 'single_choice', ARRAY['气候','影响因素'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '简述地中海气候的特点及其分布规律。', NULL, '地中海气候的特点是夏季炎热干燥，冬季温和多雨。主要分布在南北纬30°-40°大陆西岸，如地中海沿岸、美国加州、南非开普敦等地。', '地中海气候受副热带高气压带和西风带交替控制，夏季炎热干燥，冬季温和多雨。', 'short_answer', ARRAY['气候','地中海气候'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '为什么赤道地区全年高温多雨，而两极地区寒冷干燥？', NULL, '赤道地区太阳高度角大，接受的太阳辐射多，且受赤道低气压带控制，盛行上升气流，多对流雨，所以高温多雨。两极地区太阳高度角小，接受的太阳辐射少，且受极地高气压带控制，盛行下沉气流，降水稀少，所以寒冷干燥。', '太阳辐射的纬度差异是根本原因，气压带和风带影响降水和气温。', 'short_answer', ARRAY['气候','全球气候差异'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '我国地势第二级阶梯上的主要地形类型是：', [{"label": "A", "text": "平原和丘陵"}, {"label": "B", "text": "高原和盆地"}, {"label": "C", "text": "山地和高原"}, {"label": "D", "text": "平原和盆地"}], 'B', '我国地势第二级阶梯包括内蒙古高原、黄土高原、云贵高原和塔里木盆地、准噶尔盆地、四川盆地等，主要地形为高原和盆地。', 'single_choice', ARRAY['中国地理','地形'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '简述秦岭-淮河一线在我国地理上的重要意义（至少两点）。', NULL, '①亚热带与暖温带的分界线；②湿润区与半湿润区的分界线；③水田农业与旱作农业的分界线；④南方与北方的分界线等（任答两点即可）。', '秦岭-淮河一线是我国重要的地理分界线，大致与1月0℃等温线和800毫米年等降水量线吻合，对气候、农业、植被等有显著影响。', 'short_answer', ARRAY['中国地理','分界线'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '说明我国长江三角洲地区成为“鱼米之乡”的自然条件。', NULL, '地势低平，土壤肥沃；气候温暖湿润，雨热同期；河网密布，水源充足；适宜水稻种植和水产养殖。', '长江三角洲地区属于亚热带季风气候，地形平坦，水热条件优越，有利于农业和渔业发展，因此被称为“鱼米之乡”。', 'short_answer', ARRAY['中国地理','区域地理'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '位于南美洲的安第斯山脉是由哪两大板块碰撞形成的？', [{"label": "A", "text": "A. 太平洋板块与美洲板块"}, {"label": "B", "text": "B. 南极洲板块与美洲板块"}, {"label": "C", "text": "C. 纳斯卡板块与美洲板块"}, {"label": "D", "text": "D. 太平洋板块与南极洲板块"}], 'C', '安第斯山脉位于南美洲西海岸，是纳斯卡板块（属于太平洋板块的一部分）向南美洲板块（美洲板块的一部分）俯冲碰撞形成的。选项A中太平洋板块与美洲板块的碰撞主要形成北美洲西部的山脉；选项B南极洲板块与美洲板块的碰撞主要形成南美洲南端的山脉；选项D太平洋板块与南极洲板块的碰撞主要形成太平洋中脊。', 'single_choice', ARRAY['世界地理','板块构造','山脉'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '请简述地中海气候的分布规律及其典型特征。', NULL, '地中海气候主要分布在南北纬30°-40°的大陆西岸，典型特征为夏季炎热干燥、冬季温和多雨。', '地中海气候受副热带高压带和西风带的交替控制，夏季受副热带高压控制，盛行下沉气流，炎热干燥；冬季受西风带控制，温和多雨。典型地区包括地中海沿岸、美国加州、南非开普敦、澳大利亚西南部、智利中部等。', 'short_answer', ARRAY['世界地理','气候','地中海气候'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '比较亚洲和欧洲的地形特征，并各举一个典型地形区为例。', NULL, '亚洲地形复杂多样，以高原、山地为主，地势中部高四周低，典型地形区如青藏高原；欧洲地形以平原为主，地势低平，典型地形区如东欧平原。', '亚洲平均海拔高，有世界最高的青藏高原和喜马拉雅山脉；欧洲是世界上平均海拔最低的大洲，平原面积广阔，如东欧平原、西欧平原。', 'short_answer', ARRAY['世界地理','亚洲','欧洲'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '在地球仪上，纬线指示东西方向，经线指示南北方向。下列有关经线和纬线的说法，正确的是（ ）', [{"label": "A", "text": "A. 所有经线的长度都相等"}, {"label": "B", "text": "B. 所有纬线的长度都相等"}, {"label": "C", "text": "C. 经线是平行于赤道的圆圈"}, {"label": "D", "text": "D. 纬线是连接南北两极的半圆"}], 'A', '经线是连接南北两极的半圆，所有经线长度相等；纬线是与赤道平行的圆圈，长度从赤道向两极递减，因此并非所有纬线长度相等。B错误，C、D描述颠倒。', 'single_choice', ARRAY['地球与地图','经线与纬线'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '某点以东是西半球，以西是东半球，以北有极昼极夜现象，以南为温带。该点的经纬度位置是（ ）', [{"label": "A", "text": "A. 66.5°S, 20°W"}, {"label": "B", "text": "B. 66.5°N, 160°E"}, {"label": "C", "text": "C. 66.5°N, 20°W"}, {"label": "D", "text": "D. 66.5°S, 160°E"}], 'B', '东西半球分界线是20°W和160°E。20°W以东为东半球，以西为西半球；160°E以东为西半球，以西为东半球。根据题意，该点以东为西半球、以西为东半球，因此位于160°E经线上。以北有极昼极夜现象，说明位于北极圈（66.5°N）上，以南为温带，符合。所以经纬度为(66.5°N, 160°E)。', 'single_choice', ARRAY['地球与地图','经纬度定位'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '在地图上，比例尺为1:5000000，量得甲乙两地距离为3厘米，则甲乙两地的实际距离为____千米。', NULL, '150', '实际距离 = 图上距离 / 比例尺 = 3厘米 / (1:5000000) = 3厘米 × 5000000 = 15000000厘米 = 150千米。注意单位换算。', 'fill_blank', ARRAY['地球与地图','比例尺'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '简述利用经纬网可以确定地球表面任意一点位置的原因，并说明经度和纬度的划分方法。', NULL, '经纬网是地球仪或地图上由经线和纬线交织成的网格。经线连接南北两极，指示南北方向；纬线平行于赤道，指示东西方向。经度以本初子午线为起始线，向东向西各分180°；纬度以赤道为起始线，向南向北各分90°。通过经纬度的组合，可以唯一确定地球表面任意一点的位置。', '本题考察经纬网的作用和经纬度划分。经纬网提供坐标系统，经度和纬度构成有序数对，因此可以精确定位。', 'short_answer', ARRAY['地球与地图','经纬网'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '地球自转产生昼夜交替现象。假设地球不自转，仅绕太阳公转，地球表面是否还有昼夜交替？请说明理由。', NULL, '有。理由：即使地球不自转，由于地球绕太阳公转，地球表面也会出现昼夜交替，但周期为一年。具体来说，地球公转一周，地球上的某点会经历一次昼夜交替（即半年白天，半年黑夜）。', '昼夜交替的根本原因是地球的自转，但若不自转，公转也会导致太阳照射方向变化，从而产生昼夜交替，只是周期长。', 'short_answer', ARRAY['地球与地图','地球运动'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '当某地受单一气团控制时，其天气状况通常表现为：', [{"label": "A", "text": "A. 阴雨连绵"}, {"label": "B", "text": "B. 晴朗干燥"}, {"label": "C", "text": "C. 狂风暴雨"}, {"label": "D", "text": "D. 气温骤降"}], 'B', '单一气团控制下，气团内部性质相对均匀，无明显的上升或下沉气流，因此天气通常晴朗干燥。阴雨连绵、狂风暴雨、气温骤降通常与锋面活动有关。', 'single_choice', ARRAY['气候','气团'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '下列气候类型中，受副热带高气压带和西风带交替控制形成的是：', [{"label": "A", "text": "A. 热带雨林气候"}, {"label": "B", "text": "B. 温带海洋性气候"}, {"label": "C", "text": "C. 地中海气候"}, {"label": "D", "text": "D. 亚热带季风气候"}], 'C', '地中海气候主要分布在南北纬30°-40°的大陆西岸，夏季受副热带高气压带控制，炎热干燥；冬季受西风带控制，温和多雨。热带雨林气候受赤道低气压带控制；温带海洋性气候全年受西风带影响；亚热带季风气候受季风环流控制。', 'single_choice', ARRAY['气候','气压带风带'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '我国冬季最冷的地方是黑龙江漠河，其气候类型属于_____。', NULL, '温带季风气候', '漠河位于我国东北地区，属于温带季风气候，冬季受冬季风影响，寒冷干燥，且纬度高，气温低，是我国冬季最冷的地区。', 'fill_blank', ARRAY['气候','中国气候'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '请简述全球变暖对气候带分布可能产生的影响。', NULL, '全球变暖可能导致气候带向高纬度移动，例如温带气候区可能向北扩展，亚寒带和寒带气候区面积缩小；同时，降水格局发生变化，一些地区变得更加干旱，另一些地区降水增加。', '全球变暖使温度升高，气候带整体向极地移动，影响生态系统和农业生产。例如，热带气候带可能扩大，温带气候带北移，寒带气候带缩小。', 'short_answer', ARRAY['气候','全球变暖'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '分析安第斯山脉南段东西两侧气候差异及其成因。', NULL, '安第斯山脉南段西侧为温带海洋性气候，全年温和多雨；东侧为温带大陆性气候，降水稀少。成因：西侧位于盛行西风的迎风坡，多地形雨；东侧位于背风坡，降水少。', '安第斯山脉南段（40°S以南）位于西风带，西侧受来自海洋的盛行西风影响，加上地形抬升，降水丰富；东侧处于背风坡，气流下沉，降水稀少，形成明显的雨影区。', 'short_answer', ARRAY['气候','地形雨'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '秦岭—淮河一线是我国重要的地理分界线，下列哪条地理分界线与其大致吻合？', [{"label": "A", "text": "A. 1月0℃等温线"}, {"label": "B", "text": "B. 400毫米年等降水量线"}, {"label": "C", "text": "C. 季风区与非季风区分界线"}, {"label": "D", "text": "D. 地势第二、三级阶梯分界线"}], 'A', '秦岭—淮河一线大致与1月0℃等温线、800毫米年等降水量线、亚热带与暖温带分界线等吻合。400毫米年等降水量线大致经过大兴安岭—阴山—贺兰山；季风区与非季风区分界线大致经过大兴安岭—阴山—贺兰山—巴颜喀拉山—冈底斯山；地势第二、三级阶梯分界线大致是大兴安岭—太行山—巫山—雪峰山。', 'single_choice', ARRAY['中国地理','秦岭淮河','地理分界线'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '我国地势西高东低，呈三级阶梯分布。下列地形区位于第一级阶梯的是哪个？', [{"label": "A", "text": "A. 云贵高原"}, {"label": "B", "text": "B. 青藏高原"}, {"label": "C", "text": "C. 内蒙古高原"}, {"label": "D", "text": "D. 黄土高原"}], 'B', '我国地势第一级阶梯平均海拔在4000米以上，主要地形区是青藏高原。云贵高原、内蒙古高原、黄土高原均位于第二级阶梯。', 'single_choice', ARRAY['中国地理','地势阶梯','地形区'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '我国最大的内流河是________。', NULL, '塔里木河', '塔里木河位于新疆维吾尔自治区，是我国最长的内流河，全长约2179千米，流域面积约102万平方千米。', 'fill_blank', ARRAY['中国地理','河流','内流河'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '简要说明我国南北方在气候和农业方面的主要差异。', NULL, '南方气候以亚热带季风气候为主，冬季温暖湿润，夏季高温多雨，年降水量大于800毫米；北方以温带季风气候为主，冬季寒冷干燥，夏季高温多雨，年降水量在400-800毫米之间。农业方面，南方以水田农业为主，主要种植水稻、油菜等；北方以旱地农业为主，主要种植小麦、玉米等。', '秦岭—淮河一线是我国南北方的重要分界线，南北气候差异明显，导致农业类型不同。南方水热条件更好，适宜水稻生长；北方降水较少，适宜小麦等旱作作物。', 'short_answer', ARRAY['中国地理','南方地区','北方地区'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '简述长江三角洲地区经济发展的有利条件。', NULL, '长江三角洲地区经济发展的有利条件包括：地理位置优越，濒江临海，交通便利；气候温暖湿润，地形平坦，土壤肥沃，农业基础好；工业基础雄厚，科技实力强；劳动力资源丰富，市场广阔；国家政策支持等。', '长江三角洲是我国经济最发达的地区之一，其有利条件可从自然条件和社会经济条件两方面分析。自然条件包括地形、气候、水源等；社会经济条件包括交通、工业、科技、劳动力、市场等。', 'short_answer', ARRAY['中国地理','长江三角洲','经济发展条件'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '下列哪个国家不属于‘金砖国家’（BRICS）？', [{"label": "A", "text": "巴西"}, {"label": "B", "text": "俄罗斯"}, {"label": "C", "text": "印度"}, {"label": "D", "text": "澳大利亚"}], 'D', '金砖国家包括巴西、俄罗斯、印度、中国和南非。澳大利亚不属于金砖国家。', 'single_choice', ARRAY['世界地理','国际组织'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '简述地中海气候的分布规律及其主要特征。', NULL, '地中海气候主要分布在南北纬30°-40°的大陆西岸，以地中海沿岸最为典型。其特征是夏季炎热干燥，冬季温和多雨。', '地中海气候受副热带高气压带和西风带交替控制，夏季副高控制盛行下沉气流，干燥少雨；冬季西风带控制，带来海洋湿润气流，温和多雨。', 'short_answer', ARRAY['世界地理','气候'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '解释为什么日本多火山和地震，并列举两个著名的日本火山。', NULL, '日本位于太平洋板块与亚欧板块交界处，地壳活跃，因此多火山和地震。著名的日本火山有富士山、樱岛火山等。', '日本地处环太平洋火山地震带，板块碰撞挤压导致地壳不稳定。富士山是日本最高峰，樱岛火山是活火山。', 'short_answer', ARRAY['世界地理','板块构造'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '分析亚马孙平原成为世界最大热带雨林区的自然原因。', NULL, '亚马孙平原位于赤道附近，终年受赤道低气压带控制，盛行上升气流，降水丰富；平原面积广阔，北、西、南三面被高原山地环绕，有利于水汽深入和停留；河流众多，水源充足；纬度低，气温高，蒸发旺盛，形成湿热气候，适合热带雨林生长。', '赤道低气压带控制带来对流雨；地形封闭，水汽不易扩散；热带雨林气候（高温多雨）是植被茂盛的直接原因。', 'short_answer', ARRAY['世界地理','南美洲','自然带'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '哪个海峡连接了太平洋和印度洋，并且位于苏门答腊岛和爪哇岛之间？', [{"label": "A", "text": "马六甲海峡"}, {"label": "B", "text": "巽他海峡"}, {"label": "C", "text": "龙目海峡"}, {"label": "D", "text": "望加锡海峡"}], 'B', '巽他海峡位于苏门答腊岛和爪哇岛之间，连接了印度洋和太平洋；马六甲海峡位于马来半岛和苏门答腊岛之间，龙目海峡位于巴厘岛和龙目岛之间，望加锡海峡位于加里曼丹岛和苏拉威西岛之间。', 'single_choice', ARRAY['世界地理'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '下列哪些国家属于南美洲的“ABC国家”？', [{"label": "A", "text": "阿根廷"}, {"label": "B", "text": "巴西"}, {"label": "C", "text": "智利"}, {"label": "D", "text": "哥伦比亚"}], 'ABC', '南美洲的ABC国家指阿根廷（Argentina）、巴西（Brazil）和智利（Chile），这三个国家名称的首字母分别为A、B、C。', 'multiple_choice', ARRAY['世界地理'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '北极地区的气温比南极地区高，主要原因是北极地区是海洋，而南极地区是陆地。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '正确', '北极地区是北冰洋，海洋比热容大，冬季降温慢；南极地区是南极大陆，陆地比热容小，冬季降温快，因此南极气温更低。', 'true_false', ARRAY['世界地理'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'advanced', '初三', '请写出位于非洲的四大裂谷湖的名称。', NULL, '坦噶尼喀湖、马拉维湖、维多利亚湖、图尔卡纳湖', '东非大裂谷带有一系列湖泊，其中面积较大的四个是坦噶尼喀湖、马拉维湖、维多利亚湖和图尔卡纳湖。维多利亚湖虽不完全在裂谷内，但通常被包括。', 'fill_blank', ARRAY['世界地理'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '地球的真实形状最接近以下哪个？', [{"label": "A", "text": "A. 完美的球体"}, {"label": "B", "text": "B. 两极稍扁、赤道略鼓的不规则球体"}, {"label": "C", "text": "C. 南北半球对称的球体"}, {"label": "D", "text": "D. 像橘子一样扁平的球体"}], 'B', '地球是一个两极稍扁、赤道略鼓的不规则球体，不是完美的球体。', 'single_choice', ARRAY['地球与地图'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '中国的四大高原中，被称为“世界屋脊”的是？', [{"label": "A", "text": "A. 青藏高原"}, {"label": "B", "text": "B. 内蒙古高原"}, {"label": "C", "text": "C. 黄土高原"}, {"label": "D", "text": "D. 云贵高原"}], 'A', '青藏高原平均海拔4000米以上，是世界上海拔最高的高原，有“世界屋脊”之称。', 'single_choice', ARRAY['中国地理'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'intermediate', '初三', '在地球仪上，经度相差1°的纬线长度是（ ）。', [{"label": "A", "text": "赤道上最长，向两极递减"}, {"label": "B", "text": "在赤道上最长，向两极递增"}, {"label": "C", "text": "在赤道上最短，向两极递减"}, {"label": "D", "text": "在赤道上最短，向两极递增"}], 'A', '在地球仪上，纬线长度从赤道向两极递减，赤道最长，两极缩短为点。经度相差1°的纬线弧长，赤道上最长，约111千米，向两极递减。', 'single_choice', ARRAY['地球与地图'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '13-15', 'beginner', '初三', '哪种气候类型全年高温多雨？', [{"label": "A", "text": "A. 热带雨林气候"}, {"label": "B", "text": "B. 温带季风气候"}, {"label": "C", "text": "C. 地中海气候"}, {"label": "D", "text": "D. 寒带气候"}], 'A', '热带雨林气候的特点是全年高温多雨。', 'single_choice', ARRAY['气候'], 'ai_generated', 'batch_geography_13-15_supplement_20260715184922');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '水循环中，目前人类活动影响最大的环节是：', [{"label": "A", "text": "A. 蒸发"}, {"label": "B", "text": "B. 水汽输送"}, {"label": "C", "text": "C. 降水"}, {"label": "D", "text": "D. 地表径流"}], 'D', '人类通过修建水库、跨流域调水、引水灌溉等活动，对地表径流施加显著影响，而对蒸发、水汽输送和降水影响较小。', 'single_choice', ARRAY['水循环'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '从赤道到两极，自然带呈现出有规律的更替，这种地域分异规律的基础是：', [{"label": "A", "text": "A. 水分"}, {"label": "B", "text": "B. 热量"}, {"label": "C", "text": "C. 土壤"}, {"label": "D", "text": "D. 地形"}], 'B', '从赤道到两极，太阳辐射随纬度升高而减少，热量条件变化导致自然带更替，形成纬度地带性分异规律。', 'single_choice', ARRAY['自然带'], 'ai_generated', 'batch_geography_16-18');

-- Batch 40
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '影响农业生产的最基本、最自然的社会经济因素是：', [{"label": "A", "text": "A. 气候"}, {"label": "B", "text": "B. 土壤"}, {"label": "C", "text": "C. 市场"}, {"label": "D", "text": "D. 政策"}], 'C', '气候和土壤属于自然因素，市场是社会经济因素中最基本、最活跃的因素，它决定农业生产的类型和规模。', 'single_choice', ARRAY['农业区位'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '下列工业部门中，属于原料导向型工业的是：', [{"label": "A", "text": "A. 啤酒厂"}, {"label": "B", "text": "B. 水产品加工厂"}, {"label": "C", "text": "C. 电子装配厂"}, {"label": "D", "text": "D. 服装厂"}], 'B', '原料导向型工业通常接近原料产地，水产品加工厂原料易腐烂，需就近加工；啤酒厂是市场导向型，电子装配厂和服装厂是劳动力导向型。', 'single_choice', ARRAY['工业区位'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '下列行为中，有利于实现可持续发展的是：', [{"label": "A", "text": "A. 过度开采地下水，解决水资源短缺"}, {"label": "B", "text": "B. 大量使用化肥农药，提高粮食产量"}, {"label": "C", "text": "C. 推广清洁能源，减少污染物排放"}, {"label": "D", "text": "D. 围湖造田，增加耕地面积"}], 'C', '过度开采地下水会导致地面沉降等环境问题，大量使用化肥农药会污染土壤和水体，围湖造田会破坏湿地生态，均不利于可持续发展。推广清洁能源可减少污染，实现经济与环境协调发展。', 'single_choice', ARRAY['可持续发展'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '以下关于地质构造的叙述，正确的有（ ）', [{"label": "A", "text": "A. 背斜岩层向上拱起，中心岩层新两翼岩层老"}, {"label": "B", "text": "B. 向斜岩层向下弯曲，中心岩层老两翼岩层新"}, {"label": "C", "text": "C. 断层是岩层发生断裂并沿断裂面产生显著位移的地质构造"}, {"label": "D", "text": "D. 背斜顶部受张力，常被侵蚀成谷地"}], 'C,D', '背斜岩层向上拱起，中心岩层老两翼岩层新，A项错误；向斜岩层向下弯曲，中心岩层新两翼岩层老，B项错误。断层是岩层发生断裂并沿断裂面产生显著位移的地质构造，C项正确；背斜顶部受张力，岩石破碎，易被侵蚀成谷地，D项正确。', 'multiple_choice', ARRAY['地质构造','背斜与向斜','断层'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '下列有关大气环流的说法，正确的有（ ）', [{"label": "A", "text": "A. 赤道低气压带是热力因素形成的"}, {"label": "B", "text": "B. 副热带高气压带是动力因素形成的"}, {"label": "C", "text": "C. 信风带的风向是北半球东北信风、南半球东南信风"}, {"label": "D", "text": "D. 中纬西风带的风向是北半球西南风、南半球西北风"}], 'A,B,C', '赤道地区受热多，空气膨胀上升，形成赤道低气压带，是热力因素，A项正确。副热带高气压带是由于气流在高空堆积下沉形成的，是动力因素，B项正确。北半球信风为东北信风，南半球为东南信风，C项正确。中纬西风带北半球为西南风，南半球为西北风，D项错误。', 'multiple_choice', ARRAY['大气环流','气压带风带','三圈环流'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '水循环的主要环节包括（ ）', [{"label": "A", "text": "A. 蒸发"}, {"label": "B", "text": "B. 水汽输送"}, {"label": "C", "text": "C. 降水"}, {"label": "D", "text": "D. 地表径流"}, {"label": "E", "text": "E. 下渗"}], 'A,B,C,D,E', '水循环的主要环节包括蒸发（蒸腾）、水汽输送、降水、地表径流、下渗、地下径流等，因此所有选项均正确。', 'multiple_choice', ARRAY['水循环','水循环环节'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '下列关于自然带的叙述，正确的有（ ）', [{"label": "A", "text": "A. 自然带是陆地上由于气候、土壤、植被等差异而形成的带状区域"}, {"label": "B", "text": "B. 热带雨林带主要分布在赤道附近，气候湿热"}, {"label": "C", "text": "C. 亚热带常绿硬叶林带对应地中海气候"}, {"label": "D", "text": "D. 温带荒漠带主要分布在中纬度大陆内部，降水稀少"}], 'A,B,C,D', '自然带是气候、土壤、植被等综合作用形成的带状区域，A项正确。热带雨林带分布在赤道附近，终年高温多雨，B项正确。亚热带常绿硬叶林带对应地中海气候，夏季炎热干燥，冬季温和多雨，C项正确。温带荒漠带分布在中纬度大陆内部，降水稀少，D项正确。', 'multiple_choice', ARRAY['自然带','气候与自然带','植被分布'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '全球气压带和风带中，由于热力原因形成的气压带是赤道低气压带和________。', [{"label": "A", "text": "A. 副热带高气压带"}, {"label": "B", "text": "B. 副极地低气压带"}, {"label": "C", "text": "C. 极地高气压带"}, {"label": "D", "text": "D. 低纬信风带"}], 'C', '赤道低气压带和极地高气压带是由于地面冷热不均引起的空气垂直运动形成的，属于热力成因；副热带高气压带和副极地低气压带是由于大气运动引起的，属于动力成因。', 'single_choice', ARRAY['大气环流','气压带风带'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '下列水循环环节中，属于陆地内循环的是（多选）', [{"label": "A", "text": "A. 蒸发"}, {"label": "B", "text": "B. 降水"}, {"label": "C", "text": "C. 水汽输送"}, {"label": "D", "text": "D. 径流"}, {"label": "E", "text": "E. 下渗"}], 'A,B,D', '陆地内循环是指发生在陆地与陆地之间的水循环，主要包括蒸发、降水和径流等环节。水汽输送是海陆间循环的环节，下渗则属于下垫面过程，不直接构成循环环节。', 'multiple_choice', ARRAY['水循环','陆地内循环'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '下列哪些因素会影响人口迁移？', [{"label": "A", "text": "经济发展水平"}, {"label": "B", "text": "气候条件"}, {"label": "C", "text": "国家政策"}, {"label": "D", "text": "文化教育"}, {"label": "E", "text": "矿产资源"}], 'A,B,C,D,E', '影响人口迁移的因素包括经济因素（如经济发展水平）、自然因素（如气候条件）、政策因素（如国家政策）、社会文化因素（如文化教育）以及资源因素（如矿产资源）等，因此所有选项都正确。', 'multiple_choice', ARRAY['人口迁移'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '下图为某区域地质剖面示意图。读图，完成下题。图中甲、乙、丙、丁四处中，最可能形成地下溶洞的是（ ）', [{"label": "A", "text": "A. 甲处"}, {"label": "B", "text": "B. 乙处"}, {"label": "C", "text": "C. 丙处"}, {"label": "D", "text": "D. 丁处"}], 'C', '溶洞属于喀斯特地貌，主要形成于可溶性岩石（如石灰岩）中。图中丙处为石灰岩，且位于地下水位以下，易受流水溶蚀形成溶洞。甲处为花岗岩，乙处为砂岩，丁处为页岩，均不易溶蚀。', 'single_choice', ARRAY['地质构造','喀斯特地貌','外力作用'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '读北半球某季节气压带和风带分布示意图，完成下题。图中①气压带和②风带分别是（ ）', [{"label": "A", "text": "A. 副极地低气压带；东北信风带"}, {"label": "B", "text": "B. 副热带高气压带；盛行西风带"}, {"label": "C", "text": "C. 赤道低气压带；东南信风带"}, {"label": "D", "text": "D. 极地高气压带；极地东风带"}], 'B', '根据图示，①位于30°N附近，为副热带高气压带；②位于30°N～60°N之间，为盛行西风带（北半球为西南风）。', 'single_choice', ARRAY['大气环流','气压带风带'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '下图为非洲自然带分布图，图中甲、乙、丙、丁四地自然带的变化体现的地域分异规律是（ ）', [{"label": "A", "text": "A. 纬度地带性"}, {"label": "B", "text": "B. 经度地带性"}, {"label": "C", "text": "C. 垂直地带性"}, {"label": "D", "text": "D. 非地带性"}], 'A', '甲（热带雨林带）、乙（热带草原带）、丙（热带荒漠带）、丁（亚热带常绿硬叶林带）大致沿纬线方向延伸，南北更替，体现了从赤道到两极的纬度地带性分异规律。', 'single_choice', ARRAY['自然带','地域分异规律'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '读某城市空间结构示意图，完成下题。该城市拟建设高级住宅区，最适宜布局在（ ）', [{"label": "A", "text": "A. ①处"}, {"label": "B", "text": "B. ②处"}, {"label": "C", "text": "C. ③处"}, {"label": "D", "text": "D. ④处"}], 'C', '高级住宅区一般选址于环境优美、交通便利、远离工业区的地方。图中③处位于河流上游，靠近风景区，且远离工业区，环境质量好，适合建设高级住宅区。①处靠近火车站，②处靠近工业区，④处位于城市中心，均不适宜。', 'single_choice', ARRAY['城市内部空间结构','城市功能区'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '下图为我国某地区农业土地利用示意图，该地区农业地域类型是（ ）', [{"label": "A", "text": "A. 商品谷物农业"}, {"label": "B", "text": "B. 季风水田农业"}, {"label": "C", "text": "C. 大牧场放牧业"}, {"label": "D", "text": "D. 乳畜业"}], 'B', '图中显示主要农作物为水稻，且土地利用方式为水田，一年两熟或三熟，主要分布在亚洲季风区，因此为季风水田农业。', 'single_choice', ARRAY['农业地域类型','农业'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '读某工业区布局图，完成下题。该工业区布局的主导区位因素是（ ）', [{"label": "A", "text": "A. 原料"}, {"label": "B", "text": "B. 市场"}, {"label": "C", "text": "C. 动力"}, {"label": "D", "text": "D. 劳动力"}], 'C', '图中工业区靠近火电站和水电站，且工业类型多为高耗能工业（如炼铝、钢铁等），因此动力（能源）是主导区位因素。', 'single_choice', ARRAY['工业区位因素','工业'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '下图为某区域交通线路分布图，图中甲、乙、丙、丁四处中，最可能最先发展为城市的是（ ）', [{"label": "A", "text": "A. 甲处"}, {"label": "B", "text": "B. 乙处"}, {"label": "C", "text": "C. 丙处"}, {"label": "D", "text": "D. 丁处"}], 'B', '乙处位于河流交汇处，且有多条交通线路交汇，交通便利，水源充足，有利于城市形成和发展。其他各处区位条件相对较差。', 'single_choice', ARRAY['交通运输布局','城市区位'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '读我国某地区生态环境问题成因与危害示意图，完成下题。该生态环境问题最可能是（ ）', [{"label": "A", "text": "A. 土地荒漠化"}, {"label": "B", "text": "B. 水土流失"}, {"label": "C", "text": "C. 酸雨"}, {"label": "D", "text": "D. 生物多样性减少"}], 'B', '图中显示成因包括植被破坏、陡坡开垦、降水集中等，危害包括土壤肥力下降、河流含沙量增加、下游洪涝加剧等，这些是水土流失的典型特征。', 'single_choice', ARRAY['环境问题','水土流失','区域可持续发展'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '读某地地质剖面图，图中①～④为沉积岩，⑤为岩浆岩。关于该地地质作用过程的叙述，正确的有（ ）。', [{"label": "A", "text": "A. 先发生沉积作用形成①②③④岩层，然后发生岩浆活动形成⑤"}, {"label": "B", "text": "B. ⑤的形成时间早于②岩层"}, {"label": "C", "text": "C. 该地经历了地壳的水平挤压运动"}, {"label": "D", "text": "D. 该地经历了地壳的抬升和侵蚀作用"}, {"label": "E", "text": "E. 图中岩层①可能含有化石"}], 'A,C,D,E', '图中岩层具有层理结构，为沉积岩，且①在最上层，说明先沉积形成①～④，后岩浆侵入形成⑤（侵入岩）。⑤侵入到②中，故⑤晚于②。岩层弯曲说明受水平挤压形成褶皱。地壳抬升后遭受侵蚀，形成现在的地表形态。沉积岩中可能含有化石。因此A、C、D、E正确，B错误。', 'multiple_choice', ARRAY['地质构造','地壳运动','岩石圈物质循环'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '下图为世界某区域海平面气压分布图（单位：hPa）。关于图中所示季节及各地天气的描述，正确的有（ ）。', [{"label": "A", "text": "A. 此时北半球为夏季"}, {"label": "B", "text": "B. 甲地盛行西北风，寒冷干燥"}, {"label": "C", "text": "C. 乙地受高压控制，天气晴朗"}, {"label": "D", "text": "D. 丙地可能受台风影响，狂风暴雨"}, {"label": "E", "text": "E. 丁地处于冷锋过境后，气温降低"}], 'A,C,D', '图中亚欧大陆形成印度低压，海洋上为高压，说明北半球为夏季。甲地位于东亚，夏季盛行东南风，温暖湿润，故B错。乙地受高压控制，气流下沉，天气晴朗。丙地位于西北太平洋，夏季多台风。丁地位于冷锋锋前，未受冷锋影响，E错。因此A、C、D正确。', 'multiple_choice', ARRAY['大气环流','天气系统','海陆分布对气压带的影响'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '读某流域水循环示意图，图中①②③④表示水循环环节。关于该流域水循环的叙述，正确的有（ ）。', [{"label": "A", "text": "A. 该水循环类型为海陆间循环"}, {"label": "B", "text": "B. ②为水汽输送，主要动力是盛行风"}, {"label": "C", "text": "C. ③为地表径流，受植被覆盖率影响"}, {"label": "D", "text": "D. ④为地下径流，其水量受降水补给"}, {"label": "E", "text": "E. 人类活动对①环节的影响最大"}], 'A,B,C,D', '图中海洋水蒸发后通过水汽输送（②）至陆地上空，降水（①）后形成地表径流（③）和地下径流（④），最终汇入海洋，属于海陆间循环。水汽输送主要依靠盛行风。地表径流受植被、地形等影响。地下径流受降水补给。人类活动对地表径流（③）影响最大，如修建水库、植树造林等，对蒸发（①）影响较小，故E错。因此A、B、C、D正确。', 'multiple_choice', ARRAY['水循环','陆地水体相互关系','人类活动对水循环的影响'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '下表为某国1960—2020年人口数据统计表。关于该国人口增长特点及影响的叙述，正确的有（ ）。', [{"label": "A", "text": "A. 1960—1980年人口出生率较高，属于传统型增长模式"}, {"label": "B", "text": "B. 1980—2000年人口自然增长率下降，主要原因是经济发展和生育观念转变"}, {"label": "C", "text": "C. 2000—2020年人口老龄化加剧，社会养老负担加重"}, {"label": "D", "text": "D. 该国目前人口增长模式为“低低低”模式"}, {"label": "E", "text": "E. 人口增长缓慢有利于该国经济持续高速发展"}], 'A,B,C,D', '1960—1980年出生率较高，死亡率下降，自然增长率高，为传统型。1980—2000年自然增长率下降，是由于经济水平提高、生育观念变化。2000—2020年自然增长率低，老龄化问题突出。目前出生率、死亡率、自然增长率均低，为现代型。人口增长缓慢会导致劳动力不足，不利于经济持续发展，故E错误。', 'multiple_choice', ARRAY['人口增长模式','人口问题','人口政策'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '关于城市内部功能区的特征，下列叙述正确的是（ ）', [{"label": "A", "text": "A. 商业区通常位于城市中心，具有最高的地租和最强的通达性"}, {"label": "B", "text": "B. 住宅区是城市最广泛的土地利用方式，且高级住宅区常与低级住宅区背向发展"}, {"label": "C", "text": "C. 工业区一般靠近河流、铁路等交通线，且多位于城市的下风向"}, {"label": "D", "text": "D. 城市各功能区之间没有明确的界线，往往交错分布"}], 'A,B,C,D', '商业区位于市中心，地租最高，通达性最好，A正确；住宅区占地面积最广，高级住宅区与低级住宅区在位置上往往背向发展，B正确；工业区需要便利的交通，且为减少对城区的污染，常位于城市的下风向，C正确；各功能区之间没有明确界线，往往交错分布，D正确。', 'multiple_choice', ARRAY['城市功能区','城市内部空间结构'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'advanced', '高三', '读世界某区域年降水量分布图（单位：mm），图中甲、乙、丙、丁四地中，年降水量最大的是（  ）', [{"label": "A", "text": "A. 甲地"}, {"label": "B", "text": "B. 乙地"}, {"label": "C", "text": "C. 丙地"}, {"label": "D", "text": "D. 丁地"}], 'B', '甲地位于大陆内部，受海洋水汽影响小，降水少；乙地位于迎风坡，来自海洋的暖湿气流受地形抬升，形成丰富降水；丙地位于背风坡，降水少；丁地位于大陆西岸，受寒流影响，降水较少。因此乙地降水量最大。', 'single_choice', ARRAY['大气环流','降水影响因素','地形雨'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'advanced', '高三', '读水循环示意图，关于水循环各环节的说法，正确的是（  ）', [{"label": "A", "text": "A. ①是蒸发，②是降水，③是地表径流，④是地下径流"}, {"label": "B", "text": "B. 人类活动对⑤（下渗）的影响最大"}, {"label": "C", "text": "C. 植被破坏会导致⑥（蒸腾）减少，④（地下径流）增加"}, {"label": "D", "text": "D. 南水北调工程主要影响了③（地表径流）"}], 'D', '读图可知，①为蒸发，②为水汽输送，③为降水，④为地表径流，⑤为下渗，⑥为地下径流。A项中②应为水汽输送，③应为降水，故A错。人类活动对地表径流（④）影响最大，如修建水库、跨流域调水等，对下渗影响较小，故B错。植被破坏导致蒸腾减少，但下渗减少，地下径流减少，故C错。南水北调工程改变了地表径流的空间分布，主要影响地表径流（③），故D正确。', 'single_choice', ARRAY['水循环','人类活动对水循环的影响','南水北调'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'advanced', '高三', '下表为某国人口年龄结构数据（单位：%）。该国面临的主要人口问题是（  ）', [{"label": "A", "text": "A. 人口增长过快，就业压力大"}, {"label": "B", "text": "B. 人口老龄化严重，劳动力短缺"}, {"label": "C", "text": "C. 人口性别比失衡，社会不稳定"}, {"label": "D", "text": "D. 人口素质低，教育压力大"}], 'B', '根据表格数据，0-14岁人口占比15%，15-64岁占比60%，65岁及以上占比25%。65岁以上人口占比超过7%即进入老龄化社会，该国高达25%，说明老龄化严重。15-64岁劳动力人口占比60%，但老龄化导致劳动力短缺，养老负担重。因此主要人口问题是人口老龄化严重，劳动力短缺。A项人口增长过快错误，因为0-14岁占比低。C项性别比表格未提供。D项人口素质无从判断。', 'single_choice', ARRAY['人口年龄结构','人口老龄化','人口问题'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'advanced', '高三', '某地农业土地利用类型变化如下：1980年以水稻种植为主，1990年改为花卉蔬菜种植，2000年发展为观光农业。导致这种变化的主要区位因素是（  ）', [{"label": "A", "text": "A. 气候变暖，热量条件改善"}, {"label": "B", "text": "B. 市场需求变化和交通条件改善"}, {"label": "C", "text": "C. 土地价格上升，单位面积产值要求提高"}, {"label": "D", "text": "D. 农业技术进步，农作物品种改良"}], 'B', '从水稻种植到花卉蔬菜种植，再到观光农业，反映了农业类型随市场需求变化而调整。花卉蔬菜和观光农业需要便捷的交通以快速到达市场，因此交通条件的改善也促进了这种变化。气候变暖不是主要原因，土地价格上升和农业技术进步是影响因素，但根本原因是市场需求变化和交通条件改善，故B正确。', 'single_choice', ARRAY['农业区位因素','农业类型变化','市场需求'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'advanced', '高三', '某国家矿产资源丰富，但长期以来以出口初级矿产品为主，经济结构单一。为促进经济可持续发展，该国应采取的主要措施是（  ）', [{"label": "A", "text": "A. 扩大资源开采规模，增加出口量"}, {"label": "B", "text": "B. 发展深加工，延长产业链，提高附加值"}, {"label": "C", "text": "C. 停止资源开采，保护生态环境"}, {"label": "D", "text": "D. 大量进口资源，满足国内需求"}], 'B', '出口初级矿产品利润低，且易受国际市场波动影响。发展深加工，延长产业链，可以提高附加值，增加收入，促进产业多元化，实现经济可持续发展。扩大资源开采规模会加速资源枯竭，停止开采不现实，大量进口不符合本国资源丰富的国情，故B正确。', 'single_choice', ARRAY['区域可持续发展','资源开发','产业链'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'advanced', '高三', '全球变暖导致极地冰川融化，海平面上升，对沿海低地国家构成威胁。为应对全球变暖，下列措施合理的是（  ）', [{"label": "A", "text": "A. 大量使用化石能源，加速经济发展"}, {"label": "B", "text": "B. 增加森林覆盖率，吸收二氧化碳"}, {"label": "C", "text": "C. 填海造陆，扩大陆地面积"}, {"label": "D", "text": "D. 减少水资源消耗，节约用水"}], 'B', '全球变暖的主要原因是温室气体（特别是二氧化碳）排放增加。增加森林覆盖率可以吸收二氧化碳，减缓温室效应。大量使用化石能源会增加二氧化碳排放，加剧全球变暖；填海造陆不能减少温室气体；节约用水与全球变暖无直接关系。因此B正确。', 'single_choice', ARRAY['全球变暖','森林作用','可持续发展'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'advanced', '高三', '某地地质剖面示意图显示，岩层①为石灰岩，②为砂岩，③为页岩，④为花岗岩，⑤为断层。已知该地曾经历地壳抬升、下降，并伴有岩浆活动。下列叙述正确的有（ ）', [{"label": "A", "text": "A. 岩层①②③形成的先后顺序是③②①"}, {"label": "B", "text": "B. 断层⑤的形成晚于岩层④"}, {"label": "C", "text": "C. 若岩层①含有三叶虫化石，则岩层②可能含有裸子植物化石"}, {"label": "D", "text": "D. 该地至少经历两次地壳抬升"}], 'A,D', '根据沉积岩层序律，越往下越老，所以③最早，②次之，①最晚，A正确。花岗岩④侵入到断层⑤中，说明断层形成早于岩浆侵入，B错误。三叶虫化石存在于古生代地层，裸子植物化石存在于中生代地层，石灰岩①在砂岩②之上，砂岩②可能属于古生代晚期或中生代早期，但不确定，C错误。沉积岩层形成于水下，现出露地表，说明有抬升；图中存在侵蚀面（不整合面），表明抬升后遭受侵蚀，后又下降接受沉积，所以至少两次抬升，D正确。', 'multiple_choice', ARRAY['地质构造','地壳运动','化石与地质年代'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'advanced', '高三', '下图为北半球某地近地面等压线分布图（单位：hPa），图中a、b、c、d为四个城市。此时，下列叙述正确的有（ ）', [{"label": "A", "text": "A. a城盛行东北风"}, {"label": "B", "text": "B. b城气压高于c城"}, {"label": "C", "text": "C. d城可能出现降水"}, {"label": "D", "text": "D. 若图中锋面移动速度为40千米/小时，则未来24小时内c城将经历大风、降温天气"}], 'A,C,D', '根据等压线，a城位于高压脊东侧，水平气压梯度力指向南，北半球右偏，形成东北风，A正确。b城气压在1010-1015之间，c城气压在1005-1010之间，b城气压高于c城，B正确。d城位于低压槽附近，且冷锋锋后，易出现降水，C正确。图中冷锋距离c城约960千米（根据比例尺估算），移动速度40千米/小时，24小时移动960千米，恰好到达c城，所以c城将经历冷锋过境，出现大风、降温天气，D正确。', 'multiple_choice', ARRAY['大气环流','天气系统','锋面与降水'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'advanced', '高三', '某城市地处沿海平原，近年来大力发展临港工业。下图为该城市1990-2020年人口和用地规模变化图。据图推断，该城市在城市化过程中出现的问题及对策合理的有（ ）', [{"label": "A", "text": "A. 城市热岛效应加剧，应增加绿地面积"}, {"label": "B", "text": "B. 交通拥堵严重，应优先发展公共交通"}, {"label": "C", "text": "C. 地下水漏斗区扩大，应禁止开采地下水"}, {"label": "D", "text": "D. 城市内涝频发，应完善排水系统并建设海绵城市"}], 'A,B,D', '城市规模扩大，人口密集，建筑物增加，热岛效应加剧，增加绿地可缓解，A正确。人口和用地规模扩大，交通需求增加，易拥堵，优先发展公共交通是有效措施，B正确。地下水漏斗区扩大是由于过度开采，但完全禁止不现实，应合理开采并回灌，C错误。城市地面硬化面积增加，下渗减少，内涝频发，完善排水系统和建设海绵城市可增强排水和蓄水能力，D正确。', 'multiple_choice', ARRAY['城市化问题','城市环境','可持续发展'], 'ai_generated', 'batch_geography_16-18');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '大气圈中，天气现象主要发生在？', [{"label": "A", "text": "对流层"}, {"label": "B", "text": "平流层"}, {"label": "C", "text": "中间层"}, {"label": "D", "text": "热层"}], 'A', '对流层集中了约3/4的大气质量和几乎全部水汽，天气现象如阴晴雨雪都发生在这一层。', 'single_choice', ARRAY['自然地理'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '下列岩石中，属于岩浆岩的是？', [{"label": "A", "text": "石灰岩"}, {"label": "B", "text": "花岗岩"}, {"label": "C", "text": "砂岩"}, {"label": "D", "text": "大理岩"}], 'B', '花岗岩是岩浆侵入地壳冷却凝固形成的侵入型岩浆岩；石灰岩和砂岩是沉积岩；大理岩是变质岩。', 'single_choice', ARRAY['自然地理'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '暖流对沿岸气候的影响是？', [{"label": "A", "text": "降温减湿"}, {"label": "B", "text": "增温增湿"}, {"label": "C", "text": "降温增湿"}, {"label": "D", "text": "增温减湿"}], 'B', '暖流流经沿岸地区，使沿岸气候增温增湿；寒流则降温减湿。', 'single_choice', ARRAY['自然地理'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '我国东部季风区降水的主要类型是？', [{"label": "A", "text": "地形雨"}, {"label": "B", "text": "锋面雨"}, {"label": "C", "text": "对流雨"}, {"label": "D", "text": "台风雨"}], 'B', '我国东部季风区降水主要是冷暖气团交汇形成的锋面雨，夏季还有台风雨。', 'single_choice', ARRAY['自然地理'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
