INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'beginner', '高三', '关于水循环的叙述，正确的有？（多选）', [{"label": "A", "text": "水循环包括海陆间循环、陆地内循环和海上内循环"}, {"label": "B", "text": "水汽输送是将海洋水汽带到陆地的过程"}, {"label": "C", "text": "地表径流是陆地上水返回海洋的主要途径"}, {"label": "D", "text": "植物蒸腾不属于水循环环节"}, {"label": "E", "text": "水循环使陆地水不断得到补充和更新"}], 'ABCE', '水循环包括三种类型；水汽输送将海洋水汽带到陆地；地表径流是陆地水回归海洋的主要途径；植物蒸腾是水循环的重要环节；水循环不断更新陆地水。', 'multiple_choice', ARRAY['自然地理'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
