INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'advanced', '高三', '关于海—气相互作用的叙述，正确的是？', [{"label": "A", "text": "海洋对大气没有影响"}, {"label": "B", "text": "大气运动是海洋运动的唯一动力"}, {"label": "C", "text": "海洋是大气的主要热源和水汽来源"}, {"label": "D", "text": "海气相互作用只发生在热带地区"}], 'C', '海洋是大气的主要热源和水汽来源，对大气温度和湿度有重要影响；大气运动（风）是海流的主要动力之一；海气相互作用在全球各地都存在。', 'single_choice', ARRAY['自然地理'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
