INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'advanced', '高三', '分析全球气候变暖对自然地理环境的可能影响。', NULL, '①海平面上升：极地冰川融化，海水热膨胀，沿海低地被淹；②水循环变化：蒸发加剧，部分地区干旱加重，部分地区洪涝增多；③生态系统改变：物种分布范围变化，生物多样性减少，部分物种灭绝；④农业生产变化：高纬度地区可能受益，低纬度地区可能减产；⑤极端天气事件增多：热浪、暴雨、台风等灾害频率和强度增加；⑥人类健康威胁：热带疾病传播范围扩大。', '全球变暖的影响包括海平面上升、水循环变化、生态系统改变、农业变化、极端天气增多等。', 'short_answer', ARRAY['自然地理'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
