INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'intermediate', '高三', '分析我国东北地区农业可持续发展的措施。', NULL, '①调整农业结构：因地制宜发展农林牧渔业，发展特色农业；②推进农业产业化：延长产业链，发展农产品加工业；③加强农业基础设施建设：改善农田水利条件，防治黑土流失；④发展绿色农业和生态农业：减少化肥农药使用，保护农业生态环境；⑤依靠科技进步：培育优良品种，提高单产和品质；⑥保护湿地和森林：维护农业生态系统的稳定性。', '东北农业可持续发展需从结构调整、产业化、生态保护、科技应用等多方面入手。', 'short_answer', ARRAY['区域可持续发展'], 'ai_generated', '');
