INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('geography', '16-18', 'advanced', '高三', '论述在区域发展中如何实现经济效益与生态效益的统一。', NULL, '①转变发展观念：树立绿水青山就是金山银山的理念，认识到良好生态环境是生产力；②调整产业结构：发展高新技术产业、现代服务业和生态农业，淘汰高污染高能耗产业；③发展循环经济：实现资源循环利用，减少废弃物排放；④加强生态修复：对已经破坏的生态系统进行修复治理；⑤完善制度保障：建立健全生态补偿机制、环境保护法规和绿色GDP考核体系；⑥推动技术创新：研发和推广清洁生产技术、污染治理技术和资源综合利用技术；⑦倡导绿色消费：引导公众形成节约资源、保护环境的消费模式。', '实现经济与生态效益统一需要从观念、产业、技术、制度、消费等多方面综合施策。', 'short_answer', ARRAY['区域可持续发展'], 'ai_generated', '');
