INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '《辛丑条约》的签订标志着中国完全沦为半殖民地半封建社会。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '正确', '《辛丑条约》是八国联军侵华后签订的不平等条约，巨额赔款和主权丧失使中国完全沦为半殖民地半封建社会。', 'true_false', ARRAY['中国近代史','辛丑条约'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '辛亥革命的历史意义包括（ ）。', [{"label": "A", "text": "推翻了清朝统治，结束了封建帝制"}, {"label": "B", "text": "建立了中华民国，颁布了《临时约法》"}, {"label": "C", "text": "使民主共和观念深入人心"}, {"label": "D", "text": "改变了中国半殖民地半封建的社会性质"}], 'ABC', '辛亥革命推翻了清朝统治，结束了两千多年的封建帝制，建立了中华民国，颁布了《临时约法》，使民主共和观念深入人心。但并未改变中国半殖民地半封建的社会性质。', 'multiple_choice', ARRAY['中国近代史','辛亥革命'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '新文化运动中，提出“文学革命”口号的是（ ）。', [{"label": "A", "text": "陈独秀"}, {"label": "B", "text": "鲁迅"}, {"label": "C", "text": "胡适"}, {"label": "D", "text": "李大钊"}], 'C', '胡适在《新青年》上发表《文学改良刍议》，主张以白话文代替文言文，提出“文学革命”的口号。陈独秀则提出“文学革命论”。', 'single_choice', ARRAY['中国近代史','新文化运动'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '五四运动是一次彻底的反帝反封建的爱国运动，标志着中国新民主主义革命的开端。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '正确', '五四运动以彻底反帝反封建的姿态，工人阶级开始登上政治舞台，是新民主主义革命的开端。', 'true_false', ARRAY['中国近代史','五四运动'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '中国共产党的成立时间、地点和主要代表人物分别是（ ）。', [{"label": "A", "text": "1921年7月，上海，毛泽东、董必武等"}, {"label": "B", "text": "1921年7月，北京，陈独秀、李大钊等"}, {"label": "C", "text": "1921年7月，上海，陈独秀、李大钊等"}, {"label": "D", "text": "1921年7月，嘉兴南湖，毛泽东、董必武等"}], 'A', '中共一大1921年7月在上海召开，后转移到嘉兴南湖，代表有毛泽东、董必武等13人，陈独秀和李大钊因故未参加。', 'single_choice', ARRAY['中国近代史','中国共产党的成立'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '国民革命运动失败的主要原因是（ ）。', [{"label": "A", "text": "帝国主义和封建势力的联合力量过于强大"}, {"label": "B", "text": "国民党右派叛变革命"}, {"label": "C", "text": "中国共产党缺乏经验，犯了右倾机会主义错误"}, {"label": "D", "text": "革命统一战线内部出现分化"}], 'ABCD', '国民革命失败有多方面原因：中外反动势力强大；国民党右派叛变；中共幼年，犯右倾错误；统一战线内部矛盾。', 'multiple_choice', ARRAY['中国近代史','国民革命运动'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '红军长征途中，遵义会议确立了（ ）的领导地位。', [{"label": "A", "text": "毛泽东"}, {"label": "B", "text": "周恩来"}, {"label": "C", "text": "朱德"}, {"label": "D", "text": "张闻天"}], 'A', '遵义会议纠正了博古等人的军事错误，事实上确立了毛泽东在红军和党中央的领导地位。', 'single_choice', ARRAY['中国近代史','遵义会议','红军长征'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '在古埃及，哪位法老以其大规模的建筑计划，包括修建吉萨大金字塔而闻名？', [{"label": "A", "text": "胡夫"}, {"label": "B", "text": "图坦卡蒙"}, {"label": "C", "text": "拉美西斯二世"}, {"label": "D", "text": "克利奥帕特拉七世"}], 'A', '胡夫法老（又称基奥普斯）是古埃及第四王朝的法老，他下令建造了吉萨大金字塔，这是古代世界七大奇迹之一。', 'single_choice', ARRAY['世界古代史','古埃及文明','金字塔'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '雅典民主政治中，最高权力机构是公民大会，所有成年男性公民均可参加。请问：在伯里克利时代，公民大会通常多久召开一次？', [{"label": "A", "text": "每年一次"}, {"label": "B", "text": "每月一次"}, {"label": "C", "text": "每十天一次"}, {"label": "D", "text": "每天一次"}], 'C', '伯里克利时代，雅典公民大会每十天召开一次，讨论并决定国家大事，体现了直接民主的特点。', 'single_choice', ARRAY['世界古代史','古希腊民主','伯里克利'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '罗马共和国时期，两位执政官由百人团会议选举产生，任期一年。请问：以下哪项是执政官的主要职责？', [{"label": "A", "text": "主持元老院会议"}, {"label": "B", "text": "担任最高法官"}, {"label": "C", "text": "指挥军队"}, {"label": "D", "text": "管理财政"}], 'C', '罗马执政官的主要职责是统帅军队，同时拥有行政和司法权，但军事指挥是其核心职能。', 'single_choice', ARRAY['世界古代史','罗马共和国','政治制度'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '古代印度种姓制度中，婆罗门的主要职责是祭祀和教育，那么刹帝利的主要职责是什么？', [{"label": "A", "text": "农耕和经商"}, {"label": "B", "text": "从事手工业"}, {"label": "C", "text": "担任祭司"}, {"label": "D", "text": "统治和军事"}], 'D', '刹帝利是种姓制度的第二等级，负责军事和统治，包括国王、武士和贵族。', 'single_choice', ARRAY['世界古代史','古印度种姓制度'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '佛教起源于古印度，其创始人释迦牟尼原为迦毗罗卫国的王子。请问：释迦牟尼出家前叫什么名字？', NULL, '乔达摩·悉达多', '释迦牟尼原名乔达摩·悉达多，是古印度迦毗罗卫国净饭王的太子，后出家修行，创立佛教。', 'fill_blank', ARRAY['世界古代史','佛教起源'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '古代两河流域的楔形文字是苏美尔人发明的，后来被阿卡德人、巴比伦人沿用。请问：楔形文字通常书写在什么材料上？', NULL, '泥板', '楔形文字用削尖的芦苇杆或木棒在软泥板上刻写，然后晒干或烘干，泥板成为主要的书写材料。', 'fill_blank', ARRAY['世界古代史','两河流域文明','楔形文字'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '罗马帝国在西罗马帝国灭亡后，东罗马帝国继续存在了近千年，史称拜占庭帝国。请问：拜占庭帝国的首都是君士坦丁堡，它最初是由哪位罗马皇帝建立的？', NULL, '君士坦丁大帝', '君士坦丁大帝于公元330年将罗马帝国首都迁至希腊古城拜占庭，并改名为君士坦丁堡，成为东罗马帝国的中心。', 'fill_blank', ARRAY['世界古代史','拜占庭帝国'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'advanced', '初三', '公元前6世纪，波斯帝国崛起，居鲁士大帝建立了阿契美尼德王朝。请问：波斯帝国在鼎盛时期，其疆域不包括以下哪个地区？', [{"label": "A", "text": "埃及"}, {"label": "B", "text": "印度河流域"}, {"label": "C", "text": "希腊半岛"}, {"label": "D", "text": "中亚"}], 'C', '波斯帝国鼎盛时疆域包括埃及、印度河流域、中亚和小亚细亚等地，但希腊半岛并未被征服，尽管波斯曾试图入侵希腊。', 'single_choice', ARRAY['世界古代史','波斯帝国'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
