INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'beginner', '初三', '简述罗马共和国时期的政治机构及其作用。', NULL, '罗马共和国时期的主要政治机构有执政官、元老院和公民大会。执政官是最高行政长官，元老院掌握实权，公民大会是立法机构。', '执政官由选举产生，负责行政；元老院由贵族组成，决策重大事务；公民大会选举官员和表决法律。', 'short_answer', ARRAY['世界古代史','古罗马'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
