INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '13-15', 'intermediate', '初三', '简述秦始皇为巩固统一采取的主要措施。', NULL, '统一文字、货币、度量衡；推行郡县制；修筑长城；统一车轨等。', '秦始皇通过一系列中央集权措施，如统一文字、货币、度量衡，推行郡县制，修筑长城等，巩固了国家统一。', 'short_answer', ARRAY['中国古代史','秦朝'], 'ai_generated', 'batch_history_13-15_supplement_20260715184639');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
