VALUES ('history', '16-18', 'beginner', '高三', '辛亥革命爆发于？', [{"label": "A", "text": "1910年"}, {"label": "B", "text": "1911年"}, {"label": "C", "text": "1912年"}, {"label": "D", "text": "1919年"}], 'B', '1911年10月10日武昌起义爆发，标志着辛亥革命的开始，推翻了清王朝的统治。', 'single_choice', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高三', '鸦片战争后，中国逐步沦为半殖民地半封建社会的主要表现有？（多选）', [{"label": "A", "text": "领土主权遭到破坏"}, {"label": "B", "text": "自然经济开始解体"}, {"label": "C", "text": "清政府成为列强统治工具"}, {"label": "D", "text": "民族资本主义迅速发展"}, {"label": "E", "text": "西方思想传入中国"}], 'ABE', '领土主权破坏和自然经济解体是鸦片战争后的直接结果；清政府成为列强统治工具是《辛丑条约》后的情况；民族资本主义在洋务运动后才逐步发展。', 'multiple_choice', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高三', '下列关于辛亥革命的叙述，正确的有？（多选）', [{"label": "A", "text": "推翻了清王朝的统治"}, {"label": "B", "text": "结束了两千多年的君主专制制度"}, {"label": "C", "text": "建立了资产阶级共和国"}, {"label": "D", "text": "完成了反帝反封建的革命任务"}, {"label": "E", "text": "使民主共和观念深入人心"}], 'ABCE', '辛亥革命推翻了清朝，结束了君主专制，建立了中华民国，传播了民主共和观念，但没有彻底完成反帝反封建的任务。', 'multiple_choice', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高三', '《辛丑条约》的签订标志着中国完全沦为半殖民地半封建社会。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], 'A', '1901年《辛丑条约》签订，清政府完全成为帝国主义统治中国的工具，中国完全沦为半殖民地半封建社会。', 'true_false', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'beginner', '高三', '五四运动中，工人阶级首次以独立的姿态登上政治舞台。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], 'A', '1919年五四运动中，工人阶级举行罢工支持学生斗争，标志着中国工人阶级登上政治舞台。', 'true_false', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'intermediate', '高三', '同盟会成立后发动的第一次武装起义是？', [{"label": "A", "text": "萍浏醴起义"}, {"label": "B", "text": "黄花岗起义"}, {"label": "C", "text": "武昌起义"}, {"label": "D", "text": "镇南关起义"}], 'A', '1906年的萍浏醴起义是同盟会成立后发动的第一次大规模武装起义。', 'single_choice', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'intermediate', '高三', '中国共产党第一次全国代表大会最后一天的会议转移到哪里举行？', [{"label": "A", "text": "上海"}, {"label": "B", "text": "北京"}, {"label": "C", "text": "嘉兴南湖"}, {"label": "D", "text": "广州"}], 'C', '中共一大因受到法租界巡捕干扰，最后一天的会议转移到浙江嘉兴南湖的一艘游船上举行。', 'single_choice', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'intermediate', '高三', '关于遵义会议的叙述，正确的有？（多选）', [{"label": "A", "text": "纠正了博古等人的左倾错误"}, {"label": "B", "text": "确立了毛泽东的领导地位"}, {"label": "C", "text": "是中国共产党从幼稚走向成熟的标志"}, {"label": "D", "text": "确立了抗日民族统一战线的方针"}, {"label": "E", "text": "在长征途中召开"}], 'ABCE', '遵义会议（1935年）纠正了左倾错误，确立了毛泽东的领导地位，是党走向成熟的标志；抗日民族统一战线方针是瓦窑堡会议确立的。', 'multiple_choice', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'intermediate', '高三', '抗日战争时期，国民党正面战场取得的重大胜利有？（多选）', [{"label": "A", "text": "台儿庄战役"}, {"label": "B", "text": "平型关大捷"}, {"label": "C", "text": "淞沪会战"}, {"label": "D", "text": "武汉会战"}, {"label": "E", "text": "百团大战"}], 'ACD', '台儿庄战役、淞沪会战、武汉会战是国民党正面战场的主要战役；平型关大捷和百团大战是共产党敌后战场的战役。', 'multiple_choice', ARRAY['中国近现代史'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'advanced', '高三', '关于近代中国民族资本主义发展的叙述，正确的是？', [{"label": "A", "text": "始终得到清政府的大力支持"}, {"label": "B", "text": "在甲午战后获得初步发展"}, {"label": "C", "text": "一战期间陷入萎缩"}, {"label": "D", "text": "国民政府统治前期发展停滞"}], 'B', '甲午战后清政府放宽对民间设厂的限制，民族资本主义获得初步发展；一战期间出现短暂春天；国民政府前期有所发展。', 'single_choice', ARRAY['中国近现代史'], 'ai_generated', '');
