INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('history', '16-18', 'advanced', '高三', '比较旧民主主义革命与新民主主义革命的异同。', NULL, '相同点：①革命任务相同，都是反帝反封建；②革命性质相同，都属于资产阶级民主革命范畴。不同点：①领导阶级不同：旧民主主义革命由资产阶级领导，新民主主义革命由无产阶级领导；②指导思想不同：旧民主主义革命以资产阶级民主思想为指导，新民主主义革命以马克思列宁主义、毛泽东思想为指导；③革命前途不同：旧民主主义革命要建立资产阶级共和国，新民主主义革命要走向社会主义；④革命深度不同：新民主主义革命更加彻底，能够发动广大工农群众。', '新旧民主主义革命的根本区别在于领导阶级、指导思想和革命前途。', 'short_answer', ARRAY['中国近现代史'], 'ai_generated', '');
