INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('math', '13-15', 'advanced', '初三', '关于方程ax²+bx+c=0(a≠0)，下列结论正确的有（　　）', [{"label": "A", "text": "若a+b+c=0，则必有一根为1"}, {"label": "B", "text": "若a-b+c=0，则必有一根为-1"}, {"label": "C", "text": "若两根相等，则b²=4ac"}, {"label": "D", "text": "若c=0，则方程必有一根为0"}], 'ABCD', 'A:代入x=1得a+b+c=0；B:代入x=-1得a-b+c=0；C:Δ=0即b²=4ac；D:代入x=0得c=0。', 'multiple_choice', ARRAY['一元二次方程','根的性质'], 'ai_generated', 'math_13-15_complete');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
