INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('math', '16-18', 'advanced', '高三', '在(1+2x)^5的展开式中，x^3的系数为______。', NULL, '80', 'T_{k+1}=C(5,k)(2x)^k，令k=3，系数为C(5,3)×2^3=10×8=80。', 'fill_blank', ARRAY['二项式定理'], 'ai_generated', 'math_16-18_complete');
