INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('math', '16-18', 'advanced', '高三', '已知正四棱锥的底面边长为2，侧棱长为√3，则该棱锥的体积为______。', NULL, '4/3', '底面正方形对角线长2√2，高h=√(3^2-(√2)^2)=√1=1，体积V=1/3×底面积×高=1/3×4×1=4/3。', 'fill_blank', ARRAY['立体几何','体积'], 'ai_generated', 'math_16-18_complete');
