VALUES ('math', '16-18', 'beginner', '高三', '数列 2, 4, 8, 16, ... 是等差数列。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '错误', '该数列相邻两项比值为常数2，是等比数列，不是等差数列。', 'true_false', ARRAY['数列','等比数列'], 'ai_generated', 'batch_math_16-18_supplement_20260715185911');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('math', '16-18', 'beginner', '高三', '已知等差数列 {a_n} 中，a₁ = 5，a₃ = 11，求该数列的公差d和a₁₀。', NULL, 'd = 3, a₁₀ = 32', '由a₃ = a₁ + 2d得11 = 5 + 2d，解得d=3；a₁₀ = a₁ + 9d = 5 + 27 = 32。', 'short_answer', ARRAY['数列','等差数列'], 'ai_generated', 'batch_math_16-18_supplement_20260715185911');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('math', '16-18', 'beginner', '高三', '等比数列 {b_n} 中，b₂ = 6，b₄ = 24，求公比q和b₅。', NULL, 'q = 2 或 q = -2；b₅ = 48 或 b₅ = -48', 'b₄ = b₂ * q²，24 = 6 q²，q²=4，q=±2；b₅ = b₄ * q = 24 * (±2) = ±48。', 'short_answer', ARRAY['数列','等比数列'], 'ai_generated', 'batch_math_16-18_supplement_20260715185911');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('math', '16-18', 'beginner', '高三', '函数f(x)=x^3的导数是？', [{"label": "A", "text": "3x^2"}, {"label": "B", "text": "x^2"}, {"label": "C", "text": "3x"}, {"label": "D", "text": "x^3"}], 'A', '根据幂函数求导公式，(x^n)'' = nx^(n-1)，所以(x^3)'' = 3x^2。', 'single_choice', ARRAY['导数','幂函数求导'], 'ai_generated', 'batch_math_16-18_supplement_20260715185911');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('math', '16-18', 'beginner', '高三', '函数f(x)=sin x的导数是？', [{"label": "A", "text": "cos x"}, {"label": "B", "text": "-cos x"}, {"label": "C", "text": "sin x"}, {"label": "D", "text": "-sin x"}], 'A', '根据基本导数公式，(sin x)'' = cos x。', 'single_choice', ARRAY['导数','三角函数求导'], 'ai_generated', 'batch_math_16-18_supplement_20260715185911');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('math', '16-18', 'beginner', '高三', '函数f(x)=e^x的导数是？', [{"label": "A", "text": "e^x"}, {"label": "B", "text": "x e^(x-1)"}, {"label": "C", "text": "e"}, {"label": "D", "text": "ln x"}], 'A', '指数函数e^x的导数等于其本身，即(e^x)'' = e^x。', 'single_choice', ARRAY['导数','指数函数求导'], 'ai_generated', 'batch_math_16-18_supplement_20260715185911');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('math', '16-18', 'beginner', '高三', '下列哪些函数的导数等于其本身？', [{"label": "A", "text": "f(x)=e^x"}, {"label": "B", "text": "f(x)=0"}, {"label": "C", "text": "f(x)=x"}, {"label": "D", "text": "f(x)=1"}], 'AB', 'e^x的导数是e^x，常数0的导数是0，所以A和B正确。f(x)=x的导数是1，f(x)=1的导数是0。', 'multiple_choice', ARRAY['导数','求导法则'], 'ai_generated', 'batch_math_16-18_supplement_20260715185911');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('math', '16-18', 'beginner', '高三', '函数f(x)=ln x的导数是1/x。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '正确', '根据基本导数公式，(ln x)'' = 1/x，x>0。', 'true_false', ARRAY['导数','对数函数求导'], 'ai_generated', 'batch_math_16-18_supplement_20260715185911');
