VALUES ('physics', '13-15', 'beginner', '', 'A car travels 120 km in 2 hours. What is its average speed?', [{"label": "A", "text": "A. 40 km/h"}, {"label": "B", "text": "B. 60 km/h"}, {"label": "C", "text": "C. 80 km/h"}, {"label": "D", "text": "D. 120 km/h"}], 'B', 'Average speed = total distance / total time = 120 km / 2 h = 60 km/h.', 'single_choice', ARRAY['机械运动'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'beginner', '', 'An object moves at a constant speed of 5 m/s for 4 seconds. How far does it travel?', [{"label": "A", "text": "A. 10 m"}, {"label": "B", "text": "B. 15 m"}, {"label": "C", "text": "C. 20 m"}, {"label": "D", "text": "D. 25 m"}], 'C', 'Distance = speed × time = 5 m/s × 4 s = 20 m.', 'single_choice', ARRAY['机械运动'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'beginner', '', 'Which of the following can increase pressure?', [{"label": "A", "text": "A. Increase contact area"}, {"label": "B", "text": "B. Decrease force"}, {"label": "C", "text": "C. Decrease contact area"}, {"label": "D", "text": "D. Keep area unchanged"}], 'C', 'Pressure is inversely proportional to contact area when force is constant.', 'single_choice', ARRAY['力与压强'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'beginner', '', 'The pressure at a certain depth in a liquid depends on which factors?', [{"label": "A", "text": "A. Only depth"}, {"label": "B", "text": "B. Depth and density"}, {"label": "C", "text": "C. Only density"}, {"label": "D", "text": "D. Container shape"}], 'B', 'Liquid pressure p = ρgh, depending on density and depth.', 'single_choice', ARRAY['力与压强'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
