INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'beginner', '', 'In a simple circuit, if voltage doubles and resistance stays the same, current ______.', [{"label": "A", "text": "A. halves"}, {"label": "B", "text": "B. doubles"}, {"label": "C", "text": "C. stays the same"}, {"label": "D", "text": "D. becomes zero"}], 'B', 'From I = U/R, current is directly proportional to voltage when R is constant.', 'single_choice', ARRAY['欧姆定律'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'beginner', '', 'Which of the following describe uniform linear motion? (Select all that apply)', [{"label": "A", "text": "A. Constant speed"}, {"label": "B", "text": "B. Constant direction"}, {"label": "C", "text": "C. Changing speed"}, {"label": "D", "text": "D. Straight path"}], '[''A'', ''B'', ''D'']', 'Uniform linear motion has constant speed and direction along a straight line.', 'multiple_choice', ARRAY['机械运动'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'beginner', '', 'Ways to decrease pressure include: (Select all that apply)', [{"label": "A", "text": "A. Increase contact area"}, {"label": "B", "text": "B. Decrease force"}, {"label": "C", "text": "C. Increase force"}, {"label": "D", "text": "D. Use sharp edges"}], '[''A'', ''B'']', 'Pressure = force/area; decreasing force or increasing area reduces pressure.', 'multiple_choice', ARRAY['力与压强'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
