INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'intermediate', '', 'Two cars start from the same point. Car A moves at 60 km/h, Car B at 80 km/h in the same direction. What is the relative speed of B to A?', [{"label": "A", "text": "A. 20 km/h"}, {"label": "B", "text": "B. 60 km/h"}, {"label": "C", "text": "C. 80 km/h"}, {"label": "D", "text": "D. 140 km/h"}], 'A', 'Relative speed in same direction = 80 - 60 = 20 km/h.', 'single_choice', ARRAY['机械运动'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'intermediate', '', 'A train 200 m long passes through a 800 m tunnel at 25 m/s. How long does it take?', [{"label": "A", "text": "A. 20 s"}, {"label": "B", "text": "B. 32 s"}, {"label": "C", "text": "C. 40 s"}, {"label": "D", "text": "D. 50 s"}], 'C', 'Total distance = train length + tunnel length = 1000 m; time = 1000/25 = 40 s.', 'single_choice', ARRAY['机械运动'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'intermediate', '', 'A wooden block with base area 0.2 m² and mass 8 kg rests on a table. What is the pressure? (g = 10 N/kg)', [{"label": "A", "text": "A. 200 Pa"}, {"label": "B", "text": "B. 300 Pa"}, {"label": "C", "text": "C. 400 Pa"}, {"label": "D", "text": "D. 500 Pa"}], 'C', 'Force = mg = 80 N; pressure = 80 N / 0.2 m² = 400 Pa.', 'single_choice', ARRAY['力与压强'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'intermediate', '', 'Water pressure at 3 m depth in a pool is approximately ______. (ρ_water = 1000 kg/m³, g = 10 N/kg)', [{"label": "A", "text": "A. 1000 Pa"}, {"label": "B", "text": "B. 3000 Pa"}, {"label": "C", "text": "C. 30000 Pa"}, {"label": "D", "text": "D. 100000 Pa"}], 'C', 'p = ρgh = 1000 × 10 × 3 = 30000 Pa.', 'single_choice', ARRAY['力与压强'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'intermediate', '', 'Which statement about liquid pressure is correct?', [{"label": "A", "text": "A. It depends on container shape"}, {"label": "B", "text": "B. Equal in all directions at same depth"}, {"label": "C", "text": "C. It decreases with depth"}, {"label": "D", "text": "D. It only acts downward"}], 'B', 'At the same depth, liquid pressure is equal in all directions.', 'single_choice', ARRAY['力与压强'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'intermediate', '', 'An object weighs 50 N in air and 30 N when fully submerged in water. What is the buoyant force?', [{"label": "A", "text": "A. 20 N"}, {"label": "B", "text": "B. 30 N"}, {"label": "C", "text": "C. 50 N"}, {"label": "D", "text": "D. 80 N"}], 'A', 'Buoyant force = weight in air - apparent weight in water = 50 - 30 = 20 N.', 'single_choice', ARRAY['浮力'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'intermediate', '', 'Two resistors of 4 Ω and 6 Ω are connected in series to a 10 V battery. What is the circuit current?', [{"label": "A", "text": "A. 1 A"}, {"label": "B", "text": "B. 2 A"}, {"label": "C", "text": "C. 2.5 A"}, {"label": "D", "text": "D. 5 A"}], 'A', 'Total resistance = 4 + 6 = 10 Ω; I = U/R = 10/10 = 1 A.', 'single_choice', ARRAY['欧姆定律'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'intermediate', '', 'Two resistors of 6 Ω and 12 Ω are connected in parallel. What is the equivalent resistance?', [{"label": "A", "text": "A. 4 Ω"}, {"label": "B", "text": "B. 6 Ω"}, {"label": "C", "text": "C. 9 Ω"}, {"label": "D", "text": "D. 18 Ω"}], 'A', '1/R = 1/6 + 1/12 = 1/4, so R = 4 Ω.', 'single_choice', ARRAY['欧姆定律'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'intermediate', '', 'In a parallel circuit with two branches, if one branch is broken, the other branch ______.', [{"label": "A", "text": "A. also stops working"}, {"label": "B", "text": "B. continues working normally"}, {"label": "C", "text": "C. has doubled current"}, {"label": "D", "text": "D. has halved voltage"}], 'B', 'In parallel circuits, branches work independently.', 'single_choice', ARRAY['欧姆定律'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'intermediate', '', 'Which statements about speed are correct? (Select all that apply)', [{"label": "A", "text": "A. Speed is a scalar quantity"}, {"label": "B", "text": "B. Average speed = distance / time"}, {"label": "C", "text": "C. Higher speed means more distance"}, {"label": "D", "text": "D. Speed has direction"}], '[''A'', ''B'']', 'Speed is scalar with no direction; distance also depends on time.', 'multiple_choice', ARRAY['机械运动'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'intermediate', '', 'An object floats in water but sinks in oil. This indicates: (Select all that apply)', [{"label": "A", "text": "A. Object density < water density"}, {"label": "B", "text": "B. Object density > oil density"}, {"label": "C", "text": "C. Water density > oil density"}, {"label": "D", "text": "D. Object density = water density"}], '[''A'', ''B'', ''C'']', 'Floating means less dense than fluid; sinking means denser than fluid.', 'multiple_choice', ARRAY['浮力'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'intermediate', '', 'For a fixed resistor, which relationships are correct? (Select all that apply)', [{"label": "A", "text": "A. Current is proportional to voltage"}, {"label": "B", "text": "B. I is inversely proportional to R"}, {"label": "C", "text": "C. Resistance is proportional to voltage"}, {"label": "D", "text": "D. R is inversely proportional to I"}], '[''A'', ''B'']', 'For a fixed resistor, R is constant; I is proportional to U and inversely proportional to R.', 'multiple_choice', ARRAY['欧姆定律'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'advanced', '', 'A cube with side length 0.1 m and density 3000 kg/m³ sits on a table. What is the pressure on the table? (g = 10 N/kg)', [{"label": "A", "text": "A. 300 Pa"}, {"label": "B", "text": "B. 1000 Pa"}, {"label": "C", "text": "C. 3000 Pa"}, {"label": "D", "text": "D. 10000 Pa"}], 'C', 'Mass = 3000 × 0.001 = 3 kg; force = 30 N; area = 0.01 m²; pressure = 30/0.01 = 3000 Pa.', 'single_choice', ARRAY['力与压强'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'advanced', '', 'In a U-tube containing water and oil, the water column is 8 cm and the oil column is 10 cm. What is the density of the oil?', [{"label": "A", "text": "A. 600 kg/m³"}, {"label": "B", "text": "B. 800 kg/m³"}, {"label": "C", "text": "C. 1000 kg/m³"}, {"label": "D", "text": "D. 1200 kg/m³"}], 'B', 'At equilibrium, ρ_oil × g × 0.1 = ρ_water × g × 0.08; ρ_oil = 800 kg/m³.', 'single_choice', ARRAY['力与压强'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'advanced', '', 'A hollow metal ball weighs 8 N in air and 5 N in water. Its volume is 0.0004 m³. What is the average density of the ball?', [{"label": "A", "text": "A. 1000 kg/m³"}, {"label": "B", "text": "B. 1500 kg/m³"}, {"label": "C", "text": "C. 2000 kg/m³"}, {"label": "D", "text": "D. 2500 kg/m³"}], 'C', 'Mass = 8/10 = 0.8 kg; density = 0.8/0.0004 = 2000 kg/m³.', 'single_choice', ARRAY['浮力'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'advanced', '', 'A circuit contains a 12 V source, a 4 Ω resistor, and a 6 Ω resistor in series. What is the voltage across the 4 Ω resistor?', [{"label": "A", "text": "A. 4.8 V"}, {"label": "B", "text": "B. 6 V"}, {"label": "C", "text": "C. 7.2 V"}, {"label": "D", "text": "D. 12 V"}], 'A', 'Current = 12/10 = 1.2 A; voltage across 4 Ω = 1.2 × 4 = 4.8 V.', 'single_choice', ARRAY['欧姆定律'], 'ai_generated', 'physics_13-15_001');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '13-15', 'advanced', '', 'Three identical resistors R are connected: two in parallel, then in series with the third. What is the total resistance?', [{"label": "A", "text": "A. R/2"}, {"label": "B", "text": "B. R"}, {"label": "C", "text": "C. 1.5R"}, {"label": "D", "text": "D. 3R"}], 'C', 'Two in parallel give R/2; in series with R gives 1.5R.', 'single_choice', ARRAY['欧姆定律'], 'ai_generated', 'physics_13-15_001');
