VALUES ('physics', '13-15', 'advanced', '', '关于电阻，下列说法正确的是（　　）', [{"label": "A", "text": "A. 电阻是导体本身的性质"}, {"label": "B", "text": "B. 电阻与电压成正比"}, {"label": "C", "text": "C. 电阻与电流成反比"}, {"label": "D", "text": "D. 电阻与材料有关"}], 'A,D', '电阻是导体本身属性，与电压电流无关。', 'true_false', ARRAY['欧姆定律'], 'ai_generated', 'physics_13-15_supplement');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
