INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'According to Newton''s First Law, an object will remain at rest or in uniform motion unless acted upon by a(n) _____.', [{"label": "A", "text": "external force"}, {"label": "B", "text": "internal force"}, {"label": "C", "text": "gravitational force only"}, {"label": "D", "text": "frictional force only"}], 'A', 'Newton''s First Law states that an object maintains its state of motion unless acted upon by an external net force.', 'single_choice', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'A 2 kg object moving at 3 m/s has a kinetic energy of _____.', [{"label": "A", "text": "6 J"}, {"label": "B", "text": "9 J"}, {"label": "C", "text": "18 J"}, {"label": "D", "text": "3 J"}], 'B', 'Kinetic energy Ek = ½mv² = ½ × 2 × 3² = 9 J.', 'single_choice', ARRAY['动能定理/机械能守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'In a system where only conservative forces act, which quantity remains constant?', [{"label": "A", "text": "Kinetic energy only"}, {"label": "B", "text": "Potential energy only"}, {"label": "C", "text": "Total mechanical energy"}, {"label": "D", "text": "Thermal energy"}], 'C', 'When only conservative forces act, the total mechanical energy (kinetic + potential) is conserved.', 'single_choice', ARRAY['动能定理/机械能守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'In an isolated system with no external forces, the total momentum of the system is _____.', [{"label": "A", "text": "increasing"}, {"label": "B", "text": "decreasing"}, {"label": "C", "text": "conserved"}, {"label": "D", "text": "zero"}], 'C', 'The law of conservation of momentum states that total momentum remains constant in an isolated system.', 'single_choice', ARRAY['动量守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'Faraday''s Law of Induction states that induced electromotive force is proportional to the rate of change of _____.', [{"label": "A", "text": "electric current"}, {"label": "B", "text": "magnetic flux"}, {"label": "C", "text": "resistance"}, {"label": "D", "text": "voltage"}], 'B', 'Faraday''s Law: ε = -dΦ/dt, where Φ is the magnetic flux.', 'single_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'In a double-slit experiment, increasing the wavelength of light while keeping other conditions constant will cause the interference fringes to become _____.', [{"label": "A", "text": "narrower"}, {"label": "B", "text": "wider"}, {"label": "C", "text": "unchanged"}, {"label": "D", "text": "disappear"}], 'B', 'Fringe spacing Δx = λL/d. Increasing λ increases fringe spacing, making fringes wider.', 'single_choice', ARRAY['波动光学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'For an ideal gas at constant temperature, if the volume is halved, the pressure will _____.', [{"label": "A", "text": "halve"}, {"label": "B", "text": "double"}, {"label": "C", "text": "remain unchanged"}, {"label": "D", "text": "quadruple"}], 'B', 'Boyle''s Law: pV = constant at constant T. Halving V doubles p.', 'single_choice', ARRAY['热学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'Lenz''s Law states that the direction of induced current is such that it opposes the change in _____ that produced it.', [{"label": "A", "text": "electric field"}, {"label": "B", "text": "magnetic flux"}, {"label": "C", "text": "temperature"}, {"label": "D", "text": "charge"}], 'B', 'Lenz''s Law describes the opposition to the change in magnetic flux that induces the current.', 'single_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'Which phenomenon demonstrates that light is a transverse wave?', [{"label": "A", "text": "Reflection"}, {"label": "B", "text": "Refraction"}, {"label": "C", "text": "Polarization"}, {"label": "D", "text": "Diffraction"}], 'C', 'Polarization is a property unique to transverse waves, demonstrating the transverse nature of light.', 'single_choice', ARRAY['波动光学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'Which statements about Newton''s Third Law are correct?', [{"label": "A", "text": "Action and reaction forces act on different objects"}, {"label": "B", "text": "Action and reaction forces are equal in magnitude"}, {"label": "C", "text": "Action and reaction forces cancel on the same object"}, {"label": "D", "text": "Action and reaction forces are opposite in direction"}], '[''A'', ''B'', ''D'']', 'Newton''s Third Law states forces are equal, opposite, and act on different bodies. They do not cancel on the same object.', 'multiple_choice', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'Which forms of energy are considered mechanical energy?', [{"label": "A", "text": "Kinetic energy"}, {"label": "B", "text": "Gravitational potential energy"}, {"label": "C", "text": "Internal thermal energy"}, {"label": "D", "text": "Elastic potential energy"}], '[''A'', ''B'', ''D'']', 'Mechanical energy includes kinetic, gravitational potential, and elastic potential energy. Thermal energy is not mechanical.', 'multiple_choice', ARRAY['动能定理/机械能守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'Which factors affect the magnitude of induced EMF in a coil?', [{"label": "A", "text": "Rate of change of magnetic flux"}, {"label": "B", "text": "Number of turns in the coil"}, {"label": "C", "text": "Resistance of the coil"}, {"label": "D", "text": "The rate at which the magnetic field changes"}], '[''A'', ''B'', ''D'']', 'Induced EMF depends on the rate of flux change and number of turns. Resistance affects current, not EMF.', 'multiple_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', 'For an ideal gas, which statements are true according to the ideal gas law pV = nRT?', [{"label": "A", "text": "At constant pressure, volume ∝ temperature"}, {"label": "B", "text": "At constant volume, pressure ∝ temperature"}, {"label": "C", "text": "At constant temperature, pressure ∝ 1/volume"}, {"label": "D", "text": "The gas constant R depends on the type of gas"}], '[''A'', ''B'', ''C'']', 'A, B, and C are direct consequences of the ideal gas law. R is a universal constant.', 'multiple_choice', ARRAY['热学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'A 0.5 kg ball is thrown vertically upward with an initial speed of 10 m/s. Using energy conservation, the maximum height reached is approximately _____ (g = 10 m/s²).', [{"label": "A", "text": "5 m"}, {"label": "B", "text": "10 m"}, {"label": "C", "text": "2.5 m"}, {"label": "D", "text": "20 m"}], 'A', '½mv² = mgh → h = v²/(2g) = 100/20 = 5 m.', 'single_choice', ARRAY['动能定理/机械能守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'Two objects with masses 2 kg and 3 kg move toward each other at 4 m/s and 2 m/s respectively. After a perfectly inelastic collision, they stick together. Their common velocity is _____.', [{"label": "A", "text": "1 m/s in the direction of the 2 kg object"}, {"label": "B", "text": "0.4 m/s in the direction of the 2 kg object"}, {"label": "C", "text": "2 m/s in the direction of the 3 kg object"}, {"label": "D", "text": "3 m/s in the direction of the 3 kg object"}], 'B', 'Using momentum conservation: 2×4 - 3×2 = (2+3)v → v = 2/5 = 0.4 m/s, in the direction of the 2 kg object''s initial motion.', 'single_choice', ARRAY['动量守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'A conducting rod of length L moves with velocity v perpendicular to a uniform magnetic field B. The induced EMF across the rod is _____.', [{"label": "A", "text": "BLv"}, {"label": "B", "text": "BL/v"}, {"label": "C", "text": "B/(Lv)"}, {"label": "D", "text": "B + L + v"}], 'A', 'Motional EMF ε = BLv when v is perpendicular to both B and L.', 'single_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'In a single-slit diffraction pattern, the angular width of the central maximum is _____.', [{"label": "A", "text": "λ/a"}, {"label": "B", "text": "2λ/a"}, {"label": "C", "text": "a/λ"}, {"label": "D", "text": "aλ"}], 'B', 'The first minima occur at sin θ = ±λ/a, so the angular width of the central maximum is 2λ/a.', 'single_choice', ARRAY['波动光学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'A fixed amount of ideal gas undergoes an isochoric process. If the pressure doubles, the temperature _____.', [{"label": "A", "text": "halves"}, {"label": "B", "text": "doubles"}, {"label": "C", "text": "remains constant"}, {"label": "D", "text": "quadruples"}], 'B', 'At constant volume, p ∝ T (Charles''s Law). Doubling pressure doubles absolute temperature.', 'single_choice', ARRAY['热学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'On a rough horizontal surface, a force F pulls a block at angle θ above horizontal. The normal force is _____ compared to the block''s weight.', [{"label": "A", "text": "greater than"}, {"label": "B", "text": "equal to"}, {"label": "C", "text": "less than"}, {"label": "D", "text": "independent of"}], 'C', 'The vertical component F sin θ lifts the block slightly, reducing the normal force: N = mg - F sin θ.', 'single_choice', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'A coil with 100 turns experiences a change in magnetic flux of 0.05 Wb in 0.1 s. The magnitude of induced EMF is _____.', [{"label": "A", "text": "0.5 V"}, {"label": "B", "text": "5 V"}, {"label": "C", "text": "50 V"}, {"label": "D", "text": "500 V"}], 'C', 'ε = N|ΔΦ/Δt| = 100 × 0.05/0.1 = 50 V.', 'single_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'When unpolarized light passes through a polarizer, the intensity of transmitted light becomes _____ of the original intensity.', [{"label": "A", "text": "half"}, {"label": "B", "text": "one quarter"}, {"label": "C", "text": "unchanged"}, {"label": "D", "text": "zero"}], 'A', 'A polarizer transmits the component parallel to its axis; for unpolarized light, transmitted intensity is I₀/2.', 'single_choice', ARRAY['波动光学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'Which statements correctly describe the relationship between force and motion?', [{"label": "A", "text": "Force causes acceleration, not velocity"}, {"label": "B", "text": "An object can move without any net force acting on it"}, {"label": "C", "text": "Greater force always means greater speed"}, {"label": "D", "text": "Acceleration direction matches net force direction"}], '[''A'', ''B'', ''D'']', 'Force causes acceleration (A). Inertia allows motion without force (B). Acceleration aligns with net force (D). Greater force does not guarantee greater speed (C).', 'multiple_choice', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'In which scenarios is momentum conserved for the described system?', [{"label": "A", "text": "A bullet fired from a rifle (bullet + rifle system)"}, {"label": "B", "text": "A ball bouncing elastically off a wall"}, {"label": "C", "text": "Two colliding objects on a frictionless surface"}, {"label": "D", "text": "A rocket expelling exhaust gases in space"}], '[''A'', ''C'', ''D'']', 'Momentum is conserved in isolated systems (A, C, D). In B, the wall is connected to Earth, so external forces act.', 'multiple_choice', ARRAY['动量守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'Which factors increase the self-inductance of a solenoid?', [{"label": "A", "text": "Increasing the number of turns per unit length"}, {"label": "B", "text": "Inserting an iron core"}, {"label": "C", "text": "Decreasing the cross-sectional area"}, {"label": "D", "text": "Increasing the length of the solenoid"}], '[''A'', ''B'']', 'L = μn²V. Increasing turns per unit length (A) and inserting iron (B, increasing μ) raise inductance. Decreasing area or increasing length reduces L.', 'multiple_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'intermediate', '高三', 'During an isothermal expansion of an ideal gas, which quantities remain constant?', [{"label": "A", "text": "Internal energy"}, {"label": "B", "text": "Temperature"}, {"label": "C", "text": "Pressure"}, {"label": "D", "text": "The product pV"}], '[''A'', ''B'', ''D'']', 'For an ideal gas, internal energy depends only on temperature, so both are constant in an isothermal process. Boyle''s Law gives pV = constant.', 'multiple_choice', ARRAY['热学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高三', 'A block of mass m on a horizontal surface is connected to a spring (constant k). The coefficient of kinetic friction is μ. The block is displaced by A from equilibrium and released. The total distance traveled before coming to rest is _____.', [{"label": "A", "text": "A"}, {"label": "B", "text": "A/(2μmg/k)"}, {"label": "C", "text": "kA²/(2μmg)"}, {"label": "D", "text": "μmgA/k"}], 'C', 'Initial elastic energy ½kA² is dissipated by friction: μmg × d = ½kA² → d = kA²/(2μmg).', 'single_choice', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高三', 'A rocket of initial mass M₀ ejects exhaust at speed u relative to the rocket. Its mass decreases at rate α. The thrust force is _____.', [{"label": "A", "text": "αu"}, {"label": "B", "text": "M₀u"}, {"label": "C", "text": "αM₀"}, {"label": "D", "text": "u/α"}], 'A', 'Thrust F = u|dm/dt| = αu, from the rocket equation.', 'single_choice', ARRAY['动量守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高三', 'A square loop of side L and resistance R moves with velocity v into a region of uniform magnetic field B (perpendicular to the loop). The magnitude of the magnetic force opposing the motion is _____.', [{"label": "A", "text": "B²L²v/R"}, {"label": "B", "text": "BLv/R"}, {"label": "C", "text": "B²Lv/R"}, {"label": "D", "text": "BL²v/R"}], 'A', 'EMF = BLv, I = BLv/R, F = BIL = B²L²v/R.', 'single_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高三', 'An ideal gas undergoes a cyclic process on a p-V diagram. If the cycle is traversed clockwise, the net work done by the gas is _____.', [{"label": "A", "text": "zero"}, {"label": "B", "text": "positive"}, {"label": "C", "text": "negative"}, {"label": "D", "text": "equal to the heat rejected"}], 'B', 'A clockwise cycle on a p-V diagram encloses positive area, representing net work done by the gas.', 'single_choice', ARRAY['热学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高三', 'A conducting rod rotates with angular velocity ω about one end in a uniform magnetic field B perpendicular to the plane of rotation. The rod has length L. The EMF between the ends is _____.', [{"label": "A", "text": "½BωL²"}, {"label": "B", "text": "BωL²"}, {"label": "C", "text": "BωL"}, {"label": "D", "text": "½BωL"}], 'A', 'Integrating v = ωr: ε = ∫₀ᴸ Bωr dr = ½BωL².', 'single_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高三', 'In a Michelson interferometer, when the movable mirror is displaced by distance d, the number of fringes N that cross the field of view is related by _____.', [{"label": "A", "text": "d = Nλ"}, {"label": "B", "text": "d = Nλ/2"}, {"label": "C", "text": "d = 2Nλ"}, {"label": "D", "text": "d = Nλ/4"}], 'B', 'Each fringe shift corresponds to λ/2 mirror displacement because the light path changes by 2d.', 'single_choice', ARRAY['波动光学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高三', 'For an adiabatic process of an ideal monatomic gas, the relation between pressure and volume is pV^γ = constant, where γ equals _____.', [{"label": "A", "text": "4/3"}, {"label": "B", "text": "5/3"}, {"label": "C", "text": "7/5"}, {"label": "D", "text": "3/2"}], 'B', 'For a monatomic ideal gas, γ = Cp/Cv = (5/2)R / (3/2)R = 5/3.', 'single_choice', ARRAY['热学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高三', 'Which statements about inertial and non-inertial reference frames are correct?', [{"label": "A", "text": "Newton's laws hold in inertial frames"}, {"label": "B", "text": "Fictitious forces appear in non-inertial frames"}, {"label": "C", "text": "The Earth is a perfect inertial frame"}, {"label": "D", "text": "Centrifugal force is a fictitious force"}], '[''A'', ''B'', ''D'']', 'A, B, and D are correct. Earth is approximately inertial but not perfect due to rotation (C is false).', 'multiple_choice', ARRAY['牛顿运动定律'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高三', 'For a conservative force field, which statements are true?', [{"label": "A", "text": "The work done depends only on endpoints, not path"}, {"label": "B", "text": "Force is the negative gradient of potential energy"}, {"label": "C", "text": "Mechanical energy is conserved"}, {"label": "D", "text": "Work done around any closed path is zero"}], '[''A'', ''B'', ''C'', ''D'']', 'All four are defining properties of conservative forces.', 'multiple_choice', ARRAY['动能定理/机械能守恒'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'advanced', '高三', 'Which phenomena are explained by Faraday''s Law of Induction?', [{"label": "A", "text": "Current induced in a coil by a moving magnet"}, {"label": "B", "text": "Eddy currents in a conductor near changing fields"}, {"label": "C", "text": "The operation of a transformer"}, {"label": "D", "text": "Magnetic force on a moving charge"}], '[''A'', ''B'', ''C'']', 'A, B, and C involve changing magnetic flux inducing EMF. D is the Lorentz force, not induction.', 'multiple_choice', ARRAY['电磁感应'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
