INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', '闭合电路的一部分导体在磁场中做切割磁感线运动时，一定会产生感应电流。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], 'A', '满足产生感应电流的条件。', 'true_false', ARRAY['电磁感应'], 'ai_generated', 'physics_16-18_supplement');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', '光的干涉和衍射现象说明光具有粒子性。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], 'B', '干涉和衍射说明光具有波动性。', 'true_false', ARRAY['波动光学'], 'ai_generated', 'physics_16-18_supplement');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', '一质量为m的物体在水平面上受到水平拉力F作用，做匀加速直线运动，加速度为a。若水平面变为粗糙，摩擦因数为μ，要保持相同的加速度，拉力应变为多大？', NULL, 'F''=F+μmg。原来F=ma；后来F''-μmg=ma，所以F''=F+μmg。', '分别对光滑和粗糙情况进行受力分析，运用牛顿第二定律。', 'short_answer', ARRAY['牛顿定律'], 'ai_generated', 'physics_16-18_supplement');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', '一子弹射入静止在光滑水平面上的木块中，并留在木块内。请分析子弹和木块组成的系统在碰撞过程中动量是否守恒，机械能是否守恒。', NULL, '系统动量守恒，因为水平面光滑，系统所受合外力为零；机械能不守恒，因为子弹射入木块过程中有摩擦力做功，部分机械能转化为内能。', '从动量守恒和机械能守恒的条件分别分析。', 'short_answer', ARRAY['动量守恒'], 'ai_generated', 'physics_16-18_supplement');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('physics', '16-18', 'beginner', '高三', '一矩形线圈在匀强磁场中绕垂直于磁场方向的轴匀速转动，说明线圈中感应电流的大小和方向如何变化。', NULL, '线圈转动时，穿过线圈的磁通量不断变化，产生感应电动势和感应电流；电流大小按正弦规律变化；方向每转过半圈改变一次。', '根据法拉第电磁感应定律和楞次定律分析。', 'short_answer', ARRAY['电磁感应'], 'ai_generated', 'physics_16-18_supplement');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '法律最显著的特征是（  ）。', [{"label": "A", "text": "由国家制定或认可"}, {"label": "B", "text": "靠国家强制力保证实施"}, {"label": "C", "text": "对全体社会成员具有普遍约束力"}, {"label": "D", "text": "以权利和义务为主要内容"}], 'B', '法律靠国家强制力保证实施，这是法律区别于道德等行为规范的最主要特征。', 'single_choice', ARRAY['道德与法治','法律的特征'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '我国宪法规定，中华人民共和国的一切权力属于（  ）。', [{"label": "A", "text": "公民"}, {"label": "B", "text": "人民"}, {"label": "C", "text": "中国共产党"}, {"label": "D", "text": "全国人民代表大会"}], 'B', '我国宪法明确规定，中华人民共和国的一切权力属于人民。', 'single_choice', ARRAY['道德与法治','宪法','国家权力'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '下列属于公民基本义务的有（  ）。①依法纳税 ②维护国家统一和全国各民族团结 ③选举权和被选举权 ④受教育', [{"label": "A", "text": "①②③"}, {"label": "B", "text": "①②④"}, {"label": "C", "text": "①③④"}, {"label": "D", "text": "②③④"}], 'B', '依法纳税、维护国家统一和民族团结、受教育是公民的基本义务；选举权和被选举权是权利，不是义务。', 'multiple_choice', ARRAY['道德与法治','公民义务'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '我国公民享有广泛的政治权利和自由，其中最基本的政治权利是（  ）。', [{"label": "A", "text": "监督权"}, {"label": "B", "text": "选举权和被选举权"}, {"label": "C", "text": "政治自由"}, {"label": "D", "text": "人身自由"}], 'B', '选举权和被选举权是公民参与国家管理、当家作主的基本政治权利。', 'single_choice', ARRAY['道德与法治','政治权利'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '下列行为中，属于正确行使公民权利的是（  ）。', [{"label": "A", "text": "在网络上散布谣言"}, {"label": "B", "text": "依法维护自己的合法财产"}, {"label": "C", "text": "未经他人同意使用其照片"}, {"label": "D", "text": "在公共场合大声喧哗"}], 'B', '依法维护自己的合法财产是正确行使财产权，其他三项均侵犯他人权利或违法。', 'single_choice', ARRAY['道德与法治','公民权利'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '以下关于我国民族政策的说法，正确的有（  ）。①坚持民族平等 ②坚持民族团结 ③坚持各民族共同繁荣 ④实行民族区域自治制度', [{"label": "A", "text": "①②"}, {"label": "B", "text": "①②③"}, {"label": "C", "text": "①②④"}, {"label": "D", "text": "①②③④"}], 'D', '我国处理民族关系的基本原则是民族平等、民族团结和各民族共同繁荣，基本政治制度是民族区域自治制度。', 'multiple_choice', ARRAY['道德与法治','民族政策'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '下列哪些属于我国宪法的基本原则？', [{"label": "A", "text": "人民主权原则"}, {"label": "B", "text": "基本人权原则"}, {"label": "C", "text": "法治原则"}, {"label": "D", "text": "权力分立原则"}], 'ABC', '我国宪法的基本原则包括人民主权原则、基本人权原则、法治原则和民主集中制原则，不包括权力分立原则。', 'multiple_choice', ARRAY['宪法基础','宪法基本原则'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '青春期是指由儿童逐渐发育成为成年人的过渡时期，通常发生在几岁之间？', [{"label": "A", "text": "10-18岁"}, {"label": "B", "text": "12-20岁"}, {"label": "C", "text": "15-25岁"}, {"label": "D", "text": "8-15岁"}], 'A', '青春期一般指10-18岁，是儿童向成年人过渡的时期。', 'single_choice', ARRAY['青春期心理','青春期概念'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '以下哪些属于青春期心理发展的常见表现？（多选）', [{"label": "A", "text": "情绪波动大"}, {"label": "B", "text": "对异性产生好奇"}, {"label": "C", "text": "独立意识增强"}, {"label": "D", "text": "完全依赖父母"}], 'ABC', '青春期常见心理表现包括情绪波动大、对异性好奇、独立意识增强，而完全依赖父母是儿童期的特点。', 'multiple_choice', ARRAY['青春期心理','青春期心理表现'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '下列行为中，属于违法行为的是（  ）', [{"label": "A", "text": "A. 在公共场所大声喧哗"}, {"label": "B", "text": "B. 拾到他人遗失物品不归还"}, {"label": "C", "text": "C. 在网络上随意发表言论"}, {"label": "D", "text": "D. 不遵守交通规则闯红灯"}], 'B', '拾到他人遗失物品不归还，侵犯了他人的财产权，属于民事违法行为。其他选项虽不道德但尚未达到违法程度。', 'single_choice', ARRAY['违法与犯罪','违法行为的含义'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '犯罪的最本质特征是（  ）', [{"label": "A", "text": "A. 严重社会危害性"}, {"label": "B", "text": "B. 刑事违法性"}, {"label": "C", "text": "C. 应受刑罚处罚性"}, {"label": "D", "text": "D. 违反法律性"}], 'A', '严重社会危害性是犯罪的最本质特征，也是区分犯罪与其他违法行为的关键。', 'single_choice', ARRAY['违法与犯罪','犯罪的特征'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '一般违法行为与犯罪的区别在于（  ）', [{"label": "A", "text": "A. 是否违反法律"}, {"label": "B", "text": "B. 是否具有社会危害性"}, {"label": "C", "text": "C. 是否应受法律制裁"}, {"label": "D", "text": "D. 是否触犯刑法，社会危害性是否严重"}], 'D', '一般违法行为与犯罪的主要区别在于社会危害程度不同，犯罪是触犯刑法、具有严重社会危害性的行为。', 'single_choice', ARRAY['违法与犯罪','一般违法行为与犯罪的区别'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '我国刑罚中，属于主刑的是（  ）', [{"label": "A", "text": "A. 罚款"}, {"label": "B", "text": "B. 没收财产"}, {"label": "C", "text": "C. 有期徒刑"}, {"label": "D", "text": "D. 剥夺政治权利"}], 'C', '主刑包括管制、拘役、有期徒刑、无期徒刑和死刑。罚款、没收财产、剥夺政治权利属于附加刑。', 'single_choice', ARRAY['违法与犯罪','刑罚的种类'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '下列行为中，属于犯罪的是（  ）', [{"label": "A", "text": "A. 小张因琐事将同学打成轻微伤"}, {"label": "B", "text": "B. 小李偷窃价值100元的物品"}, {"label": "C", "text": "C. 小王在公共场所随地吐痰"}, {"label": "D", "text": "D. 小赵因纠纷将他人打成重伤"}], 'D', '将他人打成重伤，具有严重社会危害性，触犯刑法，构成犯罪。轻微伤、偷窃数额不大、随地吐痰属于一般违法行为。', 'single_choice', ARRAY['违法与犯罪','犯罪的认定'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '违法不一定犯罪，犯罪一定违法。（  ）', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '正确', '违法行为包括一般违法行为和犯罪，犯罪是违法行为的一种，所以犯罪一定违法，但违法不一定达到犯罪程度。', 'true_false', ARRAY['违法与犯罪','违法与犯罪的关系'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '已满14周岁不满16周岁的人，犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质罪的，应当负刑事责任。（  ）', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '正确', '根据刑法规定，已满14周岁不满16周岁的人，对上述8种严重犯罪负刑事责任。', 'true_false', ARRAY['违法与犯罪','刑事责任年龄'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '______是维护我们合法权益最正规、最权威的一种手段。', NULL, '诉讼', '诉讼是人民法院在诉讼当事人参与下，依照法定程序解决纠纷的活动，是最正规、最权威的维权途径。', 'fill_blank', ARRAY['违法与犯罪','诉讼的含义'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '______是犯罪的法律标志。', NULL, '刑事违法性', '刑事违法性是指行为触犯刑法，是犯罪的法律标志，也是区分犯罪与其他违法行为的重要特征。', 'fill_blank', ARRAY['违法与犯罪','犯罪的特征'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'beginner', '初三', '下列属于我国刑罚中附加刑的有（  ）', [{"label": "A", "text": "A. 罚金"}, {"label": "B", "text": "B. 剥夺政治权利"}, {"label": "C", "text": "C. 没收财产"}, {"label": "D", "text": "D. 驱逐出境"}], 'ABCD', '附加刑包括罚金、剥夺政治权利、没收财产、驱逐出境（适用于外国人）。因此四个选项均正确。', 'multiple_choice', ARRAY['违法与犯罪','刑罚的种类'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'intermediate', '初三', '我国宪法规定，中华人民共和国的一切权力属于谁？', [{"label": "A", "text": "人民"}, {"label": "B", "text": "中国共产党"}, {"label": "C", "text": "全国人民代表大会"}, {"label": "D", "text": "国务院"}], 'A', '宪法第二条明确规定：中华人民共和国的一切权力属于人民。人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。', 'single_choice', ARRAY['道德与法治','宪法原则','国家权力归属'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'intermediate', '初三', '下列哪些行为属于公民依法行使监督权？（多选）', [{"label": "A", "text": "向人大代表反映情况"}, {"label": "B", "text": "在网络上随意发表不实言论"}, {"label": "C", "text": "通过新闻媒体曝光社会问题"}, {"label": "D", "text": "向有关部门举报违法行为"}], 'ACD', '公民行使监督权应通过合法途径，如向人大代表反映、新闻媒体曝光、举报等。选项B属于违法行为，不能正确行使权利。', 'multiple_choice', ARRAY['道德与法治','监督权','公民权利'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'intermediate', '初三', '依法治国首先是依宪治国。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], '正确', '宪法是国家的根本法，具有最高法律效力。依法治国首先是依宪治国，依法执政首先是依宪执政。', 'true_false', ARRAY['道德与法治','依法治国','宪法地位'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'intermediate', '初三', '社会主义的根本原则是______。', NULL, '共同富裕', '邓小平指出：社会主义的本质是解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。共同富裕是社会主义的根本原则。', 'fill_blank', ARRAY['道德与法治','社会主义本质','共同富裕'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'intermediate', '初三', '请简述公民如何正确行使权利。', NULL, '公民在行使权利时要尊重他人权利，不得损害国家的、社会的、集体的利益，要在法律允许的范围内行使权利，要以合法方式行使权利。', '正确行使权利需要遵守法律、尊重他人、不损害公共利益，并采用合法方式。', 'short_answer', ARRAY['道德与法治','公民权利','权利行使'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
