INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '13-15', 'intermediate', '初三', '我国宪法规定，中华人民共和国的一切权力属于（ ）。', [{"label": "A", "text": "A. 人民"}, {"label": "B", "text": "B. 公民"}, {"label": "C", "text": "C. 全国人大"}, {"label": "D", "text": "D. 中国共产党"}], 'A', '《宪法》第二条指出，中华人民共和国的一切权力属于人民。人民是整体，公民是个体。', 'single_choice', ARRAY['宪法基础','权力归属','人民主权'], 'ai_generated', 'batch_politics_13-15_supplement_20260715185203');
