VALUES ('politics', '16-18', 'intermediate', '高三', '简述如何弘扬和培育中华民族精神。', NULL, '①最重要的是发挥中国特色社会主义理论体系的指导作用；②必须继承和发扬中华民族的优良传统；③必须正确对待外来思想文化；④必须与弘扬时代精神相结合；⑤要立足于发展中国特色社会主义的伟大实践，人人都应成为民族精神的传播者、弘扬者和建设者。', '弘扬和培育民族精神需要发挥理论指导作用、继承优良传统、正确对待外来文化、与时代精神结合、立足实践。', 'short_answer', ARRAY['文化生活'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'advanced', '高三', '关于文化自信，下列叙述正确的是？', [{"label": "A", "text": "文化自信就是排斥外来文化"}, {"label": "B", "text": "文化自信是一个国家、一个民族发展中更基本、更深沉、更持久的力量"}, {"label": "C", "text": "文化自信只需要关注传统文化"}, {"label": "D", "text": "文化自信与经济政治无关"}], 'B', '文化自信是一个国家、一个民族发展中更基本、更深沉、更持久的力量，事关国运兴衰、事关文化安全、事关民族精神独立性。', 'single_choice', ARRAY['文化生活'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'advanced', '高三', '社会主义核心价值观中，属于国家层面价值目标的是？', [{"label": "A", "text": "富强、民主、文明、和谐"}, {"label": "B", "text": "自由、平等、公正、法治"}, {"label": "C", "text": "爱国、敬业、诚信、友善"}, {"label": "D", "text": "改革、开放、创新、包容"}], 'A', '社会主义核心价值观：国家层面是富强、民主、文明、和谐；社会层面是自由、平等、公正、法治；公民个人层面是爱国、敬业、诚信、友善。', 'single_choice', ARRAY['文化生活'], 'ai_generated', '');
