INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'advanced', '高三', '论述如何推动中华优秀传统文化创造性转化、创新性发展。', NULL, '①深入挖掘中华优秀传统文化蕴含的思想观念、人文精神、道德规范；②结合时代要求继承创新，让中华文化展现出永久魅力和时代风采；③运用现代科技手段和新媒体传播中华优秀传统文化；④推动中华优秀传统文化与现代社会相适应、与现代文明相协调；⑤把中华优秀传统文化融入国民教育、精神文明建设全过程；⑥以人民为中心，创作出人民喜闻乐见的文化产品。', '推动中华优秀传统文化创造性转化、创新性发展需要挖掘内涵、结合时代、运用科技、融入教育和以人民为中心。', 'short_answer', ARRAY['文化生活'], 'ai_generated', '');
