INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'beginner', '高三', '简述实践与认识的辩证关系。', NULL, '①实践是认识的基础：实践是认识的来源，是认识发展的动力，是检验认识真理性的唯一标准，是认识的目的。②认识对实践具有反作用：正确的认识、科学理论对实践有巨大的指导作用；错误的认识则会把实践引向歧途。', '实践与认识的辩证关系包括实践决定认识和认识反作用于实践两个方面。', 'short_answer', ARRAY['生活与哲学'], 'ai_generated', '');
