INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'intermediate', '高三', '简述唯物辩证法和形而上学的分歧。', NULL, '①联系观点与孤立观点的对立：唯物辩证法用联系的观点看问题，形而上学用孤立的观点看问题。②发展观点与静止观点的对立：唯物辩证法用发展的观点看问题，形而上学用静止的观点看问题。③全面观点与片面观点的对立：唯物辩证法用全面的观点看问题，形而上学用片面的观点看问题。④二者最根本的分歧在于是否承认矛盾，是否承认矛盾是事物发展的源泉和动力。', '唯物辩证法与形而上学的根本分歧在于是否承认矛盾，是否承认矛盾是事物发展的源泉和动力。', 'short_answer', ARRAY['生活与哲学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
