INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'advanced', '高三', '人类社会发展的基本规律是？', [{"label": "A", "text": "生产力与生产关系的矛盾运动规律、经济基础与上层建筑的矛盾运动规律"}, {"label": "B", "text": "对立统一规律"}, {"label": "C", "text": "量变质变规律"}, {"label": "D", "text": "否定之否定规律"}], 'A', '人类社会发展的基本规律是生产关系一定要适合生产力状况的规律，上层建筑一定要适合经济基础状况的规律。', 'single_choice', ARRAY['生活与哲学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'advanced', '高三', '关于价值观的叙述，正确的是？', [{"label": "A", "text": "价值观对人生道路的选择没有影响"}, {"label": "B", "text": "价值观对人们认识世界和改造世界具有重要的导向作用"}, {"label": "C", "text": "所有人的价值观都是一样的"}, {"label": "D", "text": "价值观属于社会存在"}], 'B', '价值观对人们认识世界和改造世界、对人生道路的选择具有重要的导向作用；价值观属于社会意识，不同人有不同的价值观。', 'single_choice', ARRAY['生活与哲学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'advanced', '高三', '实现人生价值的根本途径是？', [{"label": "A", "text": "等待机遇"}, {"label": "B", "text": "投身于为人民服务的实践"}, {"label": "C", "text": "依靠父母"}, {"label": "D", "text": "追求个人利益最大化"}], 'B', '实现人生价值的根本途径是投身于为人民服务的实践，在劳动和奉献中创造价值，在个人与社会的统一中实现价值。', 'single_choice', ARRAY['生活与哲学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'advanced', '高三', '下列关于人民群众是历史创造者的叙述，正确的有？（多选）', [{"label": "A", "text": "人民群众是社会物质财富的创造者"}, {"label": "B", "text": "人民群众是社会精神财富的创造者"}, {"label": "C", "text": "人民群众是社会变革的决定力量"}, {"label": "D", "text": "英雄人物是历史的唯一创造者"}, {"label": "E", "text": "要坚持群众观点和群众路线"}], 'ABCE', '人民群众是社会物质财富和精神财富的创造者，是社会变革的决定力量；要坚持群众观点和群众路线；英雄人物对历史发展有重要影响，但不是历史的唯一创造者。', 'multiple_choice', ARRAY['生活与哲学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'advanced', '高三', '______是社会历史的主体，是历史的创造者；______是判断一种价值观是否正确的根本标准。', NULL, '人民群众,是否符合社会发展规律和最广大人民的根本利益', '人民群众是社会历史的主体；是否符合社会发展规律和最广大人民的根本利益是判断价值观正确与否的根本标准。', 'fill_blank', ARRAY['生活与哲学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'advanced', '高三', '人生的真正价值在于对______的贡献；要在______与______的统一中实现价值。', NULL, '社会,个人,社会', '人生的真正价值在于对社会的贡献，要在个人与社会的统一中实现价值。', 'fill_blank', ARRAY['生活与哲学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'advanced', '高三', '真理是标志主观与客观相符合的哲学范畴，是人们对客观事物及其规律的正确反映；真理是具体的、有条件的，不存在绝对真理。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], 'B', '真理是具体的、有条件的，任何真理都有自己适用的条件和范围；但真理又是客观的，就真理的内容而言，真理具有绝对性，绝对真理和相对真理是辩证统一的。', 'true_false', ARRAY['生活与哲学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'advanced', '高三', '论述如何运用矛盾分析法分析和解决实际问题。', NULL, '①坚持一分为二的观点：全面地看问题，既要看到矛盾的主要方面，也要看到矛盾的次要方面。②坚持具体问题具体分析：根据不同事物的不同矛盾，采取不同的解决方法，这是马克思主义活的灵魂。③坚持两点论与重点论的统一：既要抓住主要矛盾和矛盾的主要方面，又要兼顾次要矛盾和矛盾的次要方面。④把握矛盾的普遍性和特殊性的辩证关系：把马克思主义普遍原理与中国具体实际相结合。⑤善于分析矛盾的特殊性：区分不同性质的矛盾，采取不同的解决方法。', '运用矛盾分析法需要坚持一分为二、具体问题具体分析、两点论与重点论统一、把握普遍性与特殊性关系。', 'short_answer', ARRAY['生活与哲学'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'beginner', '高三', '党的二十大报告指出，从现在起，中国共产党的中心任务就是团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以______全面推进中华民族伟大复兴。', [{"label": "A", "text": "中国式现代化"}, {"label": "B", "text": "西方现代化模式"}, {"label": "C", "text": "传统工业化道路"}, {"label": "D", "text": "粗放式发展"}], 'A', '党的二十大报告明确指出，以中国式现代化全面推进中华民族伟大复兴是中国共产党的中心任务。', 'single_choice', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'beginner', '高三', '中国式现代化的本质要求包括：坚持中国共产党领导，坚持中国特色社会主义，实现高质量发展，发展全过程人民民主，丰富人民精神世界，实现全体人民______，促进人与自然和谐共生，推动构建人类命运共同体，创造人类文明新形态。', [{"label": "A", "text": "共同富裕"}, {"label": "B", "text": "平均富裕"}, {"label": "C", "text": "同步富裕"}, {"label": "D", "text": "同等富裕"}], 'A', '中国式现代化的本质要求之一是实现全体人民共同富裕，不是平均富裕、同步富裕或同等富裕。', 'single_choice', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'beginner', '高三', '我国发展新的历史方位是？', [{"label": "A", "text": "社会主义初级阶段"}, {"label": "B", "text": "中国特色社会主义进入了新时代"}, {"label": "C", "text": "新民主主义社会"}, {"label": "D", "text": "共产主义社会"}], 'B', '党的十九大报告指出，中国特色社会主义进入了新时代，这是我国发展新的历史方位。', 'single_choice', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'beginner', '高三', '关于全过程人民民主的叙述，正确的是？', [{"label": "A", "text": "只有选举时才体现民主"}, {"label": "B", "text": "是全链条、全方位、全覆盖的民主"}, {"label": "C", "text": "只存在于政治领域"}, {"label": "D", "text": "与西方民主没有区别"}], 'B', '全过程人民民主是最广泛、最真实、最管用的社会主义民主，是全链条、全方位、全覆盖的民主。', 'single_choice', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'beginner', '高三', '下列关于中国式现代化的叙述，正确的有？（多选）', [{"label": "A", "text": "是人口规模巨大的现代化"}, {"label": "B", "text": "是全体人民共同富裕的现代化"}, {"label": "C", "text": "是物质文明和精神文明相协调的现代化"}, {"label": "D", "text": "是人与自然和谐共生的现代化"}, {"label": "E", "text": "是走和平发展道路的现代化"}], 'ABCDE', '中国式现代化具有五个方面的中国特色：人口规模巨大、全体人民共同富裕、物质文明和精神文明相协调、人与自然和谐共生、走和平发展道路。', 'multiple_choice', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'beginner', '高三', '党的二十大报告指出，中国式现代化是______的现代化，是______的现代化。', NULL, '中国共产党领导,社会主义现代化', '中国式现代化是中国共产党领导的社会主义现代化，既有各国现代化的共同特征，更有基于自己国情的中国特色。', 'fill_blank', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'beginner', '高三', '新时代中国特色社会主义思想明确坚持和发展中国特色社会主义，总任务是实现社会主义现代化和中华民族伟大复兴，在全面建成小康社会的基础上，分两步走在本世纪中叶建成______的社会主义现代化强国。', NULL, '富强民主文明和谐美丽', '总任务是实现社会主义现代化和中华民族伟大复兴，分两步走在本世纪中叶建成富强民主文明和谐美丽的社会主义现代化强国。', 'fill_blank', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'beginner', '高三', '共同富裕是全体人民同步富裕、同等富裕，意味着所有人的收入和生活水平完全一样。', [{"label": "A", "text": "正确"}, {"label": "B", "text": "错误"}], 'B', '共同富裕是全体人民共同富裕，是人民群众物质生活和精神生活都富裕，不是少数人的富裕，也不是整齐划一的平均主义，不是同步富裕、同等富裕。', 'true_false', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'beginner', '高三', '简述中国式现代化的中国特色。', NULL, '中国式现代化具有五个方面的中国特色：①是人口规模巨大的现代化；②是全体人民共同富裕的现代化；③是物质文明和精神文明相协调的现代化；④是人与自然和谐共生的现代化；⑤是走和平发展道路的现代化。', '中国式现代化的五个特色包括人口规模巨大、共同富裕、两个文明协调、人与自然和谐共生、和平发展道路。', 'short_answer', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'intermediate', '高三', '关于总体国家安全观的叙述，正确的是？', [{"label": "A", "text": "只关注军事安全"}, {"label": "B", "text": "以人民安全为宗旨，以政治安全为根本"}, {"label": "C", "text": "只关注经济安全"}, {"label": "D", "text": "只关注国土安全"}], 'B', '总体国家安全观以人民安全为宗旨，以政治安全为根本，以经济安全为基础，以军事、科技、文化、社会安全为保障，以促进国际安全为依托。', 'single_choice', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'intermediate', '高三', '关于新发展格局的叙述，正确的是？', [{"label": "A", "text": "完全放弃国际市场"}, {"label": "B", "text": "以国内大循环为主体、国内国际双循环相互促进"}, {"label": "C", "text": "只发展沿海经济"}, {"label": "D", "text": "只依靠出口拉动经济"}], 'B', '新发展格局是以国内大循环为主体、国内国际双循环相互促进的发展格局，不是封闭的国内循环，而是更加开放的国内国际双循环。', 'single_choice', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'intermediate', '高三', '关于一带一路倡议的叙述，正确的是？', [{"label": "A", "text": "是中国主导的地缘政治工具"}, {"label": "B", "text": "是合作共建、互利共赢的开放平台"}, {"label": "C", "text": "只对中国有利"}, {"label": "D", "text": "排斥其他国家参与"}], 'B', '一带一路倡议是合作共建、互利共赢的开放平台，秉持共商共建共享原则，不是地缘政治工具，欢迎所有感兴趣的国家参与。', 'single_choice', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'intermediate', '高三', '关于共同富裕的叙述，正确的是？', [{"label": "A", "text": "共同富裕就是平均主义"}, {"label": "B", "text": "共同富裕是一个长远目标，需要一个过程"}, {"label": "C", "text": "共同富裕就是劫富济贫"}, {"label": "D", "text": "共同富裕只关注物质富裕"}], 'B', '共同富裕是一个长远目标，需要一个过程，对其长期性、艰巨性、复杂性要有充分估计，不是平均主义，也不是劫富济贫。', 'single_choice', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'intermediate', '高三', '下列关于全面从严治党的叙述，正确的有？（多选）', [{"label": "A", "text": "是新时代党的建设的鲜明主题"}, {"label": "B", "text": "关系党的先进性和纯洁性"}, {"label": "C", "text": "关系人心向背"}, {"label": "D", "text": "关系国家和民族的兴衰"}, {"label": "E", "text": "只需要抓领导干部"}], 'ABCD', '全面从严治党是新时代党的建设的鲜明主题，关系党的先进性纯洁性、人心向背、国家和民族兴衰；全面从严治党面向全体党员。', 'multiple_choice', ARRAY['时事政治'], 'ai_generated', '');
