INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'intermediate', '高三', '简述为什么中国式现代化是走和平发展道路的现代化。', NULL, '①中华民族历来是爱好和平的民族，和平融入了中华民族的血脉中；②中国现代化建设需要和平的国际环境；③中国式现代化打破了现代化等于西方化的迷思，为广大发展中国家独立自主迈向现代化提供了全新选择；④中国不走殖民掠夺的老路，不走国强必霸的歪路，坚定站在历史正确的一边、站在人类文明进步的一边；⑤中国坚持互利共赢的开放战略，推动构建人类命运共同体。', '中国式现代化走和平发展道路，源于中华民族爱好和平的传统、现代化建设的需要、对历史教训的总结和推动构建人类命运共同体的担当。', 'short_answer', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
VALUES ('politics', '16-18', 'advanced', '高三', '关于中国式现代化和西方现代化的叙述，正确的是？', [{"label": "A", "text": "中国式现代化是照搬西方现代化模式"}, {"label": "B", "text": "中国式现代化打破了现代化等于西方化的迷思"}, {"label": "C", "text": "西方现代化是唯一正确的现代化道路"}, {"label": "D", "text": "所有国家都必须走西方现代化道路"}], 'B', '中国式现代化打破了现代化等于西方化的迷思，展现了现代化的另一幅图景，拓展了发展中国家走向现代化的路径选择。', 'single_choice', ARRAY['时事政治'], 'ai_generated', '');
INSERT INTO questions (subject, age_group, difficulty, grade, content, options, correct_answer, explanation, type, tags, source, batch_id)
